local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>Uraaagh—</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5071_50710101_3_dialog_content = "...",
  ui_story_5071_50710101_4_dialog_content = "Argh... *batuk*",
  ui_story_5071_50710101_5_dialog_content = "Tidak...",
  ui_story_5071_50710101_6_dialog_content = "Aku dengar dia membunuh semua orang!",
  ui_story_5071_50710101_7_dialog_content = "Dia satu-satunya orang yang berhasil keluar hidup-hidup dari <color=#FFB400>Pit</color>. Itu pasti benar.",
  ui_story_5071_50710101_8_dialog_content = "Aku tidak percaya dengan apa yang aku dengar. Dia bahkan membunuh saudara kandungnya sendiri untuk mendapatkan kekuasaan...",
  ui_story_5071_50710101_9_dialog_content = "Kita... Apakah kita benar-benar bisa meninggalkan masa depan Umbraton pada orang seperti ini?",
  ui_story_5071_50710101_10_dialog_content = "...",
  ui_story_5071_50710101_11_dialog_content = "Lalu, sekarang...",
  ui_story_5071_50710101_12_dialog_content = "Apa kamu...",
  ui_story_5071_50710101_13_dialog_content = "<size=50>... bahagia?</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5071_50710101_15_dialog_content = "!",
  ui_story_5071_50710101_16_dialog_content = "Semua yang mengambil bentuk bayangan berisiko dilahap oleh bayangan.",
  ui_story_5071_50710101_17_dialog_content = "Masa lalu bukanlah satu-satunya hal yang ditutupi oleh bayangan, 'kan, saudaraku?",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  ui_story_5071_50710101_19_dialog_content = "Ayah, ini aku, Bethel.",
  ui_story_5071_50710101_20_dialog_content = "Masuk.",
  ui_story_5071_50710101_21_dialog_content = "Ayah, aku sudah—",
  ui_story_5071_50710101_22_dialog_content = "...",
  ui_story_5071_50710101_23_dialog_content = "Apakah kamu baik-baik saja, Ayah? Aku belum pernah melihatmu selelah ini...",
  ui_story_5071_50710101_24_dialog_content = "Haha, kuncinya adalah moderasi, tidak peduli seberapa suka kamu pada anggur yang enak. Saya rasa saya sudah pada usia di mana saya harus berhati-hati tentang hal-hal seperti itu.",
  ui_story_5071_50710101_25_dialog_content = "Tolong jangan meremehkan hal itu seperti itu.",
  ui_story_5071_50710101_26_dialog_content = "Anggap saja itu sebagai lelucon. Mari kita bicara tentangmu.",
  ui_story_5071_50710101_27_dialog_content = "Tentu. Saya sudah siap untuk perjalanan.",
  ui_story_5071_50710101_28_dialog_content = "Jalan menuju Teluk Twin Pavilions telah diperbaiki dan diamankan dengan cukup baik sehingga penampakan Eclipsite menjadi jarang.",
  ui_story_5071_50710101_29_dialog_content = "Tapi, tetap buka mata untuk apa yang tidak bisa dilihat oleh Bayangan kita.",
  ui_story_5071_50710101_30_dialog_content = "Tentu saja, gadisku, saya percaya kamu akan menangani pertemuan dengan \"klien\" di sana dengan sempurna.",
  ui_story_5071_50710101_31_dialog_content = "Aku tidak akan mengecewakanmu, Ayah.",
  ui_story_5071_50710101_32_dialog_content = "Bethel, sebagai pemimpin guild, satu-satunya kewajibanmu adalah kepada Umbraton, bukan kepada seseorang.",
  ui_story_5071_50710101_33_dialog_content = "Ayah...",
  ui_story_5071_50710101_34_dialog_content = "Baiklah, aku juga harus pergi. Biar aku antar kamu keluar.",
  ui_story_5071_50710101_35_dialog_content = "...",
  ui_story_5071_50710101_36_dialog_content = "Sebuah guild yang bangkit dari bayangan untuk terbang bebas di langit...",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>Mimpi kamu</color>... Apakah sudah menjadi kenyataan?",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5071_50710101_39_dialog_content = "Jangan salah paham, saya mencium aroma gosip di udara!",
  ui_story_5071_50710101_40_dialog_content = "Hmm?",
  ui_story_5071_50710101_41_dialog_content = "Halo, saya Brandy, reporter untuk The Daily Scoop!",
  ui_story_5071_50710101_42_dialog_content = "May Apa pendapat Anda tentang <color=#FFB400>Cloudrover Airship</color> berukuran super besar yang dibangun oleh Cloudrover Guild?",
  ui_story_5071_50710101_43_dialog_content = "Tidak ada komentar.",
  ui_story_5071_50710101_44_dialog_content = "Itu adalah pemogokan yang cepat. Para taipan ini sekeras kerang untuk dibuka.",
  ui_story_5071_50710101_45_dialog_content = "Tapi lihat, siapa ini—",
  ui_story_5071_50710101_46_dialog_content = "PlayerName! Di sini, di sini!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5071_50710101_48_dialog_content = "Apakah kamu diundang untuk <color=#FFB400>peluncuran perdana</color> hari ini, PlayerName? Bagaimana kalau kita bicara di pesawat?",
  ui_story_5071_50710101_49_dialog_content = "Rasanya familiar.",
  ui_story_5071_50710101_50_dialog_content = "Meskipun teknologi yang digunakan di pesawat ini berbeda dari Colossi, ini masih merupakan kapal besar yang mampu terbang.",
  ui_story_5071_50710101_51_dialog_content = "Terasa mengesankan.",
  ui_story_5071_50710101_52_dialog_content = "Saya hanya pernah melihat airship yang lebih kecil sebelumnya. Saya tidak tahu jika Lady Sheol telah membuat airship besar yang cukup untuk membawa seluruh guild-nya...",
  ui_story_5071_50710101_53_dialog_content = "Airship Cloudrover ini adalah puncak dari semua airship, tapi tidak sebesar Soroz Anda, bukan, PlayerName?",
  ui_story_5071_50710101_54_dialog_content = "Tidak, tapi... Dalam hal ukuran, mungkin masih sebesar Eulogoz, tempat mereka mengadakan konser sebelumnya.",
  ui_story_5071_50710101_55_dialog_content = "Ah, sekarang aku paham judul berita besok!",
  ui_story_5071_50710101_56_dialog_content = "\"Caelestite mengumumkan: Kapal Udara Cloudrover tidak sebanding dengan Soroz!\"",
  ui_story_5071_50710101_57_dialog_content = "T-Tunggu, kenapa kamu memelintir kata-kataku seperti itu?",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>Bzz—Bzz—</color>",
  ui_story_5071_50710101_59_dialog_content = "Jangan takut bahaya atau kegagalan. Kegigihan akan berubah menjadi keberuntungan!",
  ui_story_5071_50710101_60_dialog_content = "Sudah lama sekali, teman-teman tersayang! Bagaimana kabar kalian semua?",
  ui_story_5071_50710101_61_dialog_content = "Bukankah itu... Goldie, idola yang saat ini sangat populer di Umbraton? Persekutuan Cloudrover tetap mengesankan jika mereka bisa membuatnya hadir!",
  ui_story_5071_50710101_62_dialog_content = "Tidak tahu? Lady Sheol, pemimpin dari Guild Cloudrover, dialah yang membuatnya terkenal!",
  ui_story_5071_50710101_63_dialog_content = "Persekutuan Cloudrover bahkan telah mencelupkan tangannya ke dalam industri hiburan? Berapa banyak industri yang terlibat oleh Lady Sheol?",
  ui_story_5071_50710101_64_dialog_content = "Siapa yang peduli tentang idola atau pesawat terbang? Semuanya hanya trik saja... Alasan satu-satunya aku di sini adalah karena Shadowlord yang hadir.",
  ui_story_5071_50710101_65_dialog_content = "Tenang saja, semuanya. Upacara akan segera dimulai!",
  ui_story_5071_50710101_66_dialog_content = "Sampai saat itu, saya ingin membawakan single baru untukmu—",
  ui_story_5071_50710101_67_dialog_content = "<size=45>Mimpi Dalam Jangkauan!</size>",
  ui_story_5071_50710101_68_dialog_content = "Mohon berhasrat untuk menunggang angin dan menyentuh langit bersama saya segera!",
  ui_story_5071_50710101_69_dialog_content = "♪ Di langit yang tak terbatas, awan menciptakan harapan, seperti mimpi yang terbit di atas cakrawala seperti matahari pagi ♪",
  ui_story_5071_50710101_70_dialog_content = "♪ Melebarkan sayapmu, terbang ke langit, dan sentuh cahaya yang cemerlang ♪",
  ui_story_5071_50710101_71_dialog_content = "(Itu Goldie untukmu, huh? Semua yang dibutuhkan adalah nyanyiannya untuk menenangkan semua penumpang yang marah itu. Mereka bahkan mengangguk mengikuti irama lagunya sekarang.)",
  ui_story_5071_50710101_72_dialog_content = "(Masih... Jika Goldie ada di sini, maka klub penggemar yang berteriak-teriak itu juga harus ada di sini untuk merusak gendang telingaku, bukan?)",
  ui_story_5071_50710101_73_dialog_content = "(Saya tidak mengenali siapa pun yang diundang Lady Sheol ke kapal udara...)",
  ui_story_5071_50710101_74_dialog_content = "Dia di sini! Dia di sini! Shadowlord ada di sini! Ayo pergi—",
  ui_story_5071_50710101_75_dialog_content = "(Shadowlord juga ada di sini? Ini pasti acara spesial setelah semua...)",
  ui_story_5071_50710101_76_dialog_content = "Tepat waktu seperti biasa, Shadowlord. Satu menit lagi dan kamu akan melewatkan pemotongan pita.",
  ui_story_5071_50710101_77_dialog_content = "Membuat masuk pada waktu yang tepat saat menghadiri acara seperti ini adalah rahasia yang saya pelajari dari Anda, Lady Sheol.",
  ui_story_5071_50710101_78_dialog_content = "Shadowlord! Saya sangat senang melihatmu di acara yang begitu gembira ini!",
  ui_story_5071_50710101_79_dialog_content = "Shadowlord sayang, apakah kamu masih ingat aku?",
  ui_story_5071_50710101_80_dialog_content = "Shadowlord, beberapa waktu lalu aku meminta pertemuan pribadi denganmu. Apakah kamu sudah sempat membaca undanganku?",
  ui_story_5071_50710101_81_dialog_content = "Shadowlord! Jangan lupakan aku! Shadowlord—",
  ui_story_5071_50710101_82_dialog_content = "Wanita dan pria sekalian, Shadowlord telah memutuskan untuk bertemu dengan setiap orang di antara kalian di pesawat terbang hari ini.",
  ui_story_5071_50710101_83_dialog_content = "Tentu saja, hanya mereka yang telah meminta audiensi dengannya jauh-jauh hari yang diberikan kehormatan seperti itu.",
  ui_story_5071_50710101_84_dialog_content = "Tapi untuk saat ini, mari kita semua fokus pada penyanyi wanita kita yang luar biasa dan penampilannya yang penuh semangat.",
  ui_story_5071_50710101_85_dialog_content = "Sejujurnya, aku tidak pernah tahu bahwa bertemu dengan Shadowlord memerlukan begitu banyak aturan.",
  ui_story_5071_50710101_86_dialog_content = "...",
  ui_story_5071_50710101_87_dialog_content = "Maafkan saya, saya belum sempat memperkenalkan diri dengan benar. Saya adalah Hanstie, pemimpin Continental Guild. Ini adalah kunjungan pertama saya ke sini, dan saya tidak terbiasa dengan formalitas Umbraton. Mohon maaf jika saya mengganggu kesenangan siapa pun dalam perayaan ini.",
  ui_story_5071_50710101_88_dialog_content = "Lihat... Bukankah itu Ms. Hanstie dari Guild Continental? Saya dengar dia tidak pernah muncul di mana pun! Lady Sheol memang sangat karismatik... atau ini karisma dari Shadowlord?",
  ui_story_5071_50710101_89_dialog_content = "Persekutuan Kontinental? Ada guild seperti itu di Umbraton?",
  ui_story_5071_50710101_90_dialog_content = "Continental Guild telah mulai berbisnis di kota-kota kecil di luar Umbraton dalam beberapa tahun terakhir. Meskipun baru saja mendirikan pijakan di Umbraton, momentum perkembangannya tidak boleh dianggap enteng!",
  ui_story_5071_50710101_91_dialog_content = "Sungguh suatu kehormatan bisa memiliki kehadiran Anda, Nyonya Hanstie.",
  ui_story_5071_50710101_92_dialog_content = "Persekutuan Cloudrover telah mengundang setiap pemimpin guild terkemuka di Umbraton untuk acara ini. Bagaimana mungkin saya melewatkan kesempatan seperti ini?",
  ui_story_5071_50710101_93_dialog_content = "Lebih lagi, ketika aku mendengar bahwa Shadowlord yang terkenal akan muncul, aku tahu aku harus berada di sini.",
  ui_story_5071_50710101_94_dialog_content = "Ah, kamu pasti Lady Sheol, pemimpin dari <color=#FFB400>Cloudrover Guild</color> dan sosok yang hanya bisa saya pandang ke atas.",
  ui_story_5071_50710101_95_dialog_content = "Anda bercanda, Ms. Hanstie.",
  ui_story_5071_50710101_96_dialog_content = "Jaringan <color=#FFB400>Guild Kontinental</color> meresap di seluruh Astra. Langit dan tanah bisa dan memang berkoeksistensi.",
  ui_story_5071_50710101_97_dialog_content = "Pesawatmu cukup mengesankan, harus kuakui.",
  ui_story_5071_50710101_98_dialog_content = "Ini adalah kehormatan bagi Cloudrover Guild mendapatkan dukungan dari Nyonya Hanstie.",
  ui_story_5071_50710101_99_dialog_content = "Nah, Shadowlord, bolehkah saya berbicara dengan Anda secara pribadi?",
  ui_story_5071_50710101_100_dialog_content = "Maafkan saya, Ny. Hanstie—",
  ui_story_5071_50710101_101_dialog_content = "Saya sedang berbicara dengan Shadowlord, gurita kecil yang lucu milikku.",
  ui_story_5071_50710101_102_dialog_content = "...",
  ui_story_5071_50710101_103_dialog_content = "Saya akan mempertimbangkan permintaan Anda dengan teliti, Nyonya Hanstie.",
  ui_story_5071_50710101_104_dialog_content = "Baiklah kalau begitu. Saya sangat menantikan balasan Anda.",
  ui_story_5071_50710101_105_dialog_content = "Atur waktu pertemuan antara saya dan sang lady, Kleken.",
  ui_story_5071_50710101_106_dialog_content = "...Baiklah, Tuanku.",
  ui_story_5071_50710101_107_dialog_content = "(Tunggu, Shadowlord melanggar aturannya sendiri untuk wanita flamboyan itu?)",
  ui_story_5071_50710101_108_dialog_content = "Berapa lama lagi kamu akan melamun di pojok, PlayerName?",
  ui_story_5071_50710101_109_dialog_content = "S-Salam, Shadowlord! Semua orang begitu sibuk tadi sehingga saya tidak sempat menyapa lebih awal.",
  ui_story_5071_50710101_110_dialog_content = "Ayo, giliran kita untuk naik ke panggung.",
  ui_story_5071_50710101_111_dialog_content = "Hah?",
  ui_story_5071_50710101_112_dialog_content = "Saya harap semua orang menyukai lagu itu! Selanjutnya, kita sambut—",
  ui_story_5071_50710101_113_dialog_content = "Shadowlord Istvan, pemimpin Guild Cloudrover, Lady Sheol, dan PlayerName, tamu kehormatan Astra, yang akan memotong pita bersama-sama!",
  ui_story_5071_50710101_114_dialog_content = "Aku tidak tahu mereka akan mengadakan upacara seperti ini...",
  ui_story_5071_50710101_115_dialog_content = "Tidak apa-apa, sayang, jangan gugup. Cukup potong pita dengan gunting di tanganmu.",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>Snip!</color>",
  ui_story_5071_50710101_117_dialog_content = "Airship Cloudrover dibiayai dan dibangun oleh Lady Sheol dari Cloudrover Guild, sebuah kapal super yang menggabungkan pariwisata, belanja, rekreasi, dan resor dalam satu tempat.",
  ui_story_5071_50710101_118_dialog_content = "Mulai sekarang, Aurorian biasa seperti saya bisa bermain, berbelanja, dan hidup di langit seperti Caelestite!",
  ui_story_5071_50710101_119_dialog_content = "Setelah peluncuran hari ini, kapal udara akan mengelilingi Umbraton dan mengadakan pertunjukan kembang api di atas kota di malam hari. Semakin saya pikirkan, semakin keren rasanya!",
  ui_story_5071_50710101_120_dialog_content = "Tapi jangan hanya terpaku pada pemandangan dan lupa semua kejadian di kapal!",
  ui_story_5071_50710101_121_dialog_content = "Selain bertemu dan menyapa dengan saya dan pemutaran khusus dari Alleywood Umbraton, kapal udara juga akan menjadi tuan rumah lelang udara paling transparan dan nyaman yang pernah ada!",
  ui_story_5071_50710101_122_dialog_content = "Jadi, mari kita semua mulai hitung mundurnya sekarang!",
  ui_story_5071_50710101_123_dialog_content = "Tiga-",
  ui_story_5071_50710101_124_dialog_content = "Dua-",
  ui_story_5071_50710101_125_dialog_content = "Satu!",
  ui_story_5071_50710101_126_dialog_content = "Pesawat Cloudrover...",
  ui_story_5071_50710101_127_dialog_content = "<size=50>Terbang!</size>",
  ui_story_5071_50710101_128_dialog_content = "Oh! Itu terbang sekarang. Benar-benar terbang!",
  ui_story_5071_50710101_129_dialog_content = "Kamu begitu mudah terkesan. Bukan seperti kamu belum pernah naik pesawat sebelumnya. Ketika aku di Lumopolis, aku melihat ini terjadi setiap hari.",
  ui_story_5071_50710101_130_dialog_content = "Meskipun Lumopolis bagus, pulau itu sama sekali tidak bisa bergerak. Bagaimanapun, saya sangat mengagumi kecerdasan Lady Sheol dalam berinvestasi.",
  ui_story_5071_50710101_131_dialog_content = "Memang mata yang tajam.",
  ui_story_5071_50710101_132_dialog_content = "Tapi apapun yang bisa terbang ke langit...",
  ui_story_5071_50710101_X132_dialog_content = "Harus turun pada akhirnya.",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>Di suite mewah dari Airship Cloudrover</color>",
  ui_story_5071_50710201_2_dialog_content = "Yang Terhormat Shadowlord, saya sangat berterima kasih akhirnya kita memiliki kesempatan untuk bertemu hari ini...",
  ui_story_5071_50710201_3_dialog_content = "Terima kasih atas bantuanmu yang sangat besar, akhirnya anakku bisa mewujudkan keinginannya untuk bersekolah di Lumopolis!",
  ui_story_5071_50710201_4_dialog_content = "Haha, itu berita yang menarik.",
  ui_story_5071_50710201_5_dialog_content = "Putramu sangat cerdas dan memiliki ide-ide sendiri. Kerja kerasnya membawa dia sampai ke titik ini.",
  ui_story_5071_50710201_6_dialog_content = "Namun, kamu tampak khawatir?",
  ui_story_5071_50710201_7_dialog_content = "A-Aku hanya khawatir bahwa para bangsawan dan anak-anak mereka akan mengganggunya karena statusnya...",
  ui_story_5071_50710201_8_dialog_content = "Astaga, apa yang aku katakan... Shadowlord, mohon maafkan aku telah berbicara hal yang tak masuk akal.",
  ui_story_5071_50710201_9_dialog_content = "Sangat wajar untuk khawatir tentang hal itu. Putra Anda sangat berbakat...",
  ui_story_5071_50710201_10_dialog_content = "Saya sangat menantikan kepulangannya dengan selamat dan mendirikan sekolah Umbraton lebih dari siapa pun.",
  ui_story_5071_50710201_11_dialog_content = "Aku berjanji semua kekhawatiranmu tidak akan pernah terjadi.",
  ui_story_5071_50710201_12_dialog_content = "Mendengar Anda mengatakan itu membuat hatiku terasa ringan seperti bulu, tuanku!",
  ui_story_5071_50710201_13_dialog_content = "Saya membawa beberapa botol anggur dari kebun anggur keluarga kami. Tolong terima sebagai tanda rasa terima kasih kami, serta permintaan maaf kami karena telah mengambil banyak waktu Anda...",
  ui_story_5071_50710201_14_dialog_content = "Tidak masalah. Sampai jumpa.",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>Di atas Pesawat Cloudrover, di acara jabat tangan Goldie</color>",
  ui_story_5071_50710201_16_dialog_content = "Terima kasih atas dukunganmu yang tak pernah berhenti, PlayerName!",
  ui_story_5071_50710201_17_dialog_content = "Aku tidak akan mengecewakanmu, dan aku akan terus membuat musik yang bagus!",
  ui_story_5071_50710201_18_dialog_content = "Jangan sebut itu! Kamu benar-benar memiliki koneksi khusus dengan langit, bukan? Lagu hari ini juga—",
  ui_story_5071_50710201_19_dialog_content = "Hei! Bukankah kita hanya seharusnya mendapatkan satu menit dengan Goldie? Kamu sudah melebihi waktu yang ditentukan!",
  ui_story_5071_50710201_20_dialog_content = "Maaf, PlayerName. Jangan lupa untuk mengunjungi saya di kantor saat Anda memiliki waktu!",
  ui_story_5071_50710201_21_dialog_content = "Goldie! Goldie! Kami juga ingin mengobrol denganmu sedikit lebih lama!",
  ui_story_5071_50710201_22_dialog_content = "Dalam sekejap, Goldie telah mengubah begitu banyak orang menjadi penggemarnya...",
  ui_story_5071_50710201_23_dialog_content = "Sepertinya semua teman lama saya cukup sibuk sekarang... Kurasa aku harus berjalan-jalan sendiri.",
  ui_story_5071_50710201_24_dialog_content = "Pak, apakah Anda masih ingat saya? S-saya dulu tinggal di sebelah rumah Anda!",
  ui_story_5071_50710201_25_dialog_content = "Kamu tidak ada di rumah saat orang tuamu meninggal... Aku juga ikut serta membantu biaya pemakaman mereka...",
  ui_story_5071_50710201_26_dialog_content = "Terima kasih atas bantuan yang begitu besar dalam memberikan mereka tempat peristirahatan yang damai.",
  ui_story_5071_50710201_27_dialog_content = "Y-Ya, tapi... tapi aku butuh bantuanmu sekarang lebih dari sebelumnya!",
  ui_story_5071_50710201_28_dialog_content = "Berkat kamu, aku bisa membuka sejumlah toko serba ada. Bisnisku tidak sebanding dengan Cloudrover Guild, tapi cukup sukses di sini.",
  ui_story_5071_50710201_29_dialog_content = "Sayangnya, toko-toko terdekat belakangan ini bekerja sama untuk menghancurkan bisnis saya. Saya sudah di ambang kebangkrutan...",
  ui_story_5071_50710201_30_dialog_content = "Saya tidak tahu apa lagi yang harus saya lakukan, Tuanku. Tolong bantu saya...",
  ui_story_5071_50710201_31_dialog_content = "Kamu ingin aku membantu kamu menyingkirkan mereka?",
  ui_story_5071_50710201_32_dialog_content = "A-Apakah itu diterima?",
  ui_story_5071_50710201_33_dialog_content = "Mengapa tidak bergabung saja dengan guild? Selama Anda beroperasi sesuai dengan peraturan, mereka akan memberikan perlindungan yang cukup besar.",
  ui_story_5071_50710201_34_dialog_content = "A... Aku diberitahu bahwa bergabung dengan guild memerlukan biaya keanggotaan yang besar...",
  ui_story_5071_50710201_35_dialog_content = "Bagaimana kamu bisa tahu jika kamu tidak pernah melangkah melewati pintu mereka untuk mencari tahu kebenaran?",
  ui_story_5071_50710201_36_dialog_content = "Sudah kuduga! Penjahat-penjahat itu telah berbohong padaku sejak awal!",
  ui_story_5071_50710201_37_dialog_content = "Lalu... Bolehkah saya mungkin bergabung dengan guild Anda?",
  ui_story_5071_50710201_38_dialog_content = "Saya bukan pemimpin guild, tetapi saya bisa memberitahu Anda bahwa pintunya selalu terbuka untuk siapa saja.",
  ui_story_5071_50710201_39_dialog_content = "Percayalah padaku. Kamu hanya akan menyesal tidak melakukannya lebih cepat.",
  ui_story_5071_50710201_40_dialog_content = "Oh, terima kasih! Terima kasih banyak, Shadowlord! Mulai sekarang, saya akan selalu mendukung Anda... dan juga keputusan guild!",
  ui_story_5071_50710201_41_dialog_content = "Orang-orang yang telah menguburkan orang tuamu seharusnya sudah meninggalkan dunia ini sejak lama. Tampaknya, pria itu dan aku memiliki \"hobi\" yang serupa.",
  ui_story_5071_50710201_42_dialog_content = "Bukan itu intinya, Kleken. Katakan padanya apa yang harus dia lakukan selanjutnya.",
  ui_story_5071_50710201_43_dialog_content = "Sangat baik, Shadowlord.",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>Di luar bioskop Pesawat Cloudrover</color>",
  ui_story_5071_50710201_45_dialog_content = "Hmm, \"Sebuah kisah muda berdasarkan kisah nyata, 'Chasing Alleywood' sedang diputar dengan satu tiket tersisa.\"",
  ui_story_5071_50710201_46_dialog_content = "Apakah ini karya terbaru dari Lilica? Ini menjelaskan mengapa saya tidak mendengar kabar darinya dalam waktu yang cukup lama...",
  ui_story_5071_50710201_47_dialog_content = "Yah, aku tidak punya kegiatan lain, jadi mungkin aku harus menunjukkan dukungan!",
  ui_story_5071_50710201_48_dialog_content = "Permisi, saya ingin membeli tiket terakhir untuk \"Chasing Alleywood,\" tolong!",
  ui_story_5071_50710201_49_dialog_content = "H-Hah? Brandy mengambil tiket terakhir untuk dirinya sendiri!",
  ui_story_5071_50710201_50_dialog_content = "Apa masalah dengan anak ini? Kenapa dia tidak mau bicara?",
  ui_story_5071_50710201_51_dialog_content = "Apakah dia tersesat? Kenapa orang tuanya tidak mencarinya?",
  ui_story_5071_50710201_52_dialog_content = "Anak siapa ini?",
  ui_story_5071_50710201_53_dialog_content = "Apa sih dengan semua orang-orang di sana itu? Ada acara lain?",
  ui_story_5071_50710201_54_dialog_content = "*terisak*",
  ui_story_5071_50710201_55_dialog_content = "Hah? Anak kecil?",
  ui_story_5071_50710201_56_dialog_content = "Waaah—",
  ui_story_5071_50710201_57_dialog_content = "H-Hei! Kenapa dia tiba-tiba menarikku seperti ini?",
  ui_story_5071_50710201_58_dialog_content = "Mereka pasti keluarga... Pemuda malang itu tidak ragu-ragu untuk berlari kepadanya.",
  ui_story_5071_50710201_59_dialog_content = "Apakah kamu kakak laki-laki dari anak ini? Bagaimana bisa kamu meninggalkannya sendirian seperti itu? Lihatlah wajahnya yang miskin dan menangis!",
  ui_story_5071_50710201_60_dialog_content = "Kamu harus lebih berhati-hati mulai sekarang!",
  ui_story_5071_50710201_61_dialog_content = "...",
  ui_story_5071_50710201_62_dialog_content = "...",
  ui_story_5071_50710201_63_dialog_content = "Hmm... May Siapa kamu?",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>*perut keroncongan*</color>",
  ui_story_5071_50710201_65_dialog_content = "Aku... Aku sangat lapar...",
  ui_story_5071_50710201_66_dialog_content = "Apa kabar, Shadowlord?",
  ui_story_5071_50710201_67_dialog_content = "Markis? Saya pikir akhir-akhir ini Anda menghabiskan seluruh waktu Anda membaca bersama cucu perempuan Anda di perkebunan Lumopolis Anda.",
  ui_story_5071_50710201_68_dialog_content = "Haha, kalau aku tidak datang, aku khawatir sebuah kelompok tertentu dan \"reformasi\" mereka akan merampok semua yang aku miliki di sini di Umbraton.",
  ui_story_5071_50710201_69_dialog_content = "Beritahu saya, dengan biaya keanggotaan yang sangat tinggi yang dikenakan oleh guild, bagaimana mereka bisa tidak mampu makan sepuasnya akhir-akhir ini?",
  ui_story_5071_50710201_70_dialog_content = "Haha, itu cerita yang berbeda, pak.",
  ui_story_5071_50710201_71_dialog_content = "Guild kecil milikmu itu ditutup karena melanggar peraturan guild.",
  ui_story_5071_50710201_72_dialog_content = "Selama koreksi dilakukan dan... praktik yang meragukan dihentikan, diperbolehkan untuk dibuka kembali.",
  ui_story_5071_50710201_73_dialog_content = "Selain itu, sebagian besar biaya keanggotaan yang dibayar diserahkan ke Lumopolis sebagai \"pajak properti\" seperti yang disepakati.",
  ui_story_5071_50710201_74_dialog_content = "Sisanya dihabiskan untuk pemeliharaan rutin guild—",
  ui_story_5071_50710201_75_dialog_content = "Kata-kata penipu Anda sangat mengingatkan saya pada putri angkat Anda. Jika saya tidak tahu lebih baik, saya akan bilang dia bisa dianggap sebagai salah satu dari anak kandung Anda.",
  ui_story_5071_50710201_76_dialog_content = "Mengapa kamu repot-repot menemui saya jika kamu sudah mendengar penjelasan dari pemimpin guild?",
  ui_story_5071_50710201_77_dialog_content = "Berhenti dengan sandiwara ini, Istvan...",
  ui_story_5071_50710201_78_dialog_content = "Kamu tahu apa yang dibutuhkan Umbraton untuk mempertahankan kemakmurannya saat ini, bukan?",
  ui_story_5071_50710201_79_dialog_content = "Ini sama seperti yang dibutuhkan oleh Geng Istvan pada awal pembentukannya, ingat?",
  ui_story_5071_50710201_80_dialog_content = "Tanganmu jauh lebih kotor daripada orang lain di kapal udara ini. Apakah kamu benar-benar berpikir kamu bisa mencuci dosa-dosamu?",
  ui_story_5071_50710201_81_dialog_content = "\"Reformasi\" ini hanya akan menjadi kehancuranmu!",
  ui_story_5071_50710201_82_dialog_content = "Haha, begitukah?",
  ui_story_5071_50710201_83_dialog_content = "Yah, aku agak tak sabar ingin mengetahuinya...",
  ui_story_5071_50710201_84_dialog_content = "Bagaimana sebuah reformasi untuk menempatkan Umbraton di jalur yang benar bisa merugikan saya.",
  ui_story_5071_50710201_85_dialog_content = "Nyam, nyam, glek...",
  ui_story_5071_50710201_86_dialog_content = "Hei, pelan-pelan atau kamu bisa tersedak!",
  ui_story_5071_50710201_87_dialog_content = "Dua ayam panggang, empat pizza, dan lima potong kue... Kapan terakhir kali kamu makan?",
  ui_story_5071_50710201_88_dialog_content = "Mengunyah, mengunyah... Sudah tiga jam sejak makanan terakhirku... Aku tadi sangat lapar...",
  ui_story_5071_50710201_89_dialog_content = "Kamu merasa lapar hanya setelah tiga jam?",
  ui_story_5071_50710201_90_dialog_content = "Aku... Aku jadi gugup saat berada di sekitar orang asing... sangat gugup sampai-sampai semua energiku terkuras, jadi...",
  ui_story_5071_50710201_91_dialog_content = "Um... Aku pasti akan membayar kembali untuk makanan ini!",
  ui_story_5071_50710201_92_dialog_content = "T-Tapi bisakah kamu... membantuku mencari Nona Sheol?",
  ui_story_5071_50710201_93_dialog_content = "Nona... Sheol?",
  ui_story_5071_50710201_94_dialog_content = "N-Namaku Vergil. Aku salah satu karyawan Nona Sheol...",
  ui_story_5071_50710201_95_dialog_content = "Saya... Saya tidak menyadari bahwa Lady Sheol mempekerjakan anak-anak untuk bekerja untuknya.",
  ui_story_5071_50710201_96_dialog_content = "T-T-T-Tolong jangan salah paham! Akulah yang memintanya untuk mempekerjakanku!",
  ui_story_5071_50710201_97_dialog_content = "Saya tidak tahu persis apa yang sedang terjadi, tetapi saya bisa merasakan kehadiran Nona Sheol di dekat sini—",
  ui_story_5071_50710201_98_dialog_content = "Tahan di sana!",
  ui_story_5071_50710201_99_dialog_content = "Target terlihat!",
  ui_story_5071_50710201_100_dialog_content = "Anjing penjaga ada di sini!",
  ui_story_5071_50710201_101_dialog_content = "Serangan anjing!",
  ui_story_5071_50710201_102_dialog_content = "Bukankah itu... tempat Shadowlord bertemu dengan orang-orang?",
  ui_story_5071_50710302_1_dialog_content = "Apakah Anda baik-baik saja, Bu?",
  ui_story_5071_50710302_2_dialog_content = "Aku... Aku baik-baik saja. Terima kasih atas bantuanmu.",
  ui_story_5071_50710302_3_dialog_content = "Patty, Patsy, bisakah kalian beri tahu saya apa yang sedang terjadi?",
  ui_story_5071_50710302_4_dialog_content = "Kami anjing-anjing adalah pengawal terbaik!",
  ui_story_5071_50710302_5_dialog_content = "Tidak ada yang bisa lewat kami kecuali mereka memiliki reservasi!",
  ui_story_5071_50710302_6_dialog_content = "Kamu memang anak anjing yang setia, tapi jangan sampai membuat keributan besar lain kali.",
  ui_story_5071_50710302_7_dialog_content = "Kamu mungkin akan jatuh jika terus membuat keributan seperti itu.",
  ui_story_5071_50710302_8_dialog_content = "Anjing-anjing tidak pernah menunjukkan rasa takut!",
  ui_story_5071_50710302_9_dialog_content = "Tapi bukan ide yang baik untuk mengganggu pertemuan Shadowlord di dalam.",
  ui_story_5071_50710302_10_dialog_content = "Jangan mengganggu Shadowlord... Bahkan kita tahu itu!",
  ui_story_5071_50710302_11_dialog_content = "Jadi, nyonya, pemimpin guild mana yang Anda ikuti? Mohon maafkan saya, tetapi saya tidak ingat mengirimkan undangan kepada seseorang seperti Anda.",
  ui_story_5071_50710302_12_dialog_content = "Kemiripannya sangat mencolok... Ketika saya melihat lebih dekat, kalian hampir sama persis...",
  ui_story_5071_50710302_13_dialog_content = "…?",
  ui_story_5071_50710302_14_dialog_content = "L... Nona Sheol!",
  ui_story_5071_50710302_15_dialog_content = "Vergil? Apa yang kamu lakukan di sini? Bukankah aku sudah menyuruhmu menungguku di lelang udara?",
  ui_story_5071_50710302_16_dialog_content = "A-Aku tadi sangat lapar, jadi aku pergi mencari makan... Tapi ada begitu banyak orang di luar sampai-sampai aku tersesat.",
  ui_story_5071_50710302_17_dialog_content = "Tapi orang baik ini menyelamatkanku, dan dia bahkan membayar makanan besar dan lezat untukku makan!",
  ui_story_5071_50710302_18_dialog_content = "Haha... Itu bukan apa-apa.",
  ui_story_5071_50710302_19_dialog_content = "Kamu sudah berteman dengan PlayerName? Aku pikir Vergil kecil tidak berbicara dengan orang asing.",
  ui_story_5071_50710302_20_dialog_content = "Itu karena... PlayerName mengeluarkan aroma barang antik entah kenapa, dan itu benar-benar membuatku merasa tenang...",
  ui_story_5071_50710302_21_dialog_content = "Nah, itu benar. Kamu bisa menyebut PlayerName sebagai barang antik yang baru dibuat.",
  ui_story_5071_50710302_22_dialog_content = "PlayerName... Tunggu, jangan bilang kau adalah Caelestite legendaris?!",
  ui_story_5071_50710302_23_dialog_content = "Kamu belum menjawab pertanyaan saya, Madam. Siapa kamu dan apa yang kamu lakukan di sini?",
  ui_story_5071_50710302_24_dialog_content = "Sebagai pengingat yang ramah, keamanan untuk kapal ini tidak lebih lembut dari anak anjing Shadowlord.",
  ui_story_5071_50710302_25_dialog_content = "Saya... Saya adalah Yvonne, seorang penulis. Cross Street Publishing House mengundang saya ke sini sebagai tamu spesial.",
  ui_story_5071_50710302_26_dialog_content = "Mohon maafkan saya karena telah membuat keributan tadi. Saya tidak menyadari bahwa saya memerlukan reservasi untuk bertemu Shadowlord di pesawat hari ini.",
  ui_story_5071_50710302_27_dialog_content = "Yvonne... Tunggu, kamu maksud THE Ms. Yvonne, penulis terkenal di dunia?!",
  ui_story_5071_50710302_28_dialog_content = "... Saya heran seseorang sebegitu muda seperti kamu mengenal karya-karya saya, mengingat saya tidak menulis apa-apa yang baru dalam beberapa tahun.",
  ui_story_5071_50710302_29_dialog_content = "Tulisan Ms. Yvonne adalah bukti dari masa lalu Umbraton. Setiap orang yang melek huruf di kota telah membaca karya Anda.",
  ui_story_5071_50710302_30_dialog_content = "Tapi kamu jarang menampakkan dirimu di depan umum, jadi kenapa hari ini...",
  ui_story_5071_50710302_31_dialog_content = "Saya jauh lebih muda saat itu, dan selalu khawatir atau sibuk dengan satu hal atau lainnya. Sekarang setelah saya lebih tua, saya menjadi sedikit lebih berani dari sebelumnya.",
  ui_story_5071_50710302_32_dialog_content = "Jika bukan karena ini, saya tidak akan pernah naik pesawat udara ini sendirian untuk naskah yang belum selesai saya tulis.",
  ui_story_5071_50710302_33_dialog_content = "Manuskrip?",
  ui_story_5071_50710302_34_dialog_content = "Setelah buku terakhir saya mendapatkan ulasan yang sangat buruk, saya yakin bahwa saya tidak akan pernah menulis lagi.",
  ui_story_5071_50710302_35_dialog_content = "Namun tidak lama kemudian, aku bertemu dan berteman dengan seorang <color=#FFB400>seniman</color> tertentu yang berbagi sejumlah kisah menarik denganku.",
  ui_story_5071_50710302_36_dialog_content = "Cerita-cerita ini, yang berdasarkan pada kejadian nyata, jauh lebih menarik daripada karya fiksi yang paling hati-hati sekalipun. Saya hampir tidak bisa tidur setelah mendengarnya!",
  ui_story_5071_50710302_37_dialog_content = "Aku berpikir bahwa cerita-cerita ini pantas mendapatkan lebih dari sekedar menjadi debu di masa lalu Umbraton yang telah lama terlupakan. Atas desakan temanku, aku mengambil pena lagi...",
  ui_story_5071_50710302_38_dialog_content = "Cerita yang sedang saya kerjakan ini sangat menakjubkan, tetapi saya khawatir bahwa beberapa detail masih kurang. Untuk alasan ini, saya berusaha untuk mewawancarai Shadowlord hari ini.",
  ui_story_5071_50710302_39_dialog_content = "... Meskipun ada bahaya, dan ketidakpastian saya tentang apakah dia akan berbagi pengetahuannya dengan penulis gagal seperti saya.",
  ui_story_5071_50710302_40_dialog_content = "Bahaya...? Apa yang begitu berbahaya tentang menulis cerita?",
  ui_story_5071_50710302_41_dialog_content = "Jika buku ini diterbitkan, semua orang akan mengetahui alasan di baliknya.",
  ui_story_5071_50710302_42_dialog_content = "Saya lihat kamu membuat pembaca kamu penasaran seperti yang dilakukan oleh penulis yang baik.",
  ui_story_5071_50710302_43_dialog_content = "Lady Sheol, mungkin saya melampaui batas dengan bertanya, tetapi bisakah Anda memperkenalkan saya kepada Shadowlord? Saya berjanji tidak akan mengambil banyak waktu berharganya!",
  ui_story_5071_50710302_44_dialog_content = "Nah, jika saya menolak untuk membantu, lingkaran sastra di Umbraton akan menuduh kami, para pengusaha, sebagai pengejar uang yang tidak berbudaya lagi.",
  ui_story_5071_50710302_45_dialog_content = "Bukan berarti saya tidak pernah peduli tentang kritik semacam itu... Namun, saya adalah penggemar berat buku-buku Anda!",
  ui_story_5071_50710302_46_dialog_content = "Dan ini bukan pertama kalinya Shadowlord membuat pengecualian hari ini. Tolong beri saya satu menit.",
  ui_story_5071_50710302_47_dialog_content = "Ehem, Nyonya Yvonne? Apakah tidak masalah jika Vergil mendapatkan tanda tangan dari Anda? Dia terlalu malu untuk bertanya sendiri...",
  ui_story_5071_50710302_48_dialog_content = "Tanda tangan? Itu bukan sesuatu yang harus kamu malukan, nak! Aku hanya bersyukur bahwa kamu menikmati karyaku sebanyak ini. Aku hanya memiliki beberapa kertas kosong di tangan, apakah itu menjadi masalah?",
  ui_story_5071_50710302_49_dialog_content = "N... Tidak sama sekali!!",
  ui_story_5071_50710302_50_dialog_content = "Ini, khusus untukmu. Meski tidak banyak, tapi jika kita berkesempatan bertemu lagi, aku ingin memberikanmu salinan dari...",
  ui_story_5071_50710302_51_dialog_content = "Itu mengingatkanku! Buku mana dari bukuku yang paling kamu suka?",
  ui_story_5071_50710302_52_dialog_content = "A-a-a-a-aku... Aku benar-benar menikmati \"Nyonya Red Mercury\"!",
  ui_story_5071_50710302_53_dialog_content = "Judul itu...",
  ui_story_5071_50710302_54_option_content = "Terdengar akrab...",
  ui_story_5071_50710302_55_dialog_content = "Saya pikir saya punya salinan cerita itu tentang Colossus!",
  ui_story_5071_50710302_56_option_content = "Tentu saja, aku belum pernah mendengar tentang itu...",
  ui_story_5071_50710302_57_dialog_content = "Ceritanya... tentang seorang pemimpin guild yang cantik, namun dingin dan misterius bernama Mrs. Red Mercury.",
  ui_story_5071_50710302_58_dialog_content = "Demi cinta, dia meninggalkan status bangsawannya tanpa ragu dan pergi ke Umbraton.",
  ui_story_5071_50710302_59_dialog_content = "Tapi setelah suaminya meninggal, dia mengambil alih beberapa guild kecil, dan diam-diam membalas dendam cintanya yang telah gugur.",
  ui_story_5071_50710302_60_dialog_content = "Apakah kamu sedang membicarakan tentang \"Nyonya Red Mercury\"? Saya juga suka buku itu.",
  ui_story_5071_50710302_61_dialog_content = "I-Itu benarkah? Aku sangat senang kau menyukainya...",
  ui_story_5071_50710302_62_dialog_content = "Saya telah mengirim kabar, Nona Yvonne. Kita akan segera mendengar balasannya.",
  ui_story_5071_50710302_63_dialog_content = "Itu adalah berita yang sangat baik... Terima kasih banyak, Nona Sheol!",
  ui_story_5071_50710302_64_dialog_content = "Takdir bisa menjadi hal yang aneh, dan aku tidak ingin mengatakan apa-apa sebelumnya... Tapi kamu sangat mirip dengan Lady <color=#FFB400>Melissa</color>.",
  ui_story_5071_50710302_65_dialog_content = "Kamu kenal Melissa? Jadi bukunya benar-benar...",
  ui_story_5071_50710302_66_dialog_content = "Ya. Karakter Mrs. Red Mercury didasarkan pada Lady Melissa, seorang tokoh nyata.",
  ui_story_5071_50710302_67_dialog_content = "Lady Melissa? Siapa itu?",
  ui_story_5071_50710302_68_dialog_content = "Kamu juga tidak tahu, ya? Jika saya harus menebak... Lady Melissa ini adalah seseorang yang sangat penting bagi Lady Sheol.",
  ui_story_5071_50710302_69_dialog_content = "...",
  ui_story_5071_50710302_70_dialog_content = "Ny. Yvonne, saya benar-benar berterima kasih atas deskripsi setia Anda tentang dirinya dalam buku ini, memberi saya kesempatan untuk merasakan karismanya.",
  ui_story_5071_50710302_71_dialog_content = "Saya diberitahu bahwa anak Melissa diculik dan diracuni oleh musuh-musuhnya... Tapi sekarang saya melihat bahwa dia mewarisi keteguhan hati ibunya.",
  ui_story_5071_50710302_72_dialog_content = "Saya jarang menyesal tentang sesuatu, tapi sekarang saya berpikir ulang tentang tidak pernah berinvestasi di bisnis penerbitan. Mungkin saya bisa bertemu denganmu lebih awal.",
  ui_story_5071_50710302_73_dialog_content = "Aku yakin kita akan punya banyak kesempatan untuk bertemu di masa depan, asalkan kamu tidak keberatan dengan keingintahuan ku tentang masa lalu.",
  ui_story_5071_50710302_74_dialog_content = "Aku suka cerita, terutama ketika itu tentang dia...",
  ui_story_5071_50710302_75_dialog_content = "Selain itu, aku sangat tertarik untuk menerbitkan buku yang sedang kamu tulis sekarang.",
  ui_story_5071_50710302_76_dialog_content = "I-Itu akan menjadi...",
  ui_story_5071_50710302_77_dialog_content = "Saya tidak bisa membayangkan betapa wajah Lady Melissa bercahaya kegembiraan jika dia bisa melihat betapa suksesnya putrinya.",
  ui_story_5071_50710302_78_dialog_content = "Kemurahan hati Anda terhadap pelanggan sangat patut dipuji, Lady Sheol. Saya hanya berharap Anda tahu betapa banyak masalah yang ditimbulkan bagi rekan kerja Anda.",
  ui_story_5071_50710302_79_dialog_content = "Kita sudah mendapatkan balasan?",
  ui_story_5071_50710302_80_dialog_content = "Jadi ini adalah Ms. Yvonne yang terkenal?",
  ui_story_5071_50710302_81_dialog_content = "Shadowlord telah setuju untuk audiensi. Silakan ke sini.",
  ui_story_5071_50710302_82_dialog_content = "!!!",
  ui_story_5071_50710302_83_dialog_content = "Saya sangat berterima kasih atas bantuanmu, Lady Sheol!",
  ui_story_5071_50710302_84_dialog_content = "Kamu sendiri yang bilang itu adalah takdir. Saya menantikan untuk berbicara tentang pekerjaan masa lalumu setelah pertemuanmu dengan Shadowlord.",
  ui_story_5071_50710302_85_dialog_content = "Ini akan menjadi kehormatan saya.",
  ui_story_5071_50710302_86_dialog_content = "...",
  ui_story_5071_50710302_87_dialog_content = "Kenapa kamu hanya berdiri di sana, sayang PlayerName?",
  ui_story_5071_50710302_88_dialog_content = "Atau...",
  ui_story_5071_50710302_89_dialog_content = "Apakah kamu tiba-tiba merasa tertarik dengan masa laluku?",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>Sekitar sepuluh tahun lalu</color>",
  ui_story_5071_50710401_2_dialog_content = "Lihat! Apakah itu orang-orang dari koalisi yang mengakhiri Darkover Crisis?",
  ui_story_5071_50710401_3_dialog_content = "Mereka bergerak menuju Lumopolis... Apakah mereka bisa jadi ksatria dari Lumopolis?!",
  ui_story_5071_50710401_4_dialog_content = "Semua Ksatria Lumopolis mengenakan seragam yang berkilau, sedangkan orang-orang ini tampak gelap dan abu-abu. Kemungkinan besar mereka berasal dari Umbraton.",
  ui_story_5071_50710401_5_dialog_content = "Bukankah Eclipsite telah meratakan Umbraton dengan tanah sejak lama? Masih ada orang yang tinggal di sana?",
  ui_story_5071_50710401_6_dialog_content = "Saya dengar banyak dari mereka yang selamat berkat bantuan yang mereka terima dari Lumopolis.",
  ui_story_5071_50710401_7_dialog_content = "Sangat menyenangkan memiliki kekuatan yang begitu besar yang menjaga mereka. Tidak peduli seburuk apa pun situasinya, master mereka akan membantu mereka begitu mereka mulai mengibaskan ekornya.",
  ui_story_5071_50710401_8_dialog_content = "Ssst! Jangan berisik! Orang-orang ini bisa membunuh Eclipsite dengan tamparan, jadi kamu harus hati-hati.",
  ui_story_5071_50710401_9_dialog_content = "Tunggu! Bukankah itu Sheol? Hei, apa yang sedang kamu lakukan?!",
  ui_story_5071_50710401_10_dialog_content = "Daripada bersikap sinis, kenapa tidak langsung saja bicara dengan mereka? Mereka adalah pahlawan yang telah mengalahkan Eclipsites, setelah semua.",
  ui_story_5071_50710401_11_dialog_content = "Sheol... Meskipun kamu telah membantu kami mengusir Eclipsite berkali-kali, orang-orang ini mungkin lebih berbahaya daripada Eclipsite. Hati-hati dan coba untuk tidak terbunuh!",
  ui_story_5071_50710401_12_dialog_content = "Santai saja. Saya rasa tidak ada yang punya masalah dengan uang dan memanfaatkannya, kan?",
  ui_story_5071_50710401_13_dialog_content = "Berhenti di sana! Siapa kamu?",
  ui_story_5071_50710401_14_dialog_content = "Jangan terlalu tegang. Lihat, aku bukan Eclipsite.",
  ui_story_5071_50710401_15_dialog_content = "Saya hanya ingin mengingatkan semua orang bahwa di sini panas dan kering, jadi jika kamu merasa haus, ada air es gratis di toko saya!",
  ui_story_5071_50710401_16_dialog_content = "Sayangnya, tidak ada yang namanya makan siang gratis di dunia ini.",
  ui_story_5071_50710401_17_dialog_content = "Tidak ada makan siang gratis tapi airnya gratis. Tentu saja, jika yang kamu inginkan adalah makan siang, saya juga menjualnya!",
  ui_story_5071_50710401_18_dialog_content = "Kotak kombo kalajengking gurun panggang otentik, sesuatu yang tidak akan Anda dapatkan di Umbraton.",
  ui_story_5071_50710401_19_dialog_content = "Jangan repot-repot. Kita harus pergi.",
  ui_story_5071_50710401_20_dialog_content = "Haruskah kamu tidak beristirahat setelah menempuh perjalanan sejauh ini? Kamu mungkin tidak merasa lelah, tapi bagaimana dengan para prajurit?",
  ui_story_5071_50710401_21_dialog_content = "Heheh, mereka bilang orang-orang di sini dikenal karena temperamen mereka yang meledak-ledak, tapi kamu tampaknya adalah pengecualian.",
  ui_story_5071_50710401_22_dialog_content = "Semua yang ingin air dan makanan yang enak, ikuti aku!",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>Sheol melepas sarung tangannya dan mulai melambai-lambaikannya, berusaha sebaik mungkin untuk menarik perhatian semua orang di sekitarnya.</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>Di bawah sinar matahari yang terang, sebuah bekas luka ramping di lengan bawah Sheol memancarkan cahaya merah, tampak seperti lidah camilan yang berkelip-kelip.</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>Istvan mata mencari asal suara yang dia dengar dan mulai mengamati penampilan gadis ini dengan cermat.</color>",
  ui_story_5071_50710401_26_dialog_content = "Tunggu! A-Apakah itu kamu, Melissa? Tidak... Kamu...",
  ui_story_5071_50710401_27_dialog_content = "Sheol?!",
  ui_story_5071_50710401_28_dialog_content = "Aku tidak ingat memberitahumu namaku.",
  ui_story_5071_50710401_29_dialog_content = "Meski aku cukup dikenal di sekitar sini. Jadi, apa yang sedang terjadi...",
  ui_story_5071_50710401_30_dialog_content = "Akhirnya aku menemukanmu!",
  ui_story_5071_50710401_31_dialog_content = "Haha, aku pikir aku tak akan pernah punya kesempatan untuk memenuhi janji ini lagi...",
  ui_story_5071_50710401_32_dialog_content = "Ayo! Mari kita kembali ke Umbraton, rumah sejatimu!",
  ui_story_5071_50710401_33_dialog_content = "(Tampaknya penduduk desa benar tentang betapa orang-orang dari Umbraton yang suka berubah-ubah dan tidak masuk akal.)",
  ui_story_5071_50710401_34_dialog_content = "Yah, aku memang ingin mengunjungi Umbraton, tapi aku masih harus menjaga toko...",
  ui_story_5071_50710401_35_dialog_content = "Dan lihat waktu sekarang... Aku harus kembali ke sana sekarang!",
  ui_story_5071_50710401_36_dialog_content = "Tolong, jangan salah paham—",
  ui_story_5071_50710401_37_dialog_content = "Tidak boleh mendekat satu inci pun!",
  ui_story_5071_50710402_1_dialog_content = "Hahah, sesuai harapan dari putri Melissa! Meski tanpa latihan yang layak, kemampuan bertarungmu tidak bisa diabaikan.",
  ui_story_5071_50710402_2_dialog_content = "Apa yang kamu inginkan? Aku hanya seorang pedagang kecil, apa nilaiku bagi kamu?",
  ui_story_5071_50710402_3_dialog_content = "Maafkan saya karena tidak menjelaskan hal-hal dengan lebih jelas. Kenyataannya, saya sedang membantu seorang teman lama menemukan putrinya yang telah lama hilang.",
  ui_story_5071_50710402_4_dialog_content = "Aku tumbuh besar di gurun. Apa hubunganku dengan Umbraton?",
  ui_story_5071_50710402_5_dialog_content = "Jika saya tidak salah, kamu memiliki tanda kecil berbentuk ular di lenganmu. Benar bukan?",
  ui_story_5071_50710402_6_dialog_content = "Kamu baru saja melihat itu satu detik yang lalu.",
  ui_story_5071_50710402_7_dialog_content = "Ya... Tapi namamu tertulis di pakaian yang kamu kenakan saat kamu menghilang: \"Sheol.\"",
  ui_story_5071_50710402_8_dialog_content = "Melihat dari reaksimu, sepertinya itu juga yang orang lain panggil padamu.",
  ui_story_5071_50710402_9_dialog_content = "Beritahu saya, putri siapa saya?",
  ui_story_5071_50710402_10_dialog_content = "Seorang teman lama saya bernama Lady Melissa.",
  ui_story_5071_50710402_11_dialog_content = "Jika dia benar-benar ibuku, kenapa dia tidak datang sendiri untukku?",
  ui_story_5071_50710402_12_dialog_content = "Karena dia... Meninggal karena sakit sudah lama.",
  ui_story_5071_50710402_13_dialog_content = "Betapa mudahnya.",
  ui_story_5071_50710402_14_dialog_content = "...",
  ui_story_5071_50710402_15_dialog_content = "Aku telah membawa ini sepanjang waktu, berharap bisa memberikannya padamu suatu hari nanti.",
  ui_story_5071_50710402_16_dialog_content = "Ini... emas murni?",
  ui_story_5071_50710402_17_dialog_content = "Ini ditinggalkan untukmu oleh ibumu yang telah tiada. Jika kamu bisa menggunakan Luminatics, maka kamu seharusnya tahu bagaimana menggunakannya.",
  ui_story_5071_50710402_18_dialog_content = "Dan kamu hanya akan memberikannya padaku?",
  ui_story_5071_50710402_19_dialog_content = "Ketika kamu sudah memiliki cukup waktu untuk mempertimbangkan segala hal, temuilah saya di Umbraton.",
  ui_story_5071_50710402_20_dialog_content = "Kamu bisa mengandalkan saya untuk mengambil ini, tetapi tidak selalu datang untuk menemuimu.",
  ui_story_5071_50710402_21_dialog_content = "Saya yakin Anda akan.",
  ui_story_5071_50710402_22_dialog_content = "Sungguh orang yang aneh.",
  ui_story_5071_50710402_23_dialog_content = "Tapi, apakah benar ada yang namanya makan siang gratis?",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_5071_50710402_25_dialog_content = "Memasuki.",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>*Langkah kaki*</color>",
  ui_story_5071_50710402_27_dialog_content = "Sheol?",
  ui_story_5071_50710402_28_dialog_content = "Hahaha, bukankah aku sudah bilang kamu akan datang menemuiku suatu hari nanti? Tapi dari yang aku dengar, kamu sudah cukup lama berada di Umbraton. Apakah kamu sudah terbiasa dengan kehidupan di kota ini?",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>Plak...</color>",
  ui_story_5071_50710402_30_dialog_content = "Tolong lihat.",
  ui_story_5071_50710402_31_dialog_content = "Hmm?",
  ui_story_5071_50710402_32_dialog_content = "Saya lihat geng Istvan yang hebat ini sekarang mencoba-coba di komoditas.",
  ui_story_5071_50710402_33_dialog_content = "Masalahnya adalah kamu tidak tahu kualitas dari apa yang kamu beli.",
  ui_story_5071_50710402_34_dialog_content = "Guild Firefox yang memasokmu berani menipu bangsawan di Lumopolis... Untuk detailnya, semuanya diringkas dalam file ini.",
  ui_story_5071_50710402_35_dialog_content = "Bahkan saya bisa melacaknya dengan cukup mudah, jadi saya pikir Lumo Guard pasti tahu tentang itu.",
  ui_story_5071_50710402_36_dialog_content = "Hanya masalah hari sebelum pemasok \"andal\" Anda itu dilemparkan untuk membusuk di penjara.",
  ui_story_5071_50710402_37_dialog_content = "Ketika Firefox tidak ada lagi, bukan hanya Anda kehilangan pemasok, tetapi Anda juga harus berurusan dengan pelanggan yang marah.",
  ui_story_5071_50710402_38_dialog_content = "Apakah ini sebabnya kamu datang kemari hari ini?",
  ui_story_5071_50710402_39_dialog_content = "Jangan tegang, Shadowlord.",
  ui_story_5071_50710402_40_dialog_content = "Saya di sini bukan untuk menendangmu saat kamu sedang terpuruk, tetapi untuk menawarkan situasi yang sama-sama menguntungkan.",
  ui_story_5071_50710402_41_dialog_content = "Jika kamu tidak keberatan saya mengatakan, kamu para gangster membutuhkan bantuan bisnis profesional.",
  ui_story_5071_50710402_42_dialog_content = "Tentu saja, saya memiliki penawaran spesial eksklusif dengan nama Anda di atasnya.",
  ui_story_5071_50710402_43_dialog_content = "(Aku mengerti. Dia tidak berniat datang kepadaku untuk meminta bantuan, dan bahkan memulai sebuah guild kecil dengan kedua tangannya sendiri di sini di Umbraton...)",
  ui_story_5071_50710402_44_dialog_content = "(Dia tidak ingin saya meremehkan kemampuannya, jadi dia datang kepada saya dengan usulan bisnis yang akan membuat kita sejajar. Apakah itu?)",
  ui_story_5071_50710402_45_dialog_content = "Hahahaha! Baiklah, saya akan menyerahkan pengiriman ini di tanganmu yang cakap, Nona Sheol.",
  ui_story_5071_50710402_46_dialog_content = "Tapi sekarang aku berhutang budi padamu. Katakan apa yang kamu inginkan, dan aku berjanji akan membuatnya menjadi milikmu.",
  ui_story_5071_50710402_47_dialog_content = "Saya selalu percaya satu-satunya yang dapat memenuhi keinginan saya adalah diri saya sendiri.",
  ui_story_5071_50710402_48_dialog_content = "Saya mengerti, maka saya akan terus memegang harapan ini untuk Anda. Jika Anda berubah pikiran, semua yang perlu Anda lakukan adalah mengatakannya.",
  ui_story_5071_50710402_49_dialog_content = "Saya menghargai tawaran itu, tapi saya berharap saya tidak perlu mencairkannya.",
  ui_story_5071_50710402_50_dialog_content = "Bahkan saya terkejut dengan kemiripanmu dengan ibumu, dan bukan hanya dari segi penampilan...",
  ui_story_5071_50710402_51_dialog_content = "Apa... seperti apa dia?",
  ui_story_5071_50710402_52_dialog_content = "Sama seperti dirimu, dia adalah seorang pemimpin guild yang tegas dan bijaksana. Saya tidak memiliki apa-apa kecuali rasa hormat yang sangat tinggi untuknya.",
  ui_story_5071_50710402_53_dialog_content = "Sayangnya, tidak ada jumlah pujian yang bisa membentuk gambaran yang jelas. Aku masih belum bisa memahaminya...",
  ui_story_5071_50710402_54_dialog_content = "Mohon maaf atas gangguannya, Shadowlord!",
  ui_story_5071_50710402_55_dialog_content = "Seperti yang kamu duga, Guild Firefox tidak mau membayar barang-barang kita dari awal! Ini semua salah kita karena tidak menyelidiki mereka lebih teliti!",
  ui_story_5071_50710402_56_dialog_content = "Presiden mereka baru saja ditangkap oleh otoritas Lumopolis... Artinya kita mungkin kehilangan investasi kita dalam kesepakatan ini.",
  ui_story_5071_50710402_57_dialog_content = "Orang-orang kita telah mulai menghubungi guild lain dengan permintaan mendesak. Haruskah kita menyiapkan kontrak untuk mereka?",
  ui_story_5071_50710402_58_dialog_content = "Tidak. Saya sudah menemukan mitra bisnis yang sangat cocok untuk pekerjaan ini. Beritahu mereka untuk menunggu instruksi lebih lanjut.",
  ui_story_5071_50710402_59_dialog_content = "Baik tuan ku!",
  ui_story_5071_50710402_60_dialog_content = "Tunggu, rencana bodoh itu salah kalian? Tapi kalau dipikir-pikir, itu berarti kalian tahu apa yang dilakukan Firefox sejak awal...",
  ui_story_5071_50710402_61_dialog_content = "Tidak perlu lagi meratapi masa lalu. Kita seharusnya merayakan kolaborasi bisnis baru kita, setuju?",
  ui_story_5071_50710402_62_dialog_content = "Tapi jika mereka menemukanmu guild lain, kenapa kamu memilihku? Apakah karena ibuku...",
  ui_story_5071_50710402_63_dialog_content = "Karena Anda, Lady Sheol, jauh lebih berhati-hati dan kooperatif dibandingkan dengan pemimpin guild lainnya yang mengklaim dapat memimpin Guild Umbraton.",
  ui_story_5071_50710402_64_dialog_content = "Prospek bekerja dengan seseorang seperti Anda membuat saya sangat senang.",
  ui_story_5071_50710402_65_dialog_content = "Lalu, untuk sebuah kemitraan yang bahagia.",
  ui_story_5071_50710402_66_dialog_content = "Nah, bagaimana saya harus menyebut guild Anda?",
  ui_story_5071_50710402_67_dialog_content = "Guild Cloudrover.",
  ui_story_5071_50710402_68_dialog_content = "... Sepertinya kamu juga merindukan pulau yang melayang di langit itu.",
  ui_story_5071_50710402_69_dialog_content = "Lumopolis? Itu memang pulau yang menarik, tetapi aku lebih menginginkan versi yang bebas berkelana.",
  ui_story_5071_50710402_70_dialog_content = "Berjalan kemana saja, berdagang dengan bebas... Apa, kamu tidak merasa itu realistis?",
  ui_story_5071_50710402_71_dialog_content = "Tidak sedikit pun. Yang ingin saya katakan—",
  ui_story_5071_50710402_72_dialog_content = "Adalah bahwa aku tak sabar untuk bekerja sama denganmu.",
  ui_story_5071_50710402_73_dialog_content = "(Saya secara tidak sengaja melihat ke dalam kenangan Lady Sheol. Saya belum pernah melihatnya tampak begitu emosional sebelumnya...)",
  ui_story_5071_50710402_74_dialog_content = "Mengapa kamu hanya berdiri di sana, sayang PlayerName?",
  ui_story_5071_50710402_75_dialog_content = "Atau...",
  ui_story_5071_50710402_76_dialog_content = "Apakah kamu tiba-tiba merasa tertarik dengan masa laluku?",
  ui_story_5071_50710402_77_dialog_content = "Aku…",
  ui_story_5071_50710402_78_dialog_content = "Saya bisa melihat mengapa kamu begitu terkejut. Ini juga pertama kalinya saya melihat Lady Sheol sebahagia ini!",
  ui_story_5071_50710402_79_dialog_content = "Karena kamu sangat menyukai Ms. Yvonne, Vergil...",
  ui_story_5071_50710402_80_dialog_content = "Mengapa saya tidak menanamkan uang ke rumah penerbit dan menandatanganinya secara eksklusif?",
  ui_story_5071_50710402_81_dialog_content = "Hah? I-Ini benar-benar baik-baik saja?",
  ui_story_5071_50710402_82_dialog_content = "Dengan syarat bahwa kamu harus menulis buku tentang barang antik untukku terlebih dahulu.",
  ui_story_5071_50710402_83_dialog_content = "A-Aku... Aku akan berusaha sebaik mungkin...",
  ui_story_5071_50710402_84_dialog_content = "Hah? Vergil, kamu sebenarnya—",
  ui_story_5071_50710402_85_dialog_content = "Vergil mungkin masih anak-anak, tetapi dia adalah ahli barang antik yang jujur dan dapat menilai apa saja!",
  ui_story_5071_50710402_86_dialog_content = "I-Itu sebenarnya tidak terlalu mengagumkan...",
  ui_story_5071_50710402_87_dialog_content = "Waktu yang tepat! Saya mengambil tumpukan kertas naskah lebih awal. Bisakah Anda memberi tahu kami siapa pemiliknya, Vergil?",
  ui_story_5071_50710402_88_dialog_content = "Ini adalah jenis kertas tulis yang digunakan semua orang saat ini—",
  ui_story_5071_50710402_89_dialog_content = "Hah? Tunggu sebentar! Ini adalah...",
  ui_story_5071_50710501_1_dialog_content = "Yakin ini naskah Nona Yvonne?",
  ui_story_5071_50710501_2_dialog_content = "Benar! Sejauh yang saya tahu, ini adalah kisah baru yang belum pernah diterbitkan sebelumnya!",
  ui_story_5071_50710501_3_dialog_content = "Tapi halaman-halaman ini terlihat sangat tua. Mengapa belum diterbitkan juga?",
  ui_story_5071_50710501_4_dialog_content = "Ada banyak alasan mengapa penulis tidak dapat menerbitkan karyanya tepat waktu. Juga, lihat beberapa halaman terakhir dari naskah ini: mereka masih cukup baru!",
  ui_story_5071_50710501_5_dialog_content = "Ini mungkin adalah naskah yang hilang untuk cerita terbaru Ms. Yvonne! Ahhh, aku tidak sabar untuk membacanya...",
  ui_story_5071_50710501_6_dialog_content = "Kamu tidak berpikir kita harus mengembalikannya pada pemilik yang sah terlebih dahulu, Vergil?",
  ui_story_5071_50710501_7_dialog_content = "Ahhh, hanya baris pertama dari naskah ini sudah cukup untuk membuatku menangis! Terakhir kali saya membaca salah satu karya Ms. Yvonne, saya tidak lebih tinggi dari bangku dari Longzhou kuno!",
  ui_story_5071_50710501_8_dialog_content = "Apakah benar-benar sebaik itu? Biarkan saya melihat...",
  ui_story_5071_50710501_9_dialog_content = "Di luar gerbang pos Lumopolis terdapat jalan yang dipenuhi dengan batu bata hijau tak terhitung jumlahnya. Di sebuah lapangan terbuka, tumpukan batu putih dapat terlihat.",
  ui_story_5071_50710501_10_dialog_content = "Anak-anak lokal yang sering datang ke sini untuk bermain petak umpet sering dihadapkan oleh seorang pengganggu yang lewat.",
  ui_story_5071_50710501_11_dialog_content = "\"Apa yang kalian pikirkan, monster kecil? Tidak tahukah kalian apa tempat ini sebelumnya?!\"",
  ui_story_5071_50710501_12_dialog_content = "Dengan perutnya yang membuncit, seorang anak berani menjawab, \"Bukankah itu disebut 'Lubang'?\"",
  ui_story_5071_50710501_13_dialog_content = "\"Ya, dan ini sangat berbeda dari klub pertarungan di kota. Apakah kamu punya ide berapa banyak orang yang telah mati di sini?\"",
  ui_story_5071_50710501_14_dialog_content = "Melihat anak-anak tiba-tiba diam, si penggossip semakin bersemangat. \"Seratus orang akan masuk, tetapi hanya satu yang akan bertahan hidup!\"",
  ui_story_5071_50710501_15_dialog_content = "Orang-orang yang suka ikut campur itu benar. Lubang itu selalu menjadi tempat di mana para bangsawan menghibur diri dengan kematian orang lain.",
  ui_story_5071_50710501_16_dialog_content = "Mereka mengikat segala jenis penjahat dengan rantai besi setebal mangkuk seperti binatang dan melemparkannya ke dalam Pit untuk bertarung.",
  ui_story_5071_50710501_17_dialog_content = "Tentu saja, ada mereka yang dengan berani memasuki Pit secara sukarela hanya untuk memenangkan sesuatu untuk dimakan atau untuk diperhatikan oleh seorang bangsawan.",
  ui_story_5071_50710501_18_dialog_content = "Namun, ada juga mereka yang telah ditipu untuk masuk ke The Pit...",
  ui_story_5071_50710501_19_dialog_content = "Jika saya bisa memberi tahu Hakim di Lumopolis bahwa Sheriff Umbraton bersekongkol dengan geng...",
  ui_story_5071_50710501_20_dialog_content = "Dia pasti akan menangani sampah yang hanya peduli tentang menghasilkan uang di atas kehidupan orang lain!",
  ui_story_5071_50710501_21_dialog_content = "Tapi, apakah Hakim benar-benar ada di sini?",
  ui_story_5071_50710501_22_dialog_content = "Tidak, tidak—",
  ui_story_5071_50710501_23_dialog_content = "Berhenti!",
  ui_story_5071_50710501_24_dialog_content = "Tolong beri jalan untukku lewat!",
  ui_story_5071_50710501_25_dialog_content = "Tapi para penjaga mengejar kamu. Apakah kamu seorang penjahat?",
  ui_story_5071_50710501_26_dialog_content = "Tidak, saya bukan... Kamu terlihat seperti juga dari Umbraton, jadi tolong bantu saya!",
  ui_story_5071_50710501_27_dialog_content = "Saya datang untuk mengajukan gugatan ke Lumo Hall of Justice mengenai kesepakatan kotor yang dilakukan oleh beberapa bangsawan di Umbraton, hanya untuk mereka menganiaya saya sebagai balasannya.",
  ui_story_5071_50710501_28_dialog_content = "Saya tidak keberatan masuk penjara, tetapi mereka ingin melemparku ke Dalam Lubang! Mereka ingin membunuhku...",
  ui_story_5071_50710501_29_dialog_content = "Saya tidak bisa percaya Anda mengalahkan saya terlebih dahulu! Jadi Balai Kehakiman juga menerima suap? Atau mungkin seluruh Lumopolis...",
  ui_story_5071_50710501_30_dialog_content = "Kemana kamu pikir kamu akan pergi?!",
  ui_story_5071_50710501_31_dialog_content = "Mereka di sini! Sepertinya aku sudah selesai.",
  ui_story_5071_50710501_32_dialog_content = "Jangan bicara terlalu dini.",
  ui_story_5071_50710501_33_dialog_content = "Hei! Ya, aku bicara padamu. Minggir!",
  ui_story_5071_50710501_34_dialog_content = "Pria ini tidak bisa bertarung sama sekali, jadi apa yang telah dia lakukan hingga sangat salah sehingga mengirimnya ke ajalnya?",
  ui_story_5071_50710501_35_dialog_content = "Dia tidak perlu bertarung. Kita hanya perlu memastikan ada cukup orang. Maukah kamu menggantikan tempatnya?",
  ui_story_5071_50710501_36_dialog_content = "Betapa tidak masuk akal! Mereka tidak berencana untuk membiarkan saya hidup.",
  ui_story_5071_50710501_37_dialog_content = "Lupakan saja. Ini sudah berakhir. Toh, aku juga tidak disukai oleh ayahku, apalagi di luar rumah...",
  ui_story_5071_50710501_38_dialog_content = "Aku akan menggantikannya.",
  ui_story_5071_50710501_39_dialog_content = "Apa? Kamu bahkan tidak kenal saya dan kamu rela mati untuk saya?",
  ui_story_5071_50710501_40_dialog_content = "Saya tahu apa yang saya lakukan.",
  ui_story_5071_50710501_41_dialog_content = "Kamu tampak sangat berpendidikan dan lebih tahu daripada saya tentang cara menyelamatkan Umbraton. Jika saya tidak bisa kembali, berjanjilah padaku...",
  ui_story_5071_50710501_42_dialog_content = "Jaga Umbraton tetap hidup.",
  ui_story_5071_50710501_43_dialog_content = "...",
  ui_story_5071_50710501_44_dialog_content = "Sepertinya ada satu lagi prajurit yang rela berjuang untuk kita hari ini!",
  ui_story_5071_50710501_45_dialog_content = "Hari ini adalah hari keberuntunganmu, pejuang! Jika ada di antara kalian yang bisa mengalahkannya dan hidup untuk menceritakan kisahnya, salah satu bangsawan baik hati ini telah setuju untuk menggandakan hadiahnya!",
  ui_story_5071_50710501_46_dialog_content = "Ahahahaha—",
  ui_story_5071_50710501_47_dialog_content = "Tangkap monster bertanduk itu!",
  ui_story_5071_50710501_48_dialog_content = "...",
  ui_story_5071_50710501_49_dialog_content = "Bunuh dia—!",
  ui_story_5071_50710501_50_dialog_content = "Orang-orang yang telah dilemparkan ke The Pit sudah menjual jiwa mereka kepada setan.",
  ui_story_5071_50710501_51_dialog_content = "Dapatkan mereka! Cepat, kalian orang-orang bodoh yang tak berguna!",
  ui_story_5071_50710501_52_dialog_content = "Jelas bahwa mereka hanya dimanfaatkan oleh bangsawan yang haus darah...",
  ui_story_5071_50710501_53_dialog_content = "Bunuh dia! Kita akan membagi hadiah uang jika kamu melakukannya!",
  ui_story_5071_50710501_54_dialog_content = "Tapi hanya satu dari mereka yang bisa hidup, kan?",
  ui_story_5071_50710501_55_dialog_content = "Aku tidak peduli selama itu bukan iblis bertanduk itu!",
  ui_story_5071_50710501_56_dialog_content = "Kalau begitu, jangan buang waktu lagi. Datang kepadaku!",
  ui_story_5071_50710502_1_dialog_content = "Setiap pukulan brutal disambut dengan raungan dan teriakan dari kerumunan. Satu demi satu, para prajurit di The Pit mulai jatuh.",
  ui_story_5071_50710502_2_dialog_content = "Beberapa penonton melindungi wajah mereka atau mundur ke baris paling belakang di tribun, takut bahwa tinju biru yang menyala berikutnya akan mencapai mereka.",
  ui_story_5071_50710502_3_dialog_content = "Pemuda yang gagah seperti binatang buas dan ganas seperti iblis akhirnya berhenti setelah menjatuhkan lawan terakhirnya. Setelah itu, para penonton akhirnya menghembuskan nafas lega.",
  ui_story_5071_50710502_4_dialog_content = "Dia menang! Dia benar-benar menang meskipun semua orang di Pit menyerangnya!",
  ui_story_5071_50710502_5_dialog_content = "Cederanya cukup serius. Orang-orang itu menyembunyikan senjata dan membuat banyak luka di tubuhnya...",
  ui_story_5071_50710502_6_dialog_content = "Aku menghitung—dia menerima lebih dari seribu tebasan!",
  ui_story_5071_50710502_7_dialog_content = "Seribu luka?!",
  ui_story_5071_50710502_8_dialog_content = "...",
  ui_story_5071_50710502_9_dialog_content = "Bisa kita pergi sekarang?",
  ui_story_5071_50710502_10_dialog_content = "Orang yang kamu lindungi bisa pergi. Sedangkan untukmu...",
  ui_story_5071_50710502_11_dialog_content = "Dengarkanlah...",
  ui_story_5071_50710502_12_dialog_content = "Kau mendengarkan, 'kan?",
  ui_story_5071_50710502_13_dialog_content = "Ahhh! A-Apa...?!",
  ui_story_5071_50710502_14_dialog_content = "Kalian berdua begitu asyik, sampai-sampai benar-benar melupakan aku.",
  ui_story_5071_50710502_15_dialog_content = "Sebanyak apapun aku ingin bergabung denganmu, aku punya urusan mendesak yang harus kuurus.",
  ui_story_5071_50710502_16_dialog_content = "Meski begitu, kamu harus segera mengembalikannya kepada Nyonya Yvonne secepatnya.",
  ui_story_5071_50710502_17_dialog_content = "Oh, dan Vergil, jangan lewatkan tugas lelangmu.",
  ui_story_5071_50710502_18_dialog_content = "Tidak kali ini!",
  ui_story_5071_50710502_19_dialog_content = "Nyonya Yvonne seharusnya sedang bertemu dengan Shadowlord sekarang. Kenapa kita tidak mencarinya di sana?",
  ui_story_5071_50710502_20_dialog_content = "T-Tapi aku baru saja sampai ke bagian yang menarik...",
  ui_story_5071_50710502_21_dialog_content = "T-Tidak bisakah saya membaca sedikit lagi?",
  ui_story_5071_50710502_22_dialog_content = "E-Ehem, baiklah... Tapi hanya sedikit lagi, oke?",
  ui_story_5071_50710502_23_dialog_content = "Oke! Sedikit lagi tidak akan sakit!",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>Di suite mewah Airship Cloudrover</color>",
  ui_story_5071_50710601_2_dialog_content = "Terima kasih telah memberikan kesempatan bertemu dengan saya, Shadowlord yang terhormat. Saya di sini menawarkan rasa hormat tertinggi atas nama Guild Kontinental.",
  ui_story_5071_50710601_3_dialog_content = "Anda adalah Nyonya Hanstie, pemimpin misterius dari Persekutuan Kontinental? Saya ingat itu bukan nama belakang Anda.",
  ui_story_5071_50710601_4_dialog_content = "Aku juga mulai khawatir.",
  ui_story_5071_50710601_5_dialog_content = "... Kau sudah banyak berubah.",
  ui_story_5071_50710601_6_dialog_content = "Kamu pikir begitu? Oh, apakah kamu maksud kakiku?",
  ui_story_5071_50710601_7_dialog_content = "Meskipun saya menghabiskan banyak uang untuk melarikan diri saat Darkover menguasai Umbraton, saya masih bertemu dengan Eclipsites di perjalanan...",
  ui_story_5071_50710601_8_dialog_content = "Tapi itu tidak masalah karena saya tidak akan menyadari manfaat dari kaki cybernetic jika tidak.",
  ui_story_5071_50710601_9_dialog_content = "Haha, memang benar kamu berbeda, lebih optimistis dan tangguh dari sebelumnya.",
  ui_story_5071_50710601_10_dialog_content = "Pasti terjadi, mengingat betapa banyaknya yang telah aku alami.",
  ui_story_5071_50710601_11_dialog_content = "Guild Anda juga cukup mengesankan dan tidak konvensional dalam cara sering melakukan investasi berisiko yang dilarang oleh Umbraton Guild.",
  ui_story_5071_50710601_12_dialog_content = "Heheh, saya melihat bayangan telah mengawasi saya.",
  ui_story_5071_50710601_13_dialog_content = "Tapi Anda jelas tidak memperlakukan saya seperti teman lama. Di sini saya datang dengan niat baik, hanya untuk Anda mencoba merendahkan saya.",
  ui_story_5071_50710601_14_dialog_content = "Kami adalah teman lama, itulah sebabnya saya menginginkan yang terbaik untukmu.",
  ui_story_5071_50710601_15_dialog_content = "Saya tidak begitu mengerti, bukankah <color=#FFB400>Umbratonmu</color> adalah kota yang bebas dan toleran?",
  ui_story_5071_50710601_16_dialog_content = "Kamu jelas bisa membawa kasino besar untuk menghasilkan lebih banyak keuntungan bagi Umbraton dan bahkan dengan mudah melunasi \"pajak properti\" yang besar ke Lumopolis, jadi mengapa kamu tidak melakukannya?",
  ui_story_5071_50710601_17_dialog_content = "Kamu tidak mulai dengan menyembah uang. Dulu, kamu tertarik pada seni dan sastra, selalu dengan pena atau kuas cat di tangan—",
  ui_story_5071_50710601_18_dialog_content = "Aku bukan satu-satunya yang berubah.",
  ui_story_5071_50710601_19_dialog_content = "Aku tidak percaya bahwa orang miskin yang kukenal bisa meraih Tongkat Gembala dan berubah menjadi <color=#FFB400>Istvan</color>.",
  ui_story_5071_50710601_20_dialog_content = "...",
  ui_story_5071_50710601_21_dialog_content = "Kamu benar. Tidak ada yang tetap sama selamanya. Umbraton sedang menjalani reformasi sekarang.",
  ui_story_5071_50710601_22_dialog_content = "Ini bukan Umbratonmu dan juga bukan Umbratonku.",
  ui_story_5071_50710601_23_dialog_content = "Di sini, kamu bisa berdagang dengan bebas, kecuali untuk jenis bawah tanah, kriminal—itu juga adalah mimpi <color=#FFB400>Valon</color>.",
  ui_story_5071_50710601_24_dialog_content = "Kenapa kamu...",
  ui_story_5071_50710601_25_dialog_content = "Betapa tragis... Mengapa ini harus terjadi pada protagonis?",
  ui_story_5071_50710601_26_dialog_content = "Jadi, meskipun setelah mendapatkan audiensi dengan City Lord, dia masih diframing oleh bangsawan dan dilemparkan ke penjara?",
  ui_story_5071_50710601_27_dialog_content = "Tuan Kota Lumopolis tidak pernah ingin mendengar pemikiran protagonis tentang Umbraton. Dia hanya melihat kota itu sebagai hewan peliharaan yang bisa berjuang... Begitu tidak lagi memberinya manfaat, dia kehilangan minat.",
  ui_story_5071_50710601_28_dialog_content = "Kisah dalam buku ini jauh lebih rumit dibandingkan yang sebelumnya... Saya penasaran apa yang akan dilakukan protagonis setelah dia keluar dari penjara?",
  ui_story_5071_50710601_29_dialog_content = "Mungkin kita harus... membaca sedikit lagi?",
  ui_story_5071_50710601_30_dialog_content = "Iya, sedikit lagi!",
  ui_story_5071_50710601_31_dialog_content = "Udara di kuburan terasa lebih dingin dibandingkan di kota, mungkin karena dia telah menghabiskan banyak waktu berdiri di sana.",
  ui_story_5071_50710601_32_dialog_content = "Ketika dia meninggalkan rumah, satu-satunya kata yang dia ucapkan kepada orang tuanya adalah \"Saya pergi sekarang.\" Sekarang, setelah bertahun-tahun, dia gagal mengumpulkan bahkan frasa paling sederhana: \"Saya kembali.\"",
  ui_story_5071_50710601_33_dialog_content = "Langkah kaki perlahan mendekatinya dari belakang. \"Sampaikan urusanmu,\" katanya dengan dingin kepada pengunjung tanpa berbalik.",
  ui_story_5071_50710601_34_dialog_content = "Tak lama kemudian pengunjung itu menjawab: \"Kade... Kamu akhirnya kembali.\"",
  ui_story_5071_50710601_35_dialog_content = "Kade memalingkan kepalanya ke arah orang itu, wajah yang agak familiar. \"Apakah saya mengenalmu?\"",
  ui_story_5071_50710601_36_dialog_content = "Kamu menyelamatkan seseorang di Pit bertahun-tahun yang lalu... Dan orang itu adalah saya.",
  ui_story_5071_50710601_37_dialog_content = "Kamu menderita bertahun-tahun gara-gara saya. Saya tidak bisa begitu saja membelakangi kamu.",
  ui_story_5071_50710601_38_dialog_content = "Jika kamu tidak memiliki tempat untuk kembali, mungkin kamu bisa pulang bersamaku? Aku akan memperlakukanmu seperti saudaraku sendiri!",
  ui_story_5071_50710601_39_dialog_content = "Tapi aku bahkan tidak tahu namamu...",
  ui_story_5071_50710601_40_dialog_content = "Valon. Panggil saja aku Valon.",
  ui_story_5071_50710601_41_dialog_content = "Tak lama kemudian, kedua pemuda itu menemukan minat yang sama...",
  ui_story_5071_50710601_42_dialog_content = "... Aku telah berlatih sejak aku kembali dari Pit.",
  ui_story_5071_50710601_43_dialog_content = "Berlatih cara bermain catur?",
  ui_story_5071_50710601_44_dialog_content = "Luminatics. Saya berharap bisa sekuat Anda suatu hari nanti, sehingga saya juga bisa mendominasi medan perang.",
  ui_story_5071_50710601_45_dialog_content = "Jika itu masalahnya, maka saya ingin menjadi sama terampilnya denganmu dalam bermain catur.",
  ui_story_5071_50710601_46_dialog_content = "Haha, saya tidak tahu kalau kamu juga suka catur. Siapa yang mengajari kamu bermain?",
  ui_story_5071_50710601_47_dialog_content = "Ayahku...",
  ui_story_5071_50710601_48_dialog_content = "Maaf, seharusnya aku tidak bertanya... Tapi mulai sekarang, ayahku bisa menjadi ayahmu juga!",
  ui_story_5071_50710601_49_dialog_content = "Saya yakin Ayah cukup menyukai kamu untuk mengadopsi kamu! Dengan begitu, kita bisa menjadi saudara kandung yang sebenarnya!",
  ui_story_5071_50710601_50_dialog_content = "...",
  ui_story_5071_50710601_51_dialog_content = "Jadi tolong jangan menolak, sama seperti saat aku tidak menolak ketika kamu menggantikan tempatku di Arena Mematikan.",
  ui_story_5071_50710601_52_dialog_content = "Aku hanya khawatir. Tidak ada yang berubah tentang Umbraton sejak terakhir kali aku di sini. Tidak ada sama sekali.",
  ui_story_5071_50710601_53_dialog_content = "... Aku juga sudah memikirkan hal itu. Jika Umbraton terus menunggu bantuan dari Lumopolis, itu tidak akan pernah berubah.",
  ui_story_5071_50710601_54_dialog_content = "Kita perlu mengandalkan kekuatan kita sendiri jika kita ingin membasmi serangga penghisap darah yang menguras kehidupan dari kota kita.",
  ui_story_5071_50710601_55_dialog_content = "Saya bertanya-tanya siapa yang memilih nama \"Umbraton\" untuk tempat ini? Siapa mereka untuk memutuskan bahwa kita harus selalu hidup dalam bayangan? Masa depan adalah milik kita untuk ditentukan!",
  ui_story_5071_50710601_56_dialog_content = "Masa depan... Ya, masa depan kota ini seharusnya bebas dan bersatu—sebuah masa depan di mana tidak ada lagi yang bisa mengendalikan kita!",
  ui_story_5071_50710601_57_dialog_content = "Aku berharap hal yang sama, tapi membebaskan diri kita dari kegelapan masa lalu bukanlah sesuatu yang bisa dilakukan dalam semalam...",
  ui_story_5071_50710601_58_dialog_content = "Mungkin kita harus belajar untuk hidup damai dengan mereka, bahkan menjadi bagian dari mereka untuk beberapa waktu...",
  ui_story_5071_50710601_59_dialog_content = "Tidak. Kita harus bebas dari pengaruh buruk mereka, dan itu harus segera! Tanpa kompromi.",
  ui_story_5071_50710601_60_dialog_content = "Hah?",
  ui_story_5071_50710601_61_dialog_content = "Ada apa?",
  ui_story_5071_50710601_62_dialog_content = "Ada yang mendengar di pintu... Haruskah kita melakukan sesuatu tentang itu?",
  ui_story_5071_50710601_63_dialog_content = "Ah... Itu hanya <color=#FFB400>Ava</color>, putri dari salah satu teman ayahku. Jangan khawatir, dia juga temanku.",
  ui_story_5071_50710601_64_dialog_content = "Kami bukan hanya teman, kamu tahu!",
  ui_story_5071_50710601_65_dialog_content = "Kade selalu terkesan dengan inisiatif Valon. Suatu hari, Valon memutuskan untuk mendekati ayahnya, pemimpin dari sebuah guild pedagang, untuk mendapatkan dukungan...",
  ui_story_5071_50710601_66_dialog_content = "Tidak akan pernah!",
  ui_story_5071_50710601_67_dialog_content = "Tapi kenapa tidak? Kita sedang berusaha melakukan hal yang benar!",
  ui_story_5071_50710601_68_dialog_content = "Geng-geng yang haus darah dan guild yang tidak berperilaku lebih baik dari mereka... Mereka adalah kanker bagi seluruh Umbraton!",
  ui_story_5071_50710601_69_dialog_content = "Jika kita bertindak cepat dan tegas, kita bisa membasmi mereka semua, satu per satu!",
  ui_story_5071_50710601_70_dialog_content = "Jika mereka bisa dihapus begitu mudah, seseorang pasti sudah melakukannya sejak lama. Meskipun bersifat kacau, Umbraton mempertahankan keseimbangan tertentu yang tidak boleh digulingkan.",
  ui_story_5071_50710601_71_dialog_content = "Berapa kali aku sudah memperingatkanmu tentang kepolosanmu? Apakah kamu tidak belajar apa-apa dari pelajaran terakhirmu?",
  ui_story_5071_50710601_72_dialog_content = "Kamu hanya selamat karena Kade ada di sana, tapi bagaimana dengan lain kali?",
  ui_story_5071_50710601_73_dialog_content = "Kamu dan Kade tidak akan menjadi satu-satunya yang menderita akibat kesalahanmu. Seluruh keluarga kita akan berada dalam bahaya!",
  ui_story_5071_50710601_74_dialog_content = "Ayah!",
  ui_story_5071_50710601_75_dialog_content = "Valon dan ayahnya selalu bertentangan. Untungnya, sekarang Kade ada di sana untuk mendukungnya...",
  ui_story_5071_50710601_76_dialog_content = "Ayah bahkan tidak mau mendengarkan strategi saya untuk masa depan Umbraton.",
  ui_story_5071_50710601_77_dialog_content = "Tapi aku. Silakan, ceritakan padaku.",
  ui_story_5071_50710601_78_dialog_content = "Katakan padaku, apakah kamu tahu mengapa guild kita menderita begitu banyak di tangan geng-geng akhir-akhir ini? Itu karena semua orang hanya memikirkan diri mereka sendiri.",
  ui_story_5071_50710601_79_dialog_content = "Saya pikir setiap guild harus bersatu dan membentuk satu badan di mana mereka dapat menikmati manfaat dan perlindungan bersama. Kita bisa menyebutnya—",
  ui_story_5071_50710601_80_dialog_content = "Guild Umbraton?",
  ui_story_5071_50710601_81_dialog_content = "Ya, kita akan menyebutnya Umbraton Guild! Hanya ketika kepentingan semua orang dibagi, kita bisa saling membantu mengalahkan musuh bersama!",
  ui_story_5071_50710601_82_dialog_content = "Geng dan guild yang ramah geng, tentara bayaran yang pemangsa... Bahkan Lumopolis pun tidak akan berpeluang!",
  ui_story_5071_50710601_83_dialog_content = "Setelah kita menghilangkan semua gangguan ini dari Umbraton, kota ini akan menjadi surga murni untuk segala jenis bisnis.",
  ui_story_5071_50710601_84_dialog_content = "Dan kemudian... Aku akan memimpin guildku sendiri ke tanah yang jauh lebih jauh!",
  ui_story_5071_50710601_85_dialog_content = "Dan bagaimana caranya kamu melakukannya?",
  ui_story_5071_50710601_86_dialog_content = "Dengan kendaraan, saya kira... Atau tunggu, lebih baik lagi! Saya akan membeli Colossus dari Eraveil dan mendirikan guild saya di atasnya!",
  ui_story_5071_50710601_87_dialog_content = "Bersama, kita akan berlayar melintasi langit dengan angin di wajah kita, bepergian dan berdagang dengan bebas di seluruh benua!",
  ui_story_5071_50710601_88_dialog_content = "Guild saya tidak akan mendiskriminasi berdasarkan kekayaan atau status. Siapa pun bisa bergabung dan berkembang, selama mereka bersedia bekerja keras untuk itu!",
  ui_story_5071_50710601_89_dialog_content = "...",
  ui_story_5071_50710601_90_dialog_content = "Apa itu, Kade? Apakah aku mengatakan sesuatu yang salah?",
  ui_story_5071_50710601_91_dialog_content = "Sama sekali tidak, Valon, itu adalah mimpi yang indah. Mungkin satu-satunya cara untuk benar-benar bebas dari bayangan... adalah dengan terbang ke langit.",
  ui_story_5071_50710601_92_dialog_content = "Aku akan melakukan apapun untuk mewujudkan mimpi itu.",
  ui_story_5071_50710601_93_dialog_content = "Aku juga akan melakukan hal yang sama!",
  ui_story_5071_50710601_94_dialog_content = "Tapi saya pikir Anda tidak peduli dengan bisnis?",
  ui_story_5071_50710601_95_dialog_content = "Hmm... Aku bisa menggambar dengan cukup baik. Kenapa aku tidak mendesain Colossus yang indah untuk guildmu saja?",
  ui_story_5071_50710601_96_dialog_content = "Haha, sepertinya merancang Colossus bukan tugas kita.",
  ui_story_5071_50710601_97_dialog_content = "Sayangnya, suasana damai ini tidak ditakdirkan untuk bertahan lama...",
  ui_story_5071_50710601_98_dialog_content = "Kenapa kamu tampak begitu kesal?",
  ui_story_5071_50710601_99_dialog_content = "Ayah memiliki pertemuan dengan mitra bisnis hari ini dan membawa saya bersamanya.",
  ui_story_5071_50710601_100_dialog_content = "Itu hal yang baik. Artinya dia akhirnya bersedia mengajari kamu tentang urusan guild. Ini akan membawa kita selangkah lebih dekat untuk mewujudkan impian kita.",
  ui_story_5071_50710601_101_dialog_content = "K-Kamu tidak mengerti... Orang yang diperkenalkannya padaku...",
  ui_story_5071_50710601_102_dialog_content = "... adalah seorang penjual racun. Jika ayah bertemu dengannya, itu hanya bisa berarti—",
  ui_story_5071_50710601_103_dialog_content = "Keluargaku juga tidak bersalah, itulah sebabnya ayah terus mencoba menghentikanku.",
  ui_story_5071_50710601_104_dialog_content = "Aku tidak tahu bagaimana aku harus menghadapi ayahku sekarang. Apa yang harus kulakukan...",
  ui_story_5071_50710601_X104_dialog_content = "Kami selalu dapat menggunakan sumber daya ayahmu untuk mewujudkan impian kami.",
  ui_story_5071_50710601_105_dialog_content = "Menggunakan sumber daya seperti itu...? Tidak, kamu pasti bercanda, Kade...",
  ui_story_5071_50710601_106_dialog_content = "... Aku tidak menyadari bahwa kamu merasa seperti itu.",
  ui_story_5071_50710601_107_dialog_content = "Kamu akan selalu di sisiku apa pun yang terjadi, kan?",
  ui_story_5071_50710601_108_dialog_content = "...",
  ui_story_5071_50710601_109_dialog_content = "Ayo terus bermain. Kali ini kamu bisa jadi Putih, dan aku akan jadi Hitam.",
  ui_story_5071_50710601_110_dialog_content = "Yang tidak diketahui oleh Valon adalah bahwa Kade sudah membuat langkah pertama.",
  ui_story_5071_50710601_111_dialog_content = "Bakar setiap tetes racun!",
  ui_story_5071_50710601_112_dialog_content = "Paham!",
  ui_story_5071_50710601_113_dialog_content = "Aduh—",
  ui_story_5071_50710601_114_dialog_content = "Jangan bergerak!",
  ui_story_5071_50710601_115_dialog_content = "Kenapa kamu melakukan ini padaku? Kapan aku pernah bersalah padamu?",
  ui_story_5071_50710601_116_dialog_content = "Jika kamu menjual semua racun ini, tak ada yang tahu berapa banyak keluarga yang akan binasa karenanya.",
  ui_story_5071_50710601_117_dialog_content = "Hah! Bahkan Balai Kehakiman Lumopolis pun tidak akan peduli tentang ini!",
  ui_story_5071_50710601_118_dialog_content = "...Siapa sebenarnya kamu?",
  ui_story_5071_50710601_119_dialog_content = "Aku? Aku hanya... bayangan yang berkelana melewati kota, itu saja.",
  ui_story_5071_50710601_120_dialog_content = "Tidak lama kemudian dan sangat mengejutkan semua orang, ayah Valon berhasil meyakinkan Kade untuk menjadi anak angkatnya. Namun, Valon tidak hadir saat upacara sumpah Kade.",
  ui_story_5071_50710601_121_dialog_content = "Kade menolak untuk menunjukkan sedikit pun kekhawatiran di wajahnya. Dengan dua tanduk hitamnya yang diangkat dengan bangga ke udara, dia mengucapkan janjinya cukup keras agar semua orang bisa mendengar—",
  ui_story_5071_50710601_122_dialog_content = "\"... Saya dengan ini bersumpah bahwa saya tidak akan menyakiti keluarga saya sendiri.\"",
  ui_story_5071_50710601_123_dialog_content = "\"Aku juga tidak akan membahayakan kepentingan keluargaku...\"",
  ui_story_5071_50710701_1_dialog_content = "Mimpi Valon? Anda berani membicarakannya?",
  ui_story_5071_50710701_2_dialog_content = "Kaulah yang menghancurkan semuanya—",
  ui_story_5071_50710701_3_dialog_content = "Saya sangat minta maaf, Nyonya Hanstie...",
  ui_story_5071_50710701_4_dialog_content = "Tapi aku masih akan memberimu beberapa saran... tentang memilih pasangan yang tepat.",
  ui_story_5071_50710701_5_dialog_content = "Saya akui saya sangat sedikit tahu tentang menjalankan bisnis.",
  ui_story_5071_50710701_6_dialog_content = "Tapi jika Anda tertarik untuk menghasilkan uang secara legal di Umbraton, temui Lady Sheol.",
  ui_story_5071_50710701_7_dialog_content = "Aku bisa janji, aku akan melakukan apa pun yang aku bisa untuk membantumu.",
  ui_story_5071_50710701_8_dialog_content = "Aku tidak butuh janjimu, jadi simpan saja, Shadowlord.",
  ui_story_5071_50710701_9_dialog_content = "Saya percaya kamu salah paham tentang saya.",
  ui_story_5071_50710701_10_dialog_content = "Mungkin kita bisa duduk dan membicarakan masa lalu nanti ketika kita mendapatkan kesempatan.",
  ui_story_5071_50710701_11_dialog_content = "Shadowlord, saatnya untuk pertemuan selanjutnya...",
  ui_story_5071_50710701_12_dialog_content = "Aku paham.",
  ui_story_5071_50710701_13_dialog_content = "Saya sangat senang bertemu dengan Anda lagi, Nyonya Hanstie.",
  ui_story_5071_50710701_14_dialog_content = "Kuharap kau berhati-hati dalam berurusan dengan mereka yang berada di bayangan dan menghindari masalah yang tidak perlu.",
  ui_story_5071_50710701_15_dialog_content = "Terima kasih atas pengingatnya, Shadowlord. Aku tahu apa yang sedang aku lakukan.",
  ui_story_5071_50710701_16_dialog_content = "Tidak seperti beberapa orang yang hanya berbicara tentang mimpi orang lain sepanjang waktu.",
  ui_story_5071_50710701_17_dialog_content = "Tanpa benar-benar mengukur...",
  ui_story_5071_50710701_18_dialog_content = "Berapa banyak yang telah dia lakukan untuk semua ini selama bertahun-tahun?",
  ui_story_5071_50710701_19_dialog_content = "...",
  ui_story_5071_50710701_20_dialog_content = "Aneh, ke mana perginya naskahku...",
  ui_story_5071_50710701_21_dialog_content = "Bisakah saya telah meninggalkannya di kamar?",
  ui_story_5071_50710701_22_dialog_content = "Sekarang giliranmu, Nyonya Yvonne!",
  ui_story_5071_50710701_23_dialog_content = "Hanstie, silakan ikuti saya.",
  ui_story_5071_50710701_24_dialog_content = "Ya, aku akan segera ke sana... Hmm?",
  ui_story_5071_50710701_25_dialog_content = "Nona... Meskipun Anda jelas masih sangat muda, mata Anda sudah melihat lika-liku kehidupan.",
  ui_story_5071_50710701_26_dialog_content = "Kakimu... Mohon maaf, ini adalah akibat dari pekerjaan saya, saya khawatir. Maafkan saya jika saya telah menyinggung Anda dengan cara apa pun.",
  ui_story_5071_50710701_27_dialog_content = "Tak apa. Aku tak keberatan.",
  ui_story_5071_50710701_28_dialog_content = "Kamu memberi kesan sebagai seseorang dengan banyak cerita untuk diceritakan. Saya merasa sangat penasaran untuk belajar lebih banyak tentangmu.",
  ui_story_5071_50710701_29_dialog_content = "Juga... Aroma bunga lili yang kaya itu—",
  ui_story_5071_50710701_30_dialog_content = "Ini mengingatkanku pada seseorang. Dia dulu selalu memakai aroma yang memikat seperti ini.",
  ui_story_5071_50710701_31_dialog_content = "Heheh. Saya sangat senang mendengar Anda mengatakan itu—karena saya mengidolakan Nyonya Red Mercury.",
  ui_story_5071_50710701_32_dialog_content = "Saya suka cara Anda menggambarkannya: misterius, kuat, dan bebas.",
  ui_story_5071_50710701_33_dialog_content = "Kagumku pada perannya sebagai penjaga diam-diam adalah alasan aku sangat menyukai bunga lili.",
  ui_story_5071_50710701_34_dialog_content = "Kenangan abadi, cinta yang tak terhentikan, dan berkah yang mendalam. Itulah yang disimbolkan oleh bunga lili, bukan?",
  ui_story_5071_50710701_35_dialog_content = "Tapi saya tidak suka dengan apa yang terjadi pada Ny. Red Mercury di sekuel-sekuelnya. Dia pantas mendapatkan akhir yang lebih baik.",
  ui_story_5071_50710701_36_dialog_content = "... Apa kita pernah bertemu sebelumnya?",
  ui_story_5071_50710701_37_dialog_content = "Kurasa tidak.",
  ui_story_5071_50710701_38_dialog_content = "Yvonne—",
  ui_story_5071_50710701_39_dialog_content = "Ada yang memanggilku?",
  ui_story_5071_50710701_40_dialog_content = "Nyonya Yvonne, tolong jangan buat Shadowlord menunggu terlalu lama.",
  ui_story_5071_50710701_41_dialog_content = "Ah! Permintaan maaf saya, aku akan segera ke sana.",
  ui_story_5071_50710701_42_dialog_content = "Saya terlambat dan tidak bisa mengembalikan naskah itu kepadanya.",
  ui_story_5071_50710701_43_dialog_content = "Anjing penjaga ada di sini!",
  ui_story_5071_50710701_44_dialog_content = "Jangan menguping!",
  ui_story_5071_50710701_45_dialog_content = "Bisakah kamu membantu kami memberikan tumpukan kertas ini kepada Bu Yvonne?",
  ui_story_5071_50710701_46_dialog_content = "Anjing-anjing baik tidak boleh mengganggu Shadowlord!",
  ui_story_5071_50710701_47_dialog_content = "Betapa keras kepala...",
  ui_story_5071_50710701_48_dialog_content = "Sepertinya aku harus menunggu dia keluar.",
  ui_story_5071_50710701_49_dialog_content = "Haruskah kita...",
  ui_story_5071_50710701_X49_dialog_content = "Membaca sedikit lagi?",
  ui_story_5071_50710701_50_dialog_content = "...",
  ui_story_5071_50710701_51_dialog_content = "Meski papan catur antara kedua pria itu tampak bersih, aroma tebal darah dan pertempuran sangat terasa di udara.",
  ui_story_5071_50710701_52_dialog_content = "Valon membuat langkah selanjutnya dengan penuh percaya diri, dan permainan pun diputuskan. \"Sekakmat,\" katanya dengan penuh kemenangan.",
  ui_story_5071_50710701_53_dialog_content = "\"Kamu kalah lagi padaku,\" tambahnya saat Kade diam-diam mengumpulkan bidak catur.",
  ui_story_5071_50710701_54_dialog_content = "Valon memperhatikan bunga lili di tangan temannya dan memanfaatkan kesempatan untuk bertanya. \"Saya dengar kerajaan bayanganmu telah menerima beberapa orang lagi?\"",
  ui_story_5071_50710701_55_dialog_content = "Orang-orang Lady Melissa tidak memiliki tempat untuk pergi setelah dia meninggal. Saya hanya menerimanya.",
  ui_story_5071_50710701_56_dialog_content = "Kenapa tidak bilang tentang ini dari tadi?",
  ui_story_5071_50710701_57_dialog_content = "Saya tidak berpikir Anda akan tertarik untuk tahu.",
  ui_story_5071_50710701_58_dialog_content = "Demi-human muda itu terus mengatur ulang papan catur. Wajah Valon masih tidak menunjukkan kesepian yang dia rasakan di hatinya.",
  ui_story_5071_50710701_59_dialog_content = "Mereka bermain catur dalam diam, dan sepertinya hubungan di antara mereka baik-baik saja.",
  ui_story_5071_50710701_60_dialog_content = "Aku belum sempat memberitahumu bagaimana keadaanku akhir-akhir ini. Setelah sekian lama jauh dari rumah, akhirnya aku membuat beberapa kemajuan.",
  ui_story_5071_50710701_61_dialog_content = "Saya berhasil menyatukan semua usaha kecil di sekitar area ini, dan orang-orang miskin di sini tampaknya benar-benar mendukung kami sekarang. Dengan kecepatan ini, tidak akan lama lagi sebelum saya mewujudkan impian saya memiliki guild yang kuat.",
  ui_story_5071_50710701_62_dialog_content = "Selamat.",
  ui_story_5071_50710701_63_dialog_content = "... Bagaimana keadaan ayah?",
  ui_story_5071_50710701_64_dialog_content = "Baiklah, aku rasa... Tapi dia masih sangat merindukanmu.",
  ui_story_5071_50710701_65_dialog_content = "Haha, saya tidak bisa menahan perasaan sedikit aneh ketika saya bertanya tentang ayah kita. Saya kira itu membuat kamu anak yang lebih baik dari keluarga Istvan daripada saya.",
  ui_story_5071_50710701_66_dialog_content = "...",
  ui_story_5071_50710701_67_dialog_content = "Saya sadar sekarang bahwa saya tidak bisa melakukannya sendiri, Kade... Saya butuh Tongkat Gembala ayah.",
  ui_story_5071_50710701_68_dialog_content = "Ini adalah simbol otoritas yang telah ada dalam keluarga kami selama beberapa generasi. Dengan ini, akhirnya saya bisa mengendalikan aset keluarga kami.",
  ui_story_5071_50710701_69_dialog_content = "Hanya dengan begitu saya bisa mengkonsolidasikan kekuatan saya dan menyatukan para bos Umbraton... sehingga saya bisa memusnahkan mereka semua.",
  ui_story_5071_50710701_70_dialog_content = "Pemuda berambut biru itu mengambil satu lagi buah catur dan berbisik lembut, \"Sekakmat.\"",
  ui_story_5071_50710701_71_dialog_content = "Kade menatap papan tulis beberapa saat sebelum mengarahkan pandangannya ke atas. \"Metode Anda terlalu ekstrem.\"",
  ui_story_5071_50710701_72_dialog_content = "Demi Umbraton dan demi orang-orang lemah, kita tidak boleh berkompromi. Tidak boleh ada sedikit pun kotoran yang tertinggal.",
  ui_story_5071_50710701_73_dialog_content = "Ini tidak adil bagi orang-orang itu.",
  ui_story_5071_50710701_74_dialog_content = "Ingatkan saya lagi tentang janji Anda, Kade.",
  ui_story_5071_50710701_75_dialog_content = "Kamu bilang kamu tidak akan pernah mengkhianati aku, kan? Bahwa kamu akan selalu mendukung dan berada di sisiku?",
  ui_story_5071_50710701_76_dialog_content = "Demi-manusia muda itu ragu sejenak saat angin mengaum di luar. Dalam jeda singkat itu, seorang utusan tiba dengan pesan yang menakutkan:",
  ui_story_5071_50710701_77_dialog_content = "\"Sebuah gerombolan besar Eclipsites telah berkumpul dan bergerak lurus menuju Umbraton.\"",
  ui_story_5071_50710701_78_dialog_content = "Menanggapi ancaman yang semakin dekat, Lumopolis telah mulai membahas apakah akan membantu Umbraton atau tidak. Beberapa orang percaya bahwa ini adalah kesempatan untuk akhirnya menggabungkan kota tersebut sebagai bagian dari mereka sendiri.",
  ui_story_5071_50710701_79_dialog_content = "Para pemain catur telah mulai membuat langkah mereka... Hanya alami, saya kira. Sampai kita berhasil keluar dari bayangan Lumopolis, ini akan terus menjadi nasib kota kita.",
  ui_story_5071_50710701_80_dialog_content = "Selalu ada pilihan alternatif... Jika mereka ingin bernegosiasi, maka kita harus berusaha menjangkau mereka.",
  ui_story_5071_50710701_81_dialog_content = "Aku akan menjadi bentengmu dan terus membuka jalan, jadi pertahankan kepercayaan dirimu, raja.",
  ui_story_5071_50710701_X81_dialog_content = "Sebuah klak keras menandakan permainan baru lainnya.",
  ui_story_5071_50710701_X82_dialog_content = "Itu adalah benteng hitam, namun ia berjuang untuk raja putih.",
  ui_story_5071_50710701_82_dialog_content = "Sendawa! Apakah kamar Nona Goldie ada di arah ini?",
  ui_story_5071_50710701_83_dialog_content = "Nona Goldie, bisakah saya mendapatkan tanda tangan Anda?",
  ui_story_5071_50710701_84_dialog_content = "Anjing penjaga ada di sini!",
  ui_story_5071_50710701_85_dialog_content = "Siap untuk menyerang!",
  ui_story_5071_50710701_86_dialog_content = "T-T-Tunggu! Biarkan kami yang menangani ini...",
  ui_story_5071_50710701_87_dialog_content = "Kita tidak bisa membuat lebih banyak masalah dari yang sudah ada...",
  ui_story_5071_50710701_88_dialog_content = "Siapa kau?",
  ui_story_5071_50710701_89_dialog_content = "Saya ingin Nona Goldie! Nona Goldie!",
  ui_story_5071_50710702_1_dialog_content = "Orang-orang ini gila... Bekerja di keamanan di sini memang berat...",
  ui_story_5071_50710702_2_dialog_content = "Jumlah mereka terlalu banyak. Ini di luar kendali kita sekarang, jadi mari kita terus membaca!",
  ui_story_5071_50710702_3_dialog_content = "Setelah bertahun-tahun, akhirnya saya menemukan keinginan untuk melanjutkan menulis biografi ini.",
  ui_story_5071_50710702_4_dialog_content = "Awalnya, saya menganggap tulisan saya sebelumnya terlalu memuji, dan mungkin salah tafsir dari kebenaran objektif. Ditambah dengan ulasan buruk tentang karya-karya saya sebelumnya, saya merasa perlu untuk berhenti menulis untuk waktu yang tidak ditentukan.",
  ui_story_5071_50710702_5_dialog_content = "Namun, cerita seorang teman tentang masa lalu menenggelamkan saya dalam banjir inspirasi. Mengingat penerimaan yang kurang baik terhadap sekuel \"Nyonya Red Mercury\", saya memutuskan untuk mendasarkan sebagian besar tulisan saya pada cerita asli daripada fiksi murni.",
  ui_story_5071_50710702_6_dialog_content = "Mungkin akhir cerita ini bukan seperti yang dibayangkan oleh pembaca saya sebelumnya, tetapi sebuah kebenaran yang tragis ini tetap layak untuk diceritakan—",
  ui_story_5071_50710702_7_dialog_content = "Ini diambil langsung dari kisah nyata di balik Nyonya Red Mercury?",
  ui_story_5071_50710702_8_dialog_content = "Aku jadi semakin bersemangat untuk membacanya sekarang!",
  ui_story_5071_50710702_9_dialog_content = "Dengan pedang seperti bintang jatuh, Melissa dengan anggun menyerang manusia setengah binatang yang berdiri di depannya.",
  ui_story_5071_50710702_10_dialog_content = "\"Menyerah,\" perintahnya dengan dingin. \"Aku tahu kamu adalah bayangan yang telah menimbulkan kekacauan di Umbraton.\"",
  ui_story_5071_50710702_11_dialog_content = "Untuk penculikan dan penjualan anak-anak, kamu tidak akan diberikan belas kasihan!",
  ui_story_5071_50710702_12_dialog_content = "Anak Melissa bagaikan permata yang hilang baginya, sesuatu yang telah dia genggam selama bertahun-tahun.",
  ui_story_5071_50710702_13_dialog_content = "Diam-diam, lawannya mematahkan hujan serangan pedang. Sepertinya dia punya alasan sendiri untuk mempertahankan kebisuannya yang keras kepala.",
  ui_story_5071_50710702_14_dialog_content = "Meskipun Melissa tidak menemukan putrinya yang telah lama hilang di sini, dia tidak berniat untuk membiarkan penculik ini bebas.",
  ui_story_5071_50710702_15_dialog_content = "Di tengah hiruk pikuk pedang dan bayangan, setengah manusia itu segera menemukan dirinya terjepit di sudut ruangan. Tiba-tiba, keributan di dekatnya terdengar.",
  ui_story_5071_50710702_16_dialog_content = "Ayah—",
  ui_story_5071_50710702_17_dialog_content = "Awas!",
  ui_story_5071_50710702_18_dialog_content = "Sebuah kerumunan anak-anak yang ketakutan berlari keluar di depan dua pejuang itu. Terkejut, Melissa perlahan-lahan menurunkan senjatanya.",
  ui_story_5071_50710702_19_dialog_content = "Menyadari bahwa dia telah diberi informasi yang salah, Melissa menyimpan pedangnya dengan raut wajah kecewa.",
  ui_story_5071_50710702_20_dialog_content = "\"Saya bisa membantu Anda menemukan putri Anda,\" kata demi-human yang dikenal sebagai Kade, setelah mendengar ceritanya.",
  ui_story_5071_50710702_21_dialog_content = "Tapi sebagai gantinya, tolong jangan ikut campur urusanku. Jangan coba hentikan aku untuk mengalahkan geng-geng di sini.",
  ui_story_5071_50710702_22_dialog_content = "Hampir setiap orang di kota ini korup dalam satu cara atau lainnya. Kenapa repot-repot dengan semua ini?",
  ui_story_5071_50710702_23_dialog_content = "Agar anak-anak ini bisa tumbuh sehat dan kuat, meskipun kita tidak ada lagi untuk melindungi mereka.",
  ui_story_5071_50710702_24_dialog_content = "Itu... terdengar sangat mirip dengan cerita tentang ibu dari Lady Sheol.",
  ui_story_5071_50710702_25_dialog_content = "Tapi bukankah itu masih sebuah karya fiksi? Mungkin kita harus... membaca sedikit lebih banyak?",
  ui_story_5071_50710702_26_dialog_content = "Ketika Kade melihat Melissa untuk terakhir kalinya, dia sudah jatuh sakit parah.",
  ui_story_5071_50710702_27_dialog_content = "Penyakitnya telah merampas kecantikannya dan meninggalkannya dalam keadaan sedih dan lesu.",
  ui_story_5071_50710702_28_dialog_content = "Ketika mata mereka akhirnya bertemu lagi, Kade melihat kerentanan dalam tatapan wanita kuat ini.",
  ui_story_5071_50710702_29_dialog_content = "\"Tolong bantu saya menemukan putri saya.\"",
  ui_story_5071_50710702_30_dialog_content = "Itu adalah permintaan terakhir dan satu-satunya dari dia. Sebagai gantinya, dia telah menutup semua bisnisnya yang terlibat dalam urusan gelap.",
  ui_story_5071_50710702_31_dialog_content = "Aku tahu kamu akan menepati janjimu.",
  ui_story_5071_50710702_32_dialog_content = "Kade terdiam di hadapannya. Di belakang punggungnya, sebuah belati tajam di tangannya berkilauan dengan dingin yang pucat.",
  ui_story_5071_50710702_33_dialog_content = "Tenang saja, saya akan melakukan segala yang saya bisa untuknya.",
  ui_story_5071_50710702_34_dialog_content = "Bebas dari semua kekhawatirannya, Melissa menghela nafas panjang lega.",
  ui_story_5071_50710702_35_dialog_content = "\"Satu hal terakhir,\" tiba-tiba dia berkata. \"Apa yang kamu pegang di belakangmu?\"",
  ui_story_5071_50710702_36_dialog_content = "\"Tidak ada apa-apa,\" kata Kade saat dia perlahan mendekatinya, wajahnya tersembunyi oleh bayangan. \"Hanya hadiah perpisahan kecil.\"",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>Teks ini berakhir secara tiba-tiba di sini. Tintanya masih segar, jadi tampaknya ditulis tidak terlalu lama yang lalu.</color>",
  ui_story_5071_50710702_38_dialog_content = "Hah? Tapi bagaimana?",
  ui_story_5071_50710702_39_dialog_content = "Ini...",
  ui_story_5071_50710702_40_dialog_content = "Apa yang sedang terjadi dengan kalian berdua, anak-anak?",
  ui_story_5071_50710702_41_dialog_content = "Saatnya untuk lelang. Kamu harus pergi dan lihat apakah ada sesuatu yang ingin kamu beli, PlayerName sayang.",
  ui_story_5071_50710702_42_dialog_content = "Lelangku berbeda dari yang ada di Umbraton. Ini transparan dan terbuka. Kamu harus melihatnya!",
  ui_story_5071_50710702_43_dialog_content = "Shadowlord dan saya bekerja sangat keras untuk mewujudkan ini.",
  ui_story_5071_50710702_44_dialog_content = "Semua hal baik akan hilang jika kamu tidak bergerak cepat.",
  ui_story_5071_50710702_45_dialog_content = "Tapi saya tidak punya banyak uang belanja... Tunggu, itu tidak penting! Lihat ini, Nona Sheol!",
  ui_story_5071_50710702_46_dialog_content = "Ada seorang wanita dalam naskah Ms. Yvonne yang memiliki nama yang sama dengan ibumu...",
  ui_story_5071_50710702_47_dialog_content = "Apa? Biarkan saya lihat... Ny. Yvonne selalu mendasarkan ceritanya pada Umbraton. Ini bukan hal baru.",
  ui_story_5071_50710702_48_dialog_content = "Ini adalah pembunuhan... Tapi fiksi itu tidak nyata. Deskripsi dalam sebuah novel biasanya hanya rekaan.",
  ui_story_5071_50710702_49_dialog_content = "Tapi lalu mengapa dia menggunakan nama asli?",
  ui_story_5071_50710702_50_dialog_content = "Jangan membaca terlalu banyak ke dalamnya, sayang. Kamu bisa bertanya pada Ny. Yvonne setelah lelang selesai.",
  ui_story_5071_50710702_51_dialog_content = "Yang penting adalah lelang ini akan segera dimulai. Kamu tidak bisa tinggal di sini...",
  ui_story_5071_50710702_52_dialog_content = "Setidaknya bukan Vergil, dia masih harus menilai barang-barang untukku!",
  ui_story_5071_50710702_53_dialog_content = "Mungkin aku bisa mendapatkan harta karun dengan harga murah...",
  ui_story_5071_50710702_54_dialog_content = "Tunggu aku, Nona Sheol!",
  ui_story_5071_50710801_1_dialog_content = "Saya tidak memiliki permintaan lain kecuali satu, Shadowlord. Saya hanya ingin menerbitkan biografi tentang Anda.",
  ui_story_5071_50710801_2_dialog_content = "Tidak masalah. Kamu tidak perlu mendapatkan izin dari saya.",
  ui_story_5071_50710801_3_dialog_content = "Umbraton menyambut kebebasan kreatif.",
  ui_story_5071_50710801_4_dialog_content = "Saya mengerti... Dan saya lega mendengar Anda mengatakan itu, tapi saya masih ingin bertanya tentang beberapa detail dari waktu itu...",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>Di tempat lelang di Pesawat Cloudrover</color>",
  ui_story_5071_50710801_6_dialog_content = "Ahem... Barang yang kami bawa untuk dilelang adalah \"Sebuah Sudut dari Gurun Rediesel,\" sebuah karya Master Finch dalam perjalanannya.",
  ui_story_5071_50710801_7_dialog_content = "Master Finch adalah seniman kelana terkenal dengan banyak karya seni terkenal yang diakui, termasuk di antaranya.",
  ui_story_5071_50710801_8_dialog_content = "Seperti yang bisa kita lihat, Master Finch menggambarkan gurun di bawah matahari yang cerah dalam lapisan melalui gaya romantis uniknya.",
  ui_story_5071_50710801_9_dialog_content = "Dia secara tidak konvensional menonjolkan pasir dalam warna biru untuk membuatnya tampak seperti ombak laut-",
  ui_story_5071_50710801_10_dialog_content = "Hah? Saya kira Cloudrover Guild yang bertanggung jawab menyelenggarakan lelang?",
  ui_story_5071_50710801_11_dialog_content = "Kami menganjurkan perdagangan bebas dan transparansi yang sama, sehingga semua orang bisa menyampaikan pendapat mereka sendiri.",
  ui_story_5071_50710801_12_dialog_content = "Banyak orang di Umbraton yang mengadakan lelang bawah tanah di masa lalu. Namun, asal-usul barang selalu diragukan, dan harganya seringkali tidak masuk akal.",
  ui_story_5071_50710801_13_dialog_content = "Kami berbeda. Kamu bisa membeli atau menjual di lelang kami dengan aman, ditambah dengan penilaian gratis.",
  ui_story_5071_50710801_14_dialog_content = "Maaf, tapi lukisan ini adalah palsu... Menjualnya sebagai barang asli akan menjadi penipuan.",
  ui_story_5071_50710801_15_dialog_content = "(Anak kecil ini tampak seperti orang yang sama sekali berbeda ketika dia berbicara tentang profesinya.)",
  ui_story_5071_50710801_16_dialog_content = "*Suara berisik*",
  ui_story_5071_50710801_17_dialog_content = "Semuanya, tolong tenang! Bukti apa yang kalian miliki untuk menyebut ini sebagai pemalsuan?",
  ui_story_5071_50710801_18_dialog_content = "Tepat sekali, apakah indra Anda lebih tajam daripada kami?",
  ui_story_5071_50710801_19_dialog_content = "Nah, sekarang sudah cukup jelas siapa penjualnya...",
  ui_story_5071_50710801_20_dialog_content = "Master Finch terkenal dengan penggambaran adat istiadat setempat yang dia lihat selama perjalanannya...",
  ui_story_5071_50710801_21_dialog_content = "Akibatnya... Semua karya seninya menggunakan cat dan pigmen yang bersumber secara lokal.",
  ui_story_5071_50710801_22_dialog_content = "Tapi, skema warna dalam lukisan ini memang terlihat kasar dan liar.",
  ui_story_5071_50710801_23_dialog_content = "Sorotan yang lebih kasar dari \"Sebuah Sudut di Gurun Rediesel\" seharusnya dicat dengan pigmen biru cerah yang diekstrak dari lapisan bawah tanah gurun—",
  ui_story_5071_50710801_24_dialog_content = "Tetapi lukisan ini menggunakan batu permata yang dihancurkan, sebuah kemewahan yang jarang ada di Gurun Rediesel.",
  ui_story_5071_50710801_25_dialog_content = "Pembuat uang palsu gagal mempertimbangkan sifat penyerap pasir saat digunakan untuk mengekstrak pigmen...",
  ui_story_5071_50710801_26_dialog_content = "Selain itu, pasir dalam lukisan asli menciptakan nada yang lebih ringan, karena Master Finch ingin itu menyerupai gelombang laut.",
  ui_story_5071_50710801_27_dialog_content = "Kanvas yang digunakan untuk pemalsuan ini dipanggang untuk meniru tekstur aslinya. Dalam prosesnya, warnanya tanpa sengaja dibuat lebih gelap...",
  ui_story_5071_50710801_28_dialog_content = "Ini semua salahmu! Bukankah aku sudah bilang untuk menjauh dari semua trik mewah—",
  ui_story_5071_50710801_29_dialog_content = "Siapa yang kamu salahkan? Kamu tidak bisa membuat salinan yang layak tanpa aku!",
  ui_story_5071_50710801_30_dialog_content = "Keamanan, tolong antar mereka keluar—oh, dan pastikan mereka membawa lukisan mereka.",
  ui_story_5071_50710801_31_dialog_content = "Wow, Vergil... Ternyata kau tahu cukup banyak!",
  ui_story_5071_50710801_32_dialog_content = "Kamu pikir begitu? Hanya saja, itu adalah sesuatu yang benar-benar aku sukai, itu saja...",
  ui_story_5071_50710801_33_dialog_content = "Tentu saja dia bisa. Profesionalisme karyawan kecilku tidak pernah dipertanyakan.",
  ui_story_5071_50710801_34_dialog_content = "Dan ini tentu saja melebihi tingkat seorang anak kecil, sayang.",
  ui_story_5071_50710801_35_dialog_content = "Hmm…",
  ui_story_5071_50710801_36_dialog_content = "Hai semua, selamat datang di lelang. Saya akan menunjukkan barang selanjutnya.",
  ui_story_5071_50710801_37_dialog_content = "Ini adalah lukisan minyak dari klien anonim saya. Seniman tersebut juga tidak dikenal.",
  ui_story_5071_50710801_38_dialog_content = "Ini adalah karya agung dari sudut pandang teknis. Saya harap kalian semua menyukainya.",
  ui_story_5071_50710801_39_dialog_content = "Lukisan ini disebut—\"Kematian Sang Lady\"!",
  ui_story_5071_50710801_40_dialog_content = "Karena nilai tidak dapat ditentukan, penawaran akan dimulai dari lima puluh ratus ribu.",
  ui_story_5071_50710801_41_dialog_content = "Apakah itu... Nyonya Red Mercury dalam lukisan itu? Dan pembunuh yang berdiri di samping tampak seperti...",
  ui_story_5071_50710801_42_dialog_content = "Tidak, sepertinya itu Lady Melissa...",
  ui_story_5071_50710801_43_dialog_content = "Apa ini? Kenapa itu tampak seperti punggung Shadowlord?",
  ui_story_5071_50710801_44_dialog_content = "Lukisan itu... Tapi bagaimana ini bisa?",
  ui_story_5071_50710801_45_dialog_content = "PlayerName sayang, bisakah kamu menawar lukisan itu untukku?",
  ui_story_5071_50710801_46_dialog_content = "Saya tidak tahu permintaan siapa ini, tetapi saya tidak bisa melakukan penawaran sebagai pemimpin guild, jadi tolong... Sebutkan saja harganya.",
  ui_story_5071_50710801_47_dialog_content = "Enam puluh ratus ribu.",
  ui_story_5071_50710801_48_dialog_content = "Satu juta.",
  ui_story_5071_50710801_49_dialog_content = "Bergeraklah, sayang!",
  ui_story_5071_50710801_50_dialog_content = "Sejuta dua!",
  ui_story_5071_50710801_51_dialog_content = "Empat juta!",
  ui_story_5071_50710801_52_dialog_content = "*bergemeletuk*",
  ui_story_5071_50710801_53_dialog_content = "Ini...",
  ui_story_5071_50710801_54_dialog_content = "(Berapa lama waktu yang akan dibutuhkan untuk menabung lagi?)",
  ui_story_5071_50710801_55_dialog_content = "Jangan hanya duduk di sana, sayang. Tawarlah, uang bukan masalah!",
  ui_story_5071_50710801_56_dialog_content = "T-Dua juta!",
  ui_story_5071_50710801_57_dialog_content = "*diam*",
  ui_story_5071_50710801_58_dialog_content = "Dua juta sekali... Ada tawaran lain? Dua juta dua kali!",
  ui_story_5071_50710801_59_dialog_content = "Dua juta tiga kali... Terjual kepada si Caelestite!",
  ui_story_5071_50710801_60_dialog_content = "Saya benar-benar terkejut bahwa sebuah karya yang tidak dikenal bisa mendapatkan harga sebesar itu. Mari kita tepuk tangan untuk Caelestite yang memiliki mata yang tajam.",
  ui_story_5071_50710801_61_dialog_content = "Lady Sheol memang memiliki selera yang baik.",
  ui_story_5071_50710801_62_dialog_content = "Tak kusangka kau begitu tertarik pada lukisan hingga rela melanggar aturan dan menggunakan proxy.",
  ui_story_5071_50710801_63_dialog_content = "Mungkin kita memiliki lebih banyak kesamaan daripada yang kita sadari. Tidak heran Shadowlord merekomendasikanmu kepadaku.",
  ui_story_5071_50710801_64_dialog_content = "Saya merasa tersanjung. Anda lah yang benar-benar mengesankan karena mendirikan guild lintas-Astra di luar Umbraton.",
  ui_story_5071_50710801_65_dialog_content = "Dan aku melihat kamu juga memiliki hubungan dengan Shadowlord. Seharusnya aku yang mengikutimu.",
  ui_story_5071_50710801_66_dialog_content = "... Aku menyukaimu, sampai-sampai aku tidak keberatan kehilangan lukisan itu untukmu.",
  ui_story_5071_50710801_67_dialog_content = "Baik, terima kasih, Nona Hanstie.",
  ui_story_5071_50710801_68_dialog_content = "K-Kita harus membayar lukisan sekarang, Lady Sheol.",
  ui_story_5071_50710801_69_dialog_content = "Kau pikir aku akan meninggalkanmu begitu saja, PlayerName? Ayo, mari kita lihat lukisan itu.",
  ui_story_5071_50710801_70_dialog_content = "May Saya ikut dengan Anda, Nona Sheol?",
  ui_story_5071_50710801_71_dialog_content = "Tentu saja.",
  ui_story_5071_50710801_72_dialog_content = "Huh? Hmm... Aku mencium sesuatu—",
  ui_story_5071_50710801_73_dialog_content = "Aroma samar itu...",
  ui_story_5071_50710801_74_dialog_content = "Nona Sheol... Saya pikir pemalsuan ini dibuat oleh \"A,\" seniman pemalsu favorit saya.",
  ui_story_5071_50710801_75_dialog_content = "Ini adalah pertama kalinya saya melihat salah satu karya asli mereka setelah mengetahui tentang mereka selama ini!",
  ui_story_5071_50710801_76_dialog_content = "Oh? Tim lelang yang saya sewa kali ini tampaknya tidak seprofesional kamu, ya.",
  ui_story_5071_50710801_77_dialog_content = "Asal-usul lukisan ini tidak diketahui, jadi bagaimana kamu bisa mengetahui siapa senimannya, anak kecilku?",
  ui_story_5071_50710801_78_dialog_content = "Nah... Saya cenderung bekerja dengan banyak barang palsu, jadi saya cukup familiar dengan pekerjaan banyak pemalsu yang terampil.",
  ui_story_5071_50710801_79_dialog_content = "Tapi yang terhebat di antara mereka adalah seorang seniman yang dikenal sebagai \"A.\"",
  ui_story_5071_50710801_80_dialog_content = "Selain keterampilan mereka yang tak tertandingi, mereka juga suka menyembunyikan huruf kecil \"A\" di suatu tempat dalam pemalsuan mereka. Itu seperti merek dagang dari karya mereka.",
  ui_story_5071_50710801_81_dialog_content = "Terkadang ada di rambut seseorang atau di mata mereka—kali ini, ada di kerah kemeja seseorang.",
  ui_story_5071_50710801_82_dialog_content = "... Kamu memperhatikan semua itu? Kamu pasti sangat menyukai A.",
  ui_story_5071_50710801_83_dialog_content = "Sebanyak apapun saya menyukai \"A,\" saya pikir mereka cukup egois. Maksud saya, kenapa lagi mereka memilih untuk meninggalkan tanda keberadaan mereka pada sebuah pemalsuan?",
  ui_story_5071_50710801_84_dialog_content = "\"A\" terkesan sebagai orang yang tidak akan pernah menyerah dalam pencapaian tujuan mereka.",
  ui_story_5071_50710801_85_dialog_content = "Benarkah? Itu cukup... menarik.",
  ui_story_5071_50710801_86_dialog_content = "Hah?",
  ui_story_5071_50710801_87_dialog_content = "S-Seorang asing...",
  ui_story_5071_50710801_88_dialog_content = "Kurasa tidak ada gunanya bersembunyi di belakangku sekarang...",
  ui_story_5071_50710801_89_dialog_content = "Jangan takut. Aku sangat menghargaimu, anakku.",
  ui_story_5071_50710801_90_dialog_content = "Aku bisa melihat kamu memiliki potensi yang hebat. Apakah kamu tertarik untuk bekerja untukku?",
  ui_story_5071_50710801_91_dialog_content = "Maaf, Ny. Hanstie, tapi Vergil bekerja untuk saya.",
  ui_story_5071_50710801_92_dialog_content = "Oh, itu sangat disayangkan. Sepertinya Lady Sheol selalu lebih dulu daripada saya.",
  ui_story_5071_50710801_93_dialog_content = "Tidak, kamu terlalu berlebihan. Tapi bagaimana kalau sebuah karya seni pilihanmu dari koleksi pribadiku sebagai kompensasi?",
  ui_story_5071_50710801_94_dialog_content = "Itu tidak perlu. Saya tidak ingin merampas barang-barang berharga milik orang lain—",
  ui_story_5071_50710801_95_dialog_content = "Ngomong-ngomong, kamu juga tidak tahu siapa yang melukis ini, jadi kenapa merasa akrab?",
  ui_story_5071_50710801_96_dialog_content = "Saya ragu Anda akan membayar harga yang sangat mahal hanya karena teknik artistiknya.",
  ui_story_5071_50710801_97_dialog_content = "Nah, katakanlah saya ingin membantu seorang teman lama.",
  ui_story_5071_50710801_98_dialog_content = "Jika lukisan ini sampai ke Umbraton, kemungkinan besar akan sangat merusak reputasi yang telah dia bangun.",
  ui_story_5071_50710801_99_dialog_content = "Tapi karena kamu membelinya untuk dia, aku sudah selesai di sini.",
  ui_story_5071_50710801_100_dialog_content = "Sampai jumpa nanti, semua orang.",
  ui_story_5071_50710801_101_dialog_content = "Tunggu, Nyonya Hanstie, saya punya satu pertanyaan lagi untuk Anda.",
  ui_story_5071_50710801_102_dialog_content = "Apakah kamu sudah lama mengenal Shadowlord?",
  ui_story_5071_50710801_103_dialog_content = "Heheh... Maksudmu orang yang sebenarnya? Mungkin lebih lama dari yang kamu pikirkan.",
  ui_story_5071_50710801_104_dialog_content = "Hmm—",
  ui_story_5071_50710801_105_dialog_content = "Ada apa denganmu? Menatapnya seperti itu... Apakah kamu sedang mempertimbangkan proposalnya?",
  ui_story_5071_50710801_106_dialog_content = "N-N-Tidak sama sekali! Hanya saja...",
  ui_story_5071_50710801_107_dialog_content = "Vergil... Kamu juga merasa terlalu aneh jika ini hanya kebetulan, 'kan?",
  ui_story_5071_50710801_108_dialog_content = "Lukisan ini sama seperti bagian dari cerita yang kita baca di naskah itu...",
  ui_story_5071_50710801_109_dialog_content = "Bisakah itu teman artis Ms. Yvonne tidak lain adalah \"A\"?",
  ui_story_5071_50710801_110_dialog_content = "Dia memang mengatakan bahwa dia mulai menulis lagi setelah berteman dengan seorang seniman tertentu...",
  ui_story_5071_50710801_111_dialog_content = "Kamu benar, sayang, ini terlalu banyak untuk menjadi kebetulan.",
  ui_story_5071_50710801_112_dialog_content = "Seolah-olah itu dipentaskan untuk kita lihat.",
  ui_story_5071_50710801_113_dialog_content = "Saya tidak mengerti, Lady Sheol... Apa tujuan dari semua ini?",
  ui_story_5071_50710801_114_dialog_content = "Hanya ada dua penjelasan untuk rangkaian peristiwa ini—",
  ui_story_5071_50710801_115_dialog_content = "Jika bukan untuk memberi tahu saya kebenaran, hanya bisa...",
  ui_story_5071_50710801_116_dialog_content = "Apa tindak lanjut untuk naskah ini, sayang?",
  ui_story_5071_50710801_117_dialog_content = "Lihatlah apa yang datang setelahnya—",
  ui_story_5071_50710901_1_dialog_content = "Dengan tongkat emas di tangan, manusia setengah dewa itu berdiri di tengah Pit. Kerumunan yang berteriak dipimpin oleh seorang teman lama mengelilinginya dari semua sisi.",
  ui_story_5071_50710901_2_dialog_content = "\"Pengkhianat!\" mereka berteriak. \"Mengapa kau membawa pasukan Lumopolis langsung ke depan pintu Umbraton?\"",
  ui_story_5071_50710901_3_dialog_content = "Setengah manusia itu tetap diam, tatapan tajamnya terfokus pada wajah seorang pria. Di bawah rambut birunya, mata Valon penuh dengan rasa sakit dan kesedihan.",
  ui_story_5071_50710901_4_dialog_content = "Setelah sekian lama, Valon akhirnya membuka mulutnya untuk berbicara. \"Kade... Mengapa? Mengapa kau membunuh ayah kita dan mencuri Tongkat Gembala?\"",
  ui_story_5071_50710901_5_dialog_content = "Apakah kamu telah membelakangi mimpi kita? Kenapa kamu mematuhi kehendak Lumopolis?",
  ui_story_5071_50710901_6_dialog_content = "The Pit... Bertahun-tahun yang lalu, aku menghadapi begitu banyak musuh di tempatmu. Apakah kamu benar-benar berpikir bisa menghentikanku hanya dengan sedikit orang?",
  ui_story_5071_50710901_7_dialog_content = "Satu pertanyaan saja sudah cukup untuk membuat seluruh kerumunan panik.",
  ui_story_5071_50710901_8_dialog_content = "Apa... Tapi bukankah mereka adalah teman baik?",
  ui_story_5071_50710901_9_dialog_content = "... Terus membaca.",
  ui_story_5071_50710901_10_dialog_content = "\"Kamu terlalu lemah! Itulah sebabnya aku harus menggantikanmu!\"",
  ui_story_5071_50710901_11_dialog_content = "Dengan raungan, Kade melaju ke depan dan menusukkan tongkat ke dada temannya. Wajahnya yang gila dan terpelintir sudah tidak bisa dikenali lagi, bahkan oleh saudara kandungnya sendiri.",
  ui_story_5071_50710901_12_dialog_content = "Ke-Kenapa...",
  ui_story_5071_50710901_13_dialog_content = "Saya menolak untuk menjadi bayangan siapa pun.",
  ui_story_5071_50710901_14_dialog_content = "Dengan wajahnya masih membeku dalam kejutan, pemuda berambut biru itu jatuh terkulai ke tanah. Tak lama, kerumunan dipenuhi dengan rasa putus asa.",
  ui_story_5071_50710901_15_dialog_content = "Dalam rasa sakit dan kemarahan mereka, mereka melompat ke dalam pertempuran—",
  ui_story_5071_50710901_16_dialog_content = "F-Flip ke halaman berikutnya!",
  ui_story_5071_50710901_17_dialog_content = "Kemarahan brutal Kade akhirnya meledak. Karena menghalangi jalannya, ia dengan cepat menghancurkan warga sesama Umbraton.",
  ui_story_5071_50710901_18_dialog_content = "Untuk membasmi semua perbedaan pendapat, dia memandikan Umbraton dalam inferno biru, memastikan bahwa tidak ada yang luput dari kemarahannya.",
  ui_story_5071_50710901_19_dialog_content = "Dengan cara yang tegas, akhirnya dia berhasil meraih otoritas mutlak di tangannya.",
  ui_story_5071_50710901_20_dialog_content = "Untuk mengambil alih Umbraton, dia mengkhianati mimpinya dan menyerahkan rumahnya kepada Lumopolis.",
  ui_story_5071_50710901_21_dialog_content = "Untuk itu, dia mengambil nyawa dan nama belakang saudaranya, dan merampas status terkemuka keluarganya—",
  ui_story_5071_50710901_22_dialog_content = "Dia memilih untuk menempuh jalan kejahatan dan kekejian. Saat dia naik ke tampuk kekuasaan, dia menyembunyikan masa lalunya dan keberadaan Valon, saudara kandungnya sebelumnya.",
  ui_story_5071_50710901_23_dialog_content = "Ketika Umbraton akhirnya jatuh sepenuhnya di bawah kendalinya, tidak ada yang mengingat bagian apa pun dari masa lalu kejamnya.",
  ui_story_5071_50710901_24_dialog_content = "Yang mereka tahu hanyalah bahwa dia memimpin gengnya dengan tongkat yang bernoda darah.",
  ui_story_5071_50710901_25_dialog_content = "Istvan, Shadowlord dari Umbraton.",
  ui_story_5071_50710901_26_dialog_content = "A-Apa?",
  ui_story_5071_50710901_27_dialog_content = "Pria bernama Kade ini... Dia adalah Shadowlord sejak awal?",
  ui_story_5071_50710901_28_dialog_content = "Itu tidak mungkin benar! Shadowlord tidak akan pernah mengkhianati Umbraton seperti itu!",
  ui_story_5071_50710901_29_dialog_content = "(Selalu ada firasat tentang sesuatu yang berbahaya tersembunyi di hati Shadowlord, tapi cerita dalam naskah ini...)",
  ui_story_5071_50710901_30_dialog_content = "...",
  ui_story_5071_50710901_31_dialog_content = "Nona Sheol, Shadowlord...",
  ui_story_5071_50710901_32_dialog_content = "Orang-orang itu sangat rahasia. Kita tidak bisa begitu saja percaya apa yang mereka katakan tapi—",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5071_50710901_34_dialog_content = "Apa yang terjadi? Dari mana asal ledakan itu?",
  ui_story_5071_50710901_35_dialog_content = "Lady Sheol! A-Alasan entah kenapa, para pengawal Lumopolis yang ada di kapal tiba-tiba menyerang kami!",
  ui_story_5071_50710901_36_dialog_content = "Mengapa penjaga Lumopolis menyerang kami?",
  ui_story_5071_50710901_37_dialog_content = "Apakah saya telah menyinggung seseorang?",
  ui_story_5071_50710901_38_dialog_content = "Berhenti! Apa yang menurutmu sedang kamu lakukan pada pesawat Lady Sheol?",
  ui_story_5071_50710901_39_dialog_content = "Kita masih di udara! Jika kamu terus merusak pesawat, semua orang di dalamnya akan mati—",
  ui_story_5071_50710901_40_dialog_content = "Ayo berikan pelajaran keras kepada orang-orang bodoh ini!",
  ui_story_5071_50710901_41_dialog_content = "Berhenti! Jangan lakukan ini...",
  ui_story_5071_50710901_42_dialog_content = "Ini akan membahayakan semua orang secara serius!",
  ui_story_5071_50710901_43_dialog_content = "Berhenti mengacaukan wilayahku!",
  ui_story_5071_50710901_X43_dialog_content = "H-hah?!",
  ui_story_5071_50710901_X44_dialog_content = "Kenapa kalian begitu bodoh...",
  ui_story_5071_50710901_X45_dialog_content = "Berani-beraninya kamu mencoba menghancurkan pesawatku!",
  ui_story_5071_50710901_X46_dialog_content = "Eek!",
  ui_story_5071_50710901_X47_dialog_content = "A-Apa tendangan jatuh yang luar biasa!",
  ui_story_5071_50710901_X48_dialog_content = "Aku tidak percaya itu bosku!",
  ui_story_5071_50710901_X49_dialog_content = "I-Ini pertama kalinya aku melihat dia bertarung!",
  ui_story_5071_50710901_44_dialog_content = "A-Apa tendangan jatuh yang luar biasa—",
  ui_story_5071_50710901_45_dialog_content = "Nona Sheol...",
  ui_story_5071_50710901_46_dialog_content = "Shadowlord, sepertinya ada keributan di luar. Seseorang tampaknya telah menyelinap masuk.",
  ui_story_5071_50710901_47_dialog_content = "Oh?",
  ui_story_5071_50710901_48_dialog_content = "Saya melihat \"tamu\" mulai menjadi tidak sabar. Menarik.",
  ui_story_5071_50710901_49_dialog_content = "?",
  ui_story_5071_50711001_1_dialog_content = "Ada apa?",
  ui_story_5071_50711001_2_dialog_content = "Shadowlord! Akhirnya kamu datang! Ini—",
  ui_story_5071_50711001_3_dialog_content = "Shadowlord, kenapa kau melakukan ini? Bukankah kau yang memerintahkan kami untuk melakukan ini?",
  ui_story_5071_50711001_4_dialog_content = "Kamu memerintahkan kami untuk menyingkirkan pengacau ini, jadi kenapa kamu...",
  ui_story_5071_50711001_5_dialog_content = "!",
  ui_story_5071_50711001_6_dialog_content = "Jadi Shadowlord yang ada di balik ini?",
  ui_story_5071_50711001_7_dialog_content = "Tidak heran penjaga Lumopolis ini...",
  ui_story_5071_50711001_8_dialog_content = "Mengapa mereka memperlakukan kita seperti ini...",
  ui_story_5071_50711001_9_dialog_content = "Diam. Situasinya bukan—",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>Berjibun lembar kertas tiba-tiba melayang di udara dan jatuh seperti kristal salju. Ini adalah—</color>",
  ui_story_5071_50711001_11_dialog_content = "Manuskrip Ms. Yvonne?",
  ui_story_5071_50711001_12_dialog_content = "Semua halaman telah berserakan di mana-mana! Siapa yang bisa...",
  ui_story_5071_50711001_13_dialog_content = "Tunggu, halaman-halaman manuskrip ini semua sama. Lihatlah.",
  ui_story_5071_50711001_14_dialog_content = "Setelah bertahun-tahun, akhirnya saya kembali ke tempat ini. Istvan kini menjadi penguasa Umbraton, dan impian Valon tentang Guild Umbraton telah menjadi alat kekuasaannya.",
  ui_story_5071_50711001_15_dialog_content = "Haruskah saya terus menulis demi kebenaran? Atau haruskah saya menyimpan cerita-cerita ini dalam-dalam di hati saya?",
  ui_story_5071_50711001_16_dialog_content = "Saya selalu menyaksikan peristiwa jahat yang terjadi di depan saya, menggerus hati nurani saya. Pada awalnya, saya pikir saya sudah terbiasa dengan itu.",
  ui_story_5071_50711001_17_dialog_content = "Seandainya aku tidak mengungkap kebenaran tentang ambisi terbarunya, mungkin aku akan terus memperhatikan dari jarak jauh—",
  ui_story_5071_50711001_18_dialog_content = "Secara kebetulan, saya mengetahui tentang keserakahan tak terpuaskan Istvan dari bawahannya. Meskipun dia duduk tepat di puncak, dia masih menginginkan lebih.",
  ui_story_5071_50711001_19_dialog_content = "Meskipun dia memperlihatkan dirinya sebagai penguasa yang murah hati, secara diam-diam dia tidak puas dengan geng dan guild yang netral.",
  ui_story_5071_50711001_20_dialog_content = "Mereka yang beroperasi di luar kendali guild-nya telah membuatnya gelisah... Dia tidak akan mentolerir pemberontakan dalam bentuk apa pun.",
  ui_story_5071_50711001_21_dialog_content = "Untuk alasan ini, dia berencana menggunakan Persekutuan Cloudrover untuk mengumpulkan lawan-lawannya dan menghancurkan mereka sekali dan untuk selamanya. Dengan melakukan itu, dia akan mencapai apa yang selalu dia cari—kontrol absolut atas Umbraton.",
  ui_story_5071_50711001_22_dialog_content = "Dengan sedikit waktu yang tersisa untukku di dunia ini, aku ingin menuntut keadilan kepada seorang pria yang masa lalunya telah dilupakan.",
  ui_story_5071_50711001_23_dialog_content = "—Ditandatangani, Yvonne.",
  ui_story_5071_50711001_24_dialog_content = "Benarkah itu?",
  ui_story_5071_50711001_25_dialog_content = "Nyonya Yvonne dan Shadowlord baru saja melakukan pertemuan, bukan?",
  ui_story_5071_50711001_26_dialog_content = "Tenanglah! Ada yang aneh dengan naskah ini.",
  ui_story_5071_50711001_27_dialog_content = "Karena Shadowlord ada di sini, bukankah itu berarti Nyonya Yvonne adalah...",
  ui_story_5071_50711001_28_dialog_content = "Ini terlalu berat sebelah...",
  ui_story_5071_50711001_29_dialog_content = "Apakah kita semua akan dihentikan?",
  ui_story_5071_50711001_30_dialog_content = "Kamu punya lagi? Tunjukkan pada kami!",
  ui_story_5071_50711001_31_dialog_content = "H-Tunggu!",
  ui_story_5071_50711001_32_dialog_content = "Semuanya, mohon tetap tenang.",
  ui_story_5071_50711001_33_dialog_content = "I-Ini...",
  ui_story_5071_50711001_34_dialog_content = "Apakah ini benar? Apakah ini benar-benar kisah masa lalu Shadowlord?",
  ui_story_5071_50711001_35_dialog_content = "*Huff* Mereka sama sekali tidak mendengarkan—",
  ui_story_5071_50711001_36_dialog_content = "Rumor itu benar-benar nyata? Dan dia ingin membunuh kita sekarang?",
  ui_story_5071_50711001_37_dialog_content = "Berhenti berdebat. Ini hanya sebuah novel. Apakah kamu benar-benar percaya ini nyata?",
  ui_story_5071_50711001_38_dialog_content = "Tapi itu sangat cocok dengan rumor...",
  ui_story_5071_50711001_39_dialog_content = "Mengingat kamu tahu itu hanyalah rumor, seberapa kredibel menurutmu rumor tersebut?",
  ui_story_5071_50711001_40_dialog_content = "Tapi, Umbraton Guild memang mengendalikan rute dagang kami. Bagaimana kamu tahu bahwa dia tidak menggunakan kita untuk membuat dirinya lebih kuat?",
  ui_story_5071_50711001_41_dialog_content = "Semua uang kami disimpan di Umbraton Guild... Jika dia benar-benar memutuskan untuk membunuh kami dan mengambil uang kami...",
  ui_story_5071_50711001_42_dialog_content = "Pedagang bodoh, pedagang buruk! Kenapa kamu percaya semua yang kamu dengar?",
  ui_story_5071_50711001_43_dialog_content = "Bos bukan orang seperti itu!",
  ui_story_5071_50711001_44_dialog_content = "Itu hanya adaptasi!",
  ui_story_5071_50711001_45_dialog_content = "Tidak akan menjelaskan, Shadowlord?",
  ui_story_5071_50711001_46_dialog_content = "(Raja Bayangan?)",
  ui_story_5071_50711001_47_dialog_content = "(Apakah dia... mengawasi mereka?)",
  ui_story_5071_50711001_48_dialog_content = "Sepertinya pemimpin dari Red Panther Guild memiliki sesuatu untuk dikatakan... Gray Parrot Guild, juga...",
  ui_story_5071_50711001_49_dialog_content = "(Tidak, bukan begitu...)",
  ui_story_5071_50711001_50_dialog_content = "Geng Rusted Falcon juga... Saya mengerti.",
  ui_story_5071_50711001_51_dialog_content = "(Dia sedang mengukur mangsanya.)",
  ui_story_5071_50711001_52_dialog_content = "Melapor! Ini buruk, Nona Sheol!",
  ui_story_5071_50711001_53_dialog_content = "Yvonne adalah...",
  ui_story_5071_50711001_54_dialog_content = "<size=45>Nyonya Yvonne mati di ruang penerimaan sementara!</size>",
  ui_story_5071_50711101_1_dialog_content = "Pembersih yang bertanggung jawab membersihkan ruang resepsionis sementara ini adalah orang yang membuat penemuan tersebut.",
  ui_story_5071_50711101_2_dialog_content = "Semuanya rapi dan bersih di tempat kejadian. Tidak ada perjuangan yang terjadi antara korban dan pembunuh.",
  ui_story_5071_50711101_3_dialog_content = "Satu-satunya yang kami temukan adalah beberapa helai rambut di karpet tempat Nyonya Yvonne berbaring.",
  ui_story_5071_50711101_4_dialog_content = "Ini bukan rambut Aurorian biasa. Bahkan, ini lebih mirip dengan rambut binatang, tetapi kondisinya tetap sangat baik...",
  ui_story_5071_50711101_5_dialog_content = "Shadowlord, ruang penerima tamu sementara ini dipinjamkan kepada Anda... Benar?",
  ui_story_5071_50711101_6_dialog_content = "Ingatkan kami di mana Anda tadi, Tuanku?",
  ui_story_5071_50711101_7_dialog_content = "Awas apa yang kamu katakan. Apakah kamu meragukan bosku?",
  ui_story_5071_50711101_8_dialog_content = "Seleucid.",
  ui_story_5071_50711101_9_dialog_content = "Tapi bos...",
  ui_story_5071_50711101_10_dialog_content = "Anda seharusnya lebih berpikir jika itu hanya dugaan dan bukan tuduhan langsung.",
  ui_story_5071_50711101_11_dialog_content = "Hingga beberapa saat yang lalu, saya sedang membahas buku-buku Nyonya Yvonne bersamanya.",
  ui_story_5071_50711101_12_dialog_content = "Saya hanya datang untuk melihat apa keributannya.",
  ui_story_5071_50711101_13_dialog_content = "Tapi Nyonya Yvonne sangat bersemangat saat itu, mengatakan bahwa dia baru saja mendapatkan inspirasi.",
  ui_story_5071_50711101_14_dialog_content = "Jadi aku membiarkannya sendiri, tidak ingin mengganggunya.",
  ui_story_5071_50711101_15_dialog_content = "Dan Nyonya Yvonne meninggal di sini kemudian. Bagaimana mungkin itu terjadi?",
  ui_story_5071_50711101_16_dialog_content = "Kami baru saja mendengar bahwa Nyonya Yvonne memiliki beberapa materi yang mencemarkan nama baik tentang masa lalu Shadowlord.",
  ui_story_5071_50711101_17_dialog_content = "Mencurigakan bagaimana dia meninggal...",
  ui_story_5071_50711101_18_dialog_content = "Semua orang, tolong jangan menyebarkan rumor di antara kerumunan.",
  ui_story_5071_50711101_19_dialog_content = "Siapa itu? Siapa yang mulai menyebarkan rumor? Tunjukan dirimu!",
  ui_story_5071_50711101_20_dialog_content = "Mungkin kita juga akan ditelan oleh bayangan, sama seperti dia.",
  ui_story_5071_50711101_21_dialog_content = "May Saya bertanya siapa Anda, Tuan? Sepertinya Anda benar-benar ingin <color=#FFB400>mengungkapkan isi hati Anda</color>, jadi mengapa tidak melangkah lebih dekat agar kita semua bisa mendengar?",
  ui_story_5071_50711101_22_dialog_content = "Cukup, Kleken.",
  ui_story_5071_50711101_23_dialog_content = "Jangan merusak hari penting Sheol.",
  ui_story_5071_50711101_24_dialog_content = "Ah... Bagaimana ini bisa...",
  ui_story_5071_50711101_25_dialog_content = "Yvonne...",
  ui_story_5071_50711101_26_dialog_content = "Dia terlihat begitu damai dengan senyum di wajahnya, seolah-olah dia hanya sedang tidur...",
  ui_story_5071_50711101_27_dialog_content = "Dia tidak memiliki luka apapun, jadi kita bisa mengesampingkan kemungkinan serangan mendadak...",
  ui_story_5071_50711101_28_dialog_content = "Apakah mungkin... dia diracuni?",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5071_50711101_30_dialog_content = "P-Pesawatnya bergetar!",
  ui_story_5071_50711101_31_dialog_content = "Ini mungkin karena serangan barusan... Jangan panik, semuanya.",
  ui_story_5071_50711101_32_dialog_content = "Pesawat ini kokoh dan dapat diandalkan—",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5071_50711101_34_dialog_content = "... Hubungi kepala teknik dan suruh mereka memeriksa kerusakan.",
  ui_story_5071_50711101_35_dialog_content = "Siap, Kapten!",
  ui_story_5071_50711101_36_dialog_content = "Semuanya, tolong tetap tenang dan dengarkan aku.",
  ui_story_5071_50711101_37_dialog_content = "Hari ini adalah hari penting untuk temanku. Saya di sini benar-benar untuk merayakan impian yang menjadi kenyataan.",
  ui_story_5071_50711101_38_dialog_content = "Saya tidak akan merusak acara ceria ini, atau membiarkan siapa pun melakukannya.",
  ui_story_5071_50711101_39_dialog_content = "Guardians akan naik dan menyelidiki segera setelah kita mendarat.",
  ui_story_5071_50711101_40_dialog_content = "Tentu saja, mereka juga akan memeriksa saya. Saya menerima semua konsekuensi jika mereka menemukan saya terlibat dengan cara apa pun.",
  ui_story_5071_50711101_41_dialog_content = "Tapi aku ingat Guardians mengikuti perintah dari Umbraton Guild...",
  ui_story_5071_50711101_42_dialog_content = "Dan mereka semua dari Geng Istvan.",
  ui_story_5071_50711101_43_dialog_content = "Bukankah putrimu adalah ketua dari Guild Umbraton?",
  ui_story_5071_50711101_44_dialog_content = "Saya sama sekali tidak mengenal Anda, tapi sepertinya Anda memiliki pendapat yang kuat tentang saya.",
  ui_story_5071_50711101_45_dialog_content = "Apakah itu ancaman?",
  ui_story_5071_50711101_46_dialog_content = "Ada sesuatu yang sangat ingin saya ketahui, Shadowlord. Apakah kamu benar-benar akan dihukum?",
  ui_story_5071_50711101_47_dialog_content = "Peraturan Keamanan Umbraton yang disebut-sebut baru saja diumumkan. Janjimu terlalu kosong!",
  ui_story_5071_50711101_48_dialog_content = "Saya tidak pernah menduga kematian Nyonya Yvonne. Sayang sekali...",
  ui_story_5071_50711101_49_dialog_content = "Sebagai teman lama mu, aku pikir kau mungkin telah berubah.",
  ui_story_5071_50711101_50_dialog_content = "Bahkan setelah bertahun-tahun, sepertinya Anda dan Umbraton masih belum melupakan luka dari masa lalu.",
  ui_story_5071_50711101_51_dialog_content = "Istvan... tidak, <color=#FFB400>Kade</color>, kau benar-benar tidak akan membiarkan kami hidup?",
  ui_story_5071_50711101_52_dialog_content = "Apakah kamu akan melakukan seperti yang kamu lakukan bertahun-tahun yang lalu...",
  ui_story_5071_50711101_53_dialog_content = "Dan menghancurkan semua orang yang tidak menurut padamu sekali lagi?",
  ui_story_5071_50711101_54_dialog_content = "...",
  ui_story_5071_50711101_55_dialog_content = "*berbisik*",
  ui_story_5071_50711101_56_dialog_content = "Saya dengar bahwa Shadowlord menghapus semua orang yang menentangnya untuk...",
  ui_story_5071_50711101_57_dialog_content = "Kamu berbicara tentang insiden Pit itu dalam naskah, 'kan?",
  ui_story_5071_50711101_58_dialog_content = "Pit dipenuhi oleh para pemimpin Umbraton sebelum Krisis Darkover menimpa kami. Saya mendengar Shadowlord bertarung satu melawan seratus di sana.",
  ui_story_5071_50711101_59_dialog_content = "Benar. Mereka sama seperti kita. Mereka juga adalah pemimpin dari Umbraton...",
  ui_story_5071_50711101_60_dialog_content = "Dia sangat kuat. Itulah mengapa dia adalah Shadowlord.",
  ui_story_5071_50711101_61_dialog_content = "Kamu dengar itu, <color=#FFB400>Kade</color>? Masa lalumu belum sepenuhnya terlupakan.",
  ui_story_5071_50711101_62_dialog_content = "Kamu membunuh temanmu dan ayah angkatmu, dan saya tahu saya bukan satu-satunya yang ingat!",
  ui_story_5071_50711101_63_dialog_content = "Jadi isi dari manuskrip-manuskrip tersebut adalah...",
  ui_story_5071_50711101_64_dialog_content = "Aku takut masa lalu jauh lebih kejam daripada yang terdokumentasi. Dia mungkin telah menggunakan cara yang lebih memalukan dan tidak bermoral untuk sampai di posisinya sekarang—",
  ui_story_5071_50711101_65_dialog_content = "Dia pasti mampu melakukan hal seperti itu!",
  ui_story_5071_50711101_66_dialog_content = "Metodenya sama sekali tidak dapat diterima. Bisakah kita masih mempercayainya?",
  ui_story_5071_50711101_67_dialog_content = "Dulu aku dengar dia mengkhianati temannya dan menyerah kepada Lumopolis untuk mendapatkan statusnya sekarang...",
  ui_story_5071_50711101_68_dialog_content = "Dia adalah putra legendaris yang iblis...",
  ui_story_5071_50711101_69_dialog_content = "Semua reformasi yang disebut-sebut ini sepenuhnya mengabaikan kepentingan kami. Apa yang mereka tuju...",
  ui_story_5071_50711101_70_dialog_content = "Apakah dia benar-benar ingin menghabisi kita semua?",
  ui_story_5071_50711101_71_dialog_content = "Aku benar-benar senang bisa bertemu denganmu lagi hari ini... <color=#FFB400>Ava</color>.",
  ui_story_5071_50711101_72_dialog_content = "Tapi sampai sekarang aku tidak mengerti mengapa kamu memilih momen ini untuk muncul.",
  ui_story_5071_50711101_73_dialog_content = "Untuk sekejap, saya sungguh berharap Anda ada di sini untuk mimpinya.",
  ui_story_5071_50711101_74_dialog_content = "Tapi ini niat sebenarmu, aku lihat.",
  ui_story_5071_50711101_75_dialog_content = "Kamu dan aku tidak sama. Aku satu-satunya yang benar-benar mengingat mimpinya.",
  ui_story_5071_50711101_76_dialog_content = "Lady Sheol, kita seharusnya mendarat setelah staf teknik selesai melakukan inspeksi.",
  ui_story_5071_50711101_77_dialog_content = "Guardians seharusnya sedang dalam perjalanan dan akan menangani sisanya.",
  ui_story_5071_50711101_78_dialog_content = "Tapi sekarang di bawah kita hanya ada belantara.",
  ui_story_5071_50711101_79_dialog_content = "Kita juga tidak jauh dari wilayah Eclipsite.",
  ui_story_5071_50711101_80_dialog_content = "Pria itu... mungkin tidak akan membiarkan kita pergi begitu saja.",
  ui_story_5071_50711101_81_dialog_content = "Apakah mungkin demi reformasi, dia bahkan akan...",
  ui_story_5071_50711101_82_dialog_content = "Tidak ada yang perlu ditakuti, semua orang!",
  ui_story_5071_50711101_83_dialog_content = "Guildku memiliki sejumlah kapal udara kecil yang ditempatkan di dekat sini. Jika kamu bersedia mempercayai saya, dengan senang hati saya akan mengangkut kalian semua kembali ke Umbraton.",
  ui_story_5071_50711101_84_dialog_content = "Bawa aku! Aku akan pergi bersamamu!",
  ui_story_5071_50711101_85_dialog_content = "Tidak akan terjadi apa-apa sekarang karena masih banyak orang di sini, tapi jika kita terus tinggal di kapal udara ini...",
  ui_story_5071_50711101_86_dialog_content = "Aku punya keluarga. Aku tidak ingin mati!",
  ui_story_5071_50711101_87_dialog_content = "*Bisikan*",
  ui_story_5071_50711101_88_dialog_content = "A-Aku juga akan ikut denganmu.",
  ui_story_5071_50711101_89_dialog_content = "Iya, aku juga!",
  ui_story_5071_50711101_90_dialog_content = "Ayo pergi dari sini sekarang. Aku tidak ingin tinggal di sini.",
  ui_story_5071_50711101_91_dialog_content = "Ayo, kenapa kau memperlakukan kami seperti kami ini penjahat?",
  ui_story_5071_50711101_92_dialog_content = "Kalianlah yang selama ini telah menjilat kami—",
  ui_story_5071_50711101_93_dialog_content = "Hei, kalian juga bisa berada dalam masalah jika terus mengikutinya.",
  ui_story_5071_50711101_94_dialog_content = "Lagipula, kami tidak bisa menjamin bahwa kami tidak akan melakukan hal serupa jika kamu tetap tinggal.",
  ui_story_5071_50711101_95_dialog_content = "Lari, lari!",
  ui_story_5071_50711101_96_dialog_content = "Biarkan mereka pergi.",
  ui_story_5071_50711101_97_dialog_content = "Aku yakin Nyonya Hanstie punya rencana sendiri.",
  ui_story_5071_50711101_98_dialog_content = "Dan untuk itu, dia pasti tidak akan menyakiti penontonnya yang sangat berharga.",
  ui_story_5071_50711101_99_dialog_content = "Tapi mereka pasti akan mencemarkan nama baik kita jika kita membiarkan mereka pergi—",
  ui_story_5071_50711101_100_dialog_content = "Ikuti mereka dengan pesawat kecil.",
  ui_story_5071_50711101_101_dialog_content = "Cukup jaga jarakmu dan pastikan orang-orang aman.",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5071_50711101_103_dialog_content = "Sepertinya pesawat ini benar-benar ditakdirkan untuk celaka. Aku harus memberi tahu kalian semua—",
  ui_story_5071_50711101_104_dialog_content = "Melanjutkan untuk tinggal di sisi pria itu hanya akan menempatkan Anda dalam bahaya yang sangat besar.",
  ui_story_5071_50711101_105_dialog_content = "Tolong jangan bicara tentang Shadowlord seperti itu, terutama karena dia belum melakukan apa-apa.",
  ui_story_5071_50711101_106_dialog_content = "Dia mungkin selalu menyembunyikan dirinya dalam bayang-bayang sepanjang waktu, tetapi saya tahu identitas aslinya.",
  ui_story_5071_50711101_107_dialog_content = "Dia adalah seorang pria yang membantai saudaranya dan merampas segalanya dari ayah angkatnya. Tidak hanya itu, dia berusaha keras untuk memastikan bahwa tidak ada seorang pun yang mengingat mereka sama sekali.",
  ui_story_5071_50711101_108_dialog_content = "Seorang pria yang rela meninggalkan namanya sendiri, semua demi keuntungan pribadi.",
  ui_story_5071_50711101_109_dialog_content = "Dia tidak lebih dari setan yang menginjak-injak siapa pun yang menghalangi dirinya dan takhta yang dia cari.",
  ui_story_5071_50711101_X109_dialog_content = "Kamu tidak pantas memegang <color=#FFB400>Shepherd's Staff</color>, Kade!",
  ui_story_5071_50711101_110_dialog_content = "...",
  ui_story_5071_50711101_111_dialog_content = "... Tidak peduli apa yang kamu katakan, aku masih memilih untuk percaya pada Shadowlord yang selama ini aku kenal.",
  ui_story_5071_50711101_112_dialog_content = "Bagus sekali, tapi maafkan saya, Nona Hanstie, Anda boleh pergi dulu.",
  ui_story_5071_50711101_113_dialog_content = "Saya tidak setuju. Saya pikir saya lebih baik tinggal di sini.",
  ui_story_5071_50711101_114_dialog_content = "Aku mencium berita besar, jadi aku juga tidak akan pergi.",
  ui_story_5071_50711101_115_dialog_content = "...",
  ui_story_5071_50711101_116_dialog_content = "Kalian akan hidup dalam penyesalan, setiap satu dari kalian.",
  ui_story_5071_50711101_117_dialog_content = "Saya yakin kalian semua sadar akan kapasitas tiraninya, jadi mengapa mengabaikannya?",
  ui_story_5071_50711101_118_dialog_content = "Menyedihkan... Kalian semua begitu menyedihkan.",
  ui_story_5071_50711101_119_dialog_content = "Selamat tinggal, \"Nona Hanstie.\"",
  ui_story_5071_50711101_120_dialog_content = "Nah, kamu juga harus...",
  ui_story_5071_50711101_121_dialog_content = "Aku merasakan musuh!",
  ui_story_5071_50711101_122_dialog_content = "Lady Sheol, awas! Prajurit-prajurit itu—",
  ui_story_5071_50711101_123_dialog_content = "Mereka punya kaki tangan! Mereka—",
  ui_story_5071_50711101_124_dialog_content = "Diam!",
  ui_story_5071_50711101_125_dialog_content = "Ingat apa yang dikatakan bos. Jangan biarkan ada yang selamat.",
  ui_story_5071_50711101_126_dialog_content = "Ini tidak baik! <size=45>Semua orang, bersiaplah untuk pertempuran!</size>",
  ui_story_5071_50711102_1_dialog_content = "Personel keamanan semuanya...",
  ui_story_5071_50711102_2_dialog_content = "Sepertinya semua orang telah dibantai. *hela nafas*",
  ui_story_5071_50711102_3_dialog_content = "Ini hal yang baik kita berada di sisi ini...",
  ui_story_5071_50711102_4_dialog_content = "Kau baik-baik saja, Bos? Lihat ke luar jendela, aku di sini!",
  ui_story_5071_50711102_5_dialog_content = "Aku mengirimmu untuk memastikan orang-orang aman. Apa yang kamu lakukan kembali di sini?",
  ui_story_5071_50711102_6_dialog_content = "Saya melihat orang-orang jahat bertingkah mencurigakan dan menjadi khawatir tentang kamu.",
  ui_story_5071_50711102_7_dialog_content = "Jadi, Anda sudah mengendalikannya, bos?",
  ui_story_5071_50711102_8_dialog_content = "... Ayo dan bantu orang-orang keluar dari sini.",
  ui_story_5071_50711102_9_dialog_content = "Aku tidak akan menyebut PlayerName, tapi kenapa kamu tetap tinggal, Vergil?",
  ui_story_5071_50711102_10_dialog_content = "Hah? Ini kapalmu, 'kan, bos?",
  ui_story_5071_50711102_11_dialog_content = "Apa masalahnya? Saya masih dalam jam kerja, jadi saya harus bersikap terbaik, bukan?",
  ui_story_5071_50711102_12_dialog_content = "...",
  ui_story_5071_50711102_13_dialog_content = "Aku baru saja membaca naskah-naskah itu, Shadowlord.",
  ui_story_5071_50711102_14_dialog_content = "Cerita yang tertulis di dalamnya sangat mirip dengan ceritamu, tapi saya masih tidak percaya itu.",
  ui_story_5071_50711102_15_dialog_content = "Jadi, saya harus bertanya, apakah kamu benar-benar melakukan semua hal itu? Kepada Lady Melissa—",
  ui_story_5071_50711102_16_dialog_content = "PlayerName!",
  ui_story_5071_50711102_17_dialog_content = "Salah jika kamu mengabaikanku dan menuntut pertanggungjawaban dari pihak yang bertanggung jawab.",
  ui_story_5071_50711102_18_dialog_content = "M-Maaf...",
  ui_story_5071_50711102_19_dialog_content = "Meski sekarang bukan waktunya untuk membahasnya.",
  ui_story_5071_50711102_20_dialog_content = "Kita masih di pesawat, dan kita harus menangani kerusakan terlebih dahulu.",
  ui_story_5071_50711102_21_dialog_content = "Setelah ini selesai, kau pasti akan mendapatkan pembalasan dariku dengan bunga.",
  ui_story_5071_50711102_22_dialog_content = "Aku akan menunggumu.",
  ui_story_5071_50711102_23_dialog_content = "Ngomong-ngomong, kamu orang yang murah hati, 'kan, Shadowlord?",
  ui_story_5071_50711102_24_dialog_content = "Sudah jelas Anda telah berusaha keras dan melakukan banyak pertolongan untuk mereka.",
  ui_story_5071_50711102_25_dialog_content = "Hanya untuk mereka meninggalkanmu dan lari pada dorongan terkecil.",
  ui_story_5071_50711102_26_dialog_content = "Hei! Kenapa kamu juga berbicara secara misterius, Nona Sheol?",
  ui_story_5071_50711102_27_dialog_content = "Berhenti, sekarang juga! Ini bukan waktunya untuk saling bertarung. Kita harus bersatu.",
  ui_story_5071_50711102_28_dialog_content = "Aku ingin mewawancarai Shadowlord sekarang, tapi aku merasa waktunya belum tepat...",
  ui_story_5071_50711102_29_dialog_content = "Shadowlord, apa yang harus kita lakukan sekarang?",
  ui_story_5071_50711102_30_dialog_content = "Saya menghargai kalian semua yang tetap percaya padaku.",
  ui_story_5071_50711102_31_dialog_content = "Rakyatku akan mengantarkanmu kembali ke tanah dengan selamat.",
  ui_story_5071_50711102_32_dialog_content = "Seleucid, kirim kapal udara untuk evakuasi penumpang.",
  ui_story_5071_50711102_33_dialog_content = "Bayangan masa lalu itu mengejarku.",
  ui_story_5071_50711102_34_dialog_content = "Anda akan mengawal penumpang keluar dari kapal ini.",
  ui_story_5071_50711102_35_dialog_content = "Bos...",
  ui_story_5071_50711102_36_dialog_content = "Itu perintah.",
  ui_story_5071_50711102_37_dialog_content = "Oh, begitu…",
  ui_story_5071_50711102_38_dialog_content = "Ini adalah Bethel. Silakan masuk.",
  ui_story_5071_50711102_39_dialog_content = "Ayah, kami melihat tersangka di jalan pengangkutan menuju Twin Pavilions Bay.",
  ui_story_5071_50711102_40_dialog_content = "Mereka telah mengirim senjata dan tentara bayaran ke Umbraton dan telah ditangkap.",
  ui_story_5071_50711102_41_dialog_content = "Bagaimana perkembangan di pihakmu? Apakah peluncuran maiden berjalan tanpa hambatan?",
  ui_story_5071_50711102_42_dialog_content = "Semuanya baik-baik saja di sini, jangan khawatir.",
  ui_story_5071_50711102_43_dialog_content = "Bethel, \"tamu\" nakal kita mungkin akan muncul kembali di rumah.",
  ui_story_5071_50711102_44_dialog_content = "Sebagai tuan rumah, saya percaya kamu tahu bagaimana cara menyapa mereka.",
  ui_story_5071_50711102_45_dialog_content = "Siap, laksanakan. Tolong jaga kesehatanmu, Ayah.",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5071_50711102_47_dialog_content = "Ini buruk... Pesawatnya masih belum mendapatkan keseimbangannya kembali.",
  ui_story_5071_50711102_48_dialog_content = "Seluruh kapal bergetar, dan tampaknya kita mulai kehilangan momentum...",
  ui_story_5071_50711102_49_dialog_content = "Kamu adalah pilot Colossus yang berpengalaman, jadi tolong jangan menakutiku seperti itu, sayang.",
  ui_story_5071_50711102_50_dialog_content = "Ini seharusnya tidak terjadi jika perbaikan sudah selesai.",
  ui_story_5071_50711102_51_dialog_content = "Jika kondisi pesawat terus memburuk, kita akan terus kehilangan ketinggian... dan kita akan jatuh ke Umbraton!",
  ui_story_5071_50711102_52_dialog_content = "Nona Sheol! Nona Sheol! Berita buruk—",
  ui_story_5071_50711102_53_dialog_content = "Kami menemukan tim teknik kami di bawah sana. Mereka semua telah...",
  ui_story_5071_50711102_54_dialog_content = "Apa?",
  ui_story_5071_50711201_1_dialog_content = "Oh tidak, kita harus pergi ke master-control room sekarang.",
  ui_story_5071_50711201_2_dialog_content = "Pilot-pilot itu masih di sana!",
  ui_story_5071_50711201_3_dialog_content = "Ini adalah-",
  ui_story_5071_50711201_4_dialog_content = "Kita terlambat. Semua pilot... dan panel kontrol hancur.",
  ui_story_5071_50711201_5_dialog_content = "Ini benar-benar terlalu jauh...",
  ui_story_5071_50711201_6_dialog_content = "Kita harus memikirkan cara untuk memutar pesawat ini.",
  ui_story_5071_50711201_7_dialog_content = "Satu langkah di belakang lagi...",
  ui_story_5071_50711201_8_dialog_content = "...",
  ui_story_5071_50711201_9_dialog_content = "Eh, apa ini?",
  ui_story_5071_50711201_10_dialog_content = "Kamu benar-benar membuatnya terlihat seperti Soroz di sini?",
  ui_story_5071_50711201_11_dialog_content = "Saat itu, saya pikir kamu hanya bercanda...",
  ui_story_5071_50711201_12_dialog_content = "Jika Anda datang ke upacara sebagai tamu kehormatan khusus saya...",
  ui_story_5071_50711201_13_dialog_content = "Aku akan membuat ruang kontrol ini menjadi duplikat dari ruang kontrol Colossus!",
  ui_story_5071_50711201_14_dialog_content = "Jadi, kamu datang?",
  ui_story_5071_50711201_X11_dialog_content = "Ini tidak sulit bagi saya sama sekali.",
  ui_story_5071_50711201_15_dialog_content = "Tentu saja, kamu adalah gimmick utama dalam promosi ini, setelah semua.",
  ui_story_5071_50711201_16_dialog_content = "Jadi, mungkin aku bisa mengemudikannya?",
  ui_story_5071_50711201_17_dialog_content = "Itu benar! Kamu ahlinya, jadi lakukan apa yang kamu mau.",
  ui_story_5071_50711201_18_dialog_content = "Saya hanya perlu mulai bermain, dan seharusnya berfungsi seperti biasa—",
  ui_story_5071_50711201_19_dialog_content = "Hah—",
  ui_story_5071_50711201_20_dialog_content = "Tidak ada respon!",
  ui_story_5071_50711201_21_dialog_content = "Sistem kontrol ini benar-benar berbeda dari yang ada di Soroz!",
  ui_story_5071_50711201_X21_dialog_content = "Aku tidak tahu bagaimana cara memperbaikinya.",
  ui_story_5071_50711201_X22_dialog_content = "Benar, panel ini bukan asal-usul Caelestite tetapi barang antik tua yang saya beli.",
  ui_story_5071_50711201_22_dialog_content = "Mereka juga rusak.",
  ui_story_5071_50711201_23_dialog_content = "Itu karena itu hanya gimmick... Itu tidak bekerja, saya mengerti.",
  ui_story_5071_50711201_24_dialog_content = "Tapi bagaimana...",
  ui_story_5071_50711201_25_dialog_content = "Antik, kata kamu?",
  ui_story_5071_50711201_26_dialog_content = "Dan aku pernah melihat panel kontrol kuno seperti ini sebelumnya, semua orang!",
  ui_story_5071_50711201_27_dialog_content = "Anda tahu cara kerjanya? Bisakah Anda memperbaikinya?",
  ui_story_5071_50711201_28_dialog_content = "Berikan aku waktu, dan aku harus bisa memulihkannya.",
  ui_story_5071_50711201_29_dialog_content = "Masih ada waktu, bukan?",
  ui_story_5071_50711201_30_dialog_content = "Sepertinya kita jatuh semakin cepat dan cepat.",
  ui_story_5071_50711201_31_dialog_content = "Tunggu! Jika pesawat terbang ini benar-benar replika dari Colossus, maka strukturnya...",
  ui_story_5071_50711201_32_dialog_content = "Saya punya ide, semuanya!",
  ui_story_5071_50711201_33_dialog_content = "Jika kita bisa mengubah orientasi sayap dari luar, kita seharusnya bisa memperlambat penurunan kita dan melakukan pendaratan darurat.",
  ui_story_5071_50711201_34_dialog_content = "Bagaimana ini?",
  ui_story_5071_50711201_35_dialog_content = "Tolong ikutlah denganku!",
  ui_story_5071_50711201_36_dialog_content = "Ambil ini, PlayerName!",
  ui_story_5071_50711201_37_dialog_content = "Ini adalah buku panduan ringkas untuk memperkenalkan Anda pada skema kapal.",
  ui_story_5071_50711201_38_dialog_content = "Aku akan tetap di sini untuk melindungi Vergil dan meninggalkan kapal untukmu.",
  ui_story_5071_50711201_39_dialog_content = "Ayo.",
  ui_story_5071_50711201_40_dialog_content = "Tunggu, ada satu masalah lagi... Sayap pesawat terbuka. Kita akan membutuhkan pesawat ulang-alik untuk mendekat!",
  ui_story_5071_50711201_41_dialog_content = "Mari kita periksa geladak atas!",
  ui_story_5071_50711201_42_dialog_content = "PlayerName, Shadowlord, tolong...",
  ui_story_5071_50711201_X42_dialog_content = "Beruntung sekali, masih ada shuttle yang tersisa!",
  ui_story_5071_50711201_44_dialog_content = "Aku melihat Seleucid telah meninggalkan satu di belakang.",
  ui_story_5071_50711201_45_dialog_content = "Bangun dan katakan padaku apa yang harus dilakukan.",
  ui_story_5071_50711201_46_dialog_content = "Biarkan saya melihat skema struktur terlebih dahulu... Di sana!",
  ui_story_5071_50711201_47_dialog_content = "Baik kapal udara maupun Colossi memiliki sayap. Meskipun struktur mereka berbeda, logika di balik mereka sama persis.",
  ui_story_5071_50711201_48_dialog_content = "Dengan menyesuaikan sendi tepat di belakang sayap, kita dapat mengubah lintasan kapal dan membuatnya berbelok.",
  ui_story_5071_50711201_49_dialog_content = "Tunggu!",
  ui_story_5071_50711201_50_dialog_content = "Ah—",
  ui_story_5071_50711201_51_dialog_content = "Apakah ini \"sayap\" yang sedang kamu bicarakan?",
  ui_story_5071_50711201_52_dialog_content = "Haha, ini pasti lebih besar dari yang seharusnya.",
  ui_story_5071_50711201_53_dialog_content = "Kamu yakin bisa mengubah arahnya?",
  ui_story_5071_50711201_54_dialog_content = "Coba terbangkan kita sedikit lebih dekat sehingga saya bisa melihat mekanisme itu lebih dekat, Shadowlord!",
  ui_story_5071_50711201_55_dialog_content = "Ini adalah-",
  ui_story_5071_50711201_56_dialog_content = "Oh tidak, mekanisme ini jauh lebih kasar daripada yang ada di Colossi!",
  ui_story_5071_50711201_57_dialog_content = "Untuk menciptakan sayap yang bisa ditenagai oleh energi, mereka meninggalkan desain asli. Sayap-sayap ini sama sekali tidak bisa diatur secara manual...",
  ui_story_5071_50711201_58_dialog_content = "Haha! Bebas dan penuh semangat, inilah <color=#FFB400>mimpi</color> yang seharusnya dimiliki setiap anak muda!",
  ui_story_5071_50711201_59_dialog_content = "Dimengerti—",
  ui_story_5071_50711201_60_dialog_content = "Sayap yang membawa mimpi tidak akan mudah menyerah!",
  ui_story_5071_50711201_61_dialog_content = "Jangan mendekat, atau kita akan terseret ke dalam—",
  ui_story_5071_50711201_62_dialog_content = "Bagaimana caranya aku mengubah arah tanpa mendekat?",
  ui_story_5071_50711201_63_dialog_content = "Shadowlord?",
  ui_story_5071_50711201_64_dialog_content = "Kamu, ambil alih kemudi.",
  ui_story_5071_50711201_65_dialog_content = "Argh!",
  ui_story_5071_50711201_66_dialog_content = "Kamu terlalu sembrono! Jika kamu memasukkan tanganmu ke dalam roda gigi raksasa itu, kamu akan—",
  ui_story_5071_50711201_67_dialog_content = "Beritahu saya ke arah mana harus belok, PlayerName!",
  ui_story_5071_50711201_68_dialog_content = "Anda-",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5071_50711201_70_dialog_content = "(Tidak bisa dipercaya! Shadowlord entah bagaimana mampu menanggung beban seluruh sayap...)",
  ui_story_5071_50711201_71_dialog_content = "Menuju sebelah kirimu! Putar mekanisme itu dan itu akan menggerakkan sisa sayap!",
  ui_story_5071_50711201_72_dialog_content = "Hyaaaah!",
  ui_story_5071_50711201_73_dialog_content = "Coba jangan—jatuh—dengan tergesa-gesa!",
  ui_story_5071_50711201_74_dialog_content = "Kriek—Kriek—",
  ui_story_5071_50711201_75_dialog_content = "(Itu bergerak—sayap raksasa itu benar-benar bergerak!)",
  ui_story_5071_50711201_76_dialog_content = "Kamu berhasil, Shadowlord! Kita mengubah kursus!",
  ui_story_5071_50711201_77_dialog_content = "Masih belum cukup—",
  ui_story_5071_50711201_78_dialog_content = "Harus menjauhkannya dari Umbraton—",
  ui_story_5071_50711201_79_dialog_content = "Ayo jalan!",
  ui_story_5071_50711201_80_dialog_content = "Duar—",
  ui_story_5071_50711201_81_dialog_content = "Oh tidak! Mesin belakang meledak!",
  ui_story_5071_50711201_82_dialog_content = "(Pada tingkat ini, kita tidak akan bisa sepenuhnya mengubah arah sebelum jatuh!)",
  ui_story_5071_50711201_83_dialog_content = "Tidak cukup. Ini masih akan jatuh di tepi Umbraton...",
  ui_story_5071_50711201_84_dialog_content = "Kembali, Shadowlord! Jika kamu terus begini, kamu akan—",
  ui_story_5071_50711201_85_dialog_content = "Bangkit melawan angin!",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5071_50711201_87_dialog_content = "K-Kembang api?",
  ui_story_5071_50711201_88_dialog_content = "Siapa sih yang sedang menyalakan kembang api di airship sekarang ini...",
  ui_story_5071_50711201_89_dialog_content = "Hei, lihat itu!",
  ui_story_5071_50711201_90_dialog_content = "Pesawat Cloudrover Guild sedang terbang ke arah ini!",
  ui_story_5071_50711201_91_dialog_content = "Ini adalah salah satu perayaan untuk penerbangan perdananya... Saya hanya tidak menyangka itu akan begitu dekat dengan kita!",
  ui_story_5071_50711201_92_dialog_content = "Apa kembang api yang menakjubkan! Pesawat itu juga sangat spektakuler.",
  ui_story_5071_50711201_93_dialog_content = "Lady Sheol pasti ingin kita juga menikmati acara ini!",
  ui_story_5071_50711201_94_dialog_content = "Hei, kalian bodoh! Kenapa kalian hanya berdiri di sana?",
  ui_story_5071_50711201_95_dialog_content = "Cepat keluar dari sini! Pesawatnya akan segera jatuh!",
  ui_story_5071_50711201_96_dialog_content = "Mengapa Istvan Gang begitu mengancam?",
  ui_story_5071_50711201_97_dialog_content = "Lari! Saya dengar Shadowlord memulai pembantaian dan memusnahkan semua orang di pesawat udara!",
  ui_story_5071_50711201_98_dialog_content = "Mereka ingin menabrakkan Pesawat Cloudrover di perkampungan kumuh kita!",
  ui_story_5071_50711201_99_dialog_content = "Ikuti kami! Kita perlu mencari tempat berteduh di luar kota—",
  ui_story_5071_50711201_100_dialog_content = "Jauh-jauh dari kami! Kami tidak pernah menyinggungmu dengan cara apapun!",
  ui_story_5071_50711201_101_dialog_content = "Kami akan mulai menyerang jika kamu semakin mendekat!",
  ui_story_5071_50711201_102_dialog_content = "Mengapa kamu begitu paranoid terhadap kami? Hei, berhenti melempar batu ke orang-orang!",
  ui_story_5071_50711201_103_dialog_content = "Geng Istvan sedang menyerang warga sipil!",
  ui_story_5071_50711201_104_dialog_content = "<size=45>Hai!</size>",
  ui_story_5071_50711201_105_dialog_content = "Tenanglah, semua orang... Serang kami satu kali lagi dan kami tidak punya pilihan selain membalas.",
  ui_story_5071_50711201_106_dialog_content = "Kenapa tiba-tiba orang-orang menyebalkan ini...",
  ui_story_5071_50711201_107_dialog_content = "Pasti wanita itu yang mencoba membuat keributan di pesawat udara!",
  ui_story_5071_50711201_108_dialog_content = "Berhenti sekarang juga!",
  ui_story_5071_50711201_109_dialog_content = "*huft* Ceroboh seperti biasanya, saya lihat. Ini tidak akan mudah untuk diatasi sekarang.",
  ui_story_5071_50711201_110_dialog_content = "Ini adalah-",
  ui_story_5071_50711201_111_dialog_content = "Apakah pesawat itu mengubah arah?",
  ui_story_5071_50711201_112_dialog_content = "Sepertinya mereka telah memperbaiki panel kontrol.",
  ui_story_5071_50711201_113_dialog_content = "Mari kita kembali.",
  ui_story_5071_50711201_114_dialog_content = "Tunggu.",
  ui_story_5071_50711201_115_dialog_content = "Tombol ini untuk menyalakan kembang api, tombol ini untuk siaran, dan tombol ini adalah...",
  ui_story_5071_50711201_116_dialog_content = "Vergil! Kamu benar-benar berhasil memperbaiki panel kontrol?",
  ui_story_5071_50711201_117_dialog_content = "Tidak benar-benar. Kontrol arah sudah bekerja lagi, tetapi kita masih tidak bisa kembali ke ketinggian.",
  ui_story_5071_50711201_118_dialog_content = "Oh... Mungkin itu karena salah satu mesin meledak...",
  ui_story_5071_50711201_119_dialog_content = "Ini masih akan jatuh dengan cara ini...",
  ui_story_5071_50711201_120_dialog_content = "Jika kita mengarahkannya dengan benar dan mendarat di Sungai Emas, mungkin pesawat bisa tetap utuh.",
  ui_story_5071_50711201_121_dialog_content = "Ke arah mana aku harus terbang, Nona Sheol? Menuju sungai?",
  ui_story_5071_50711201_122_dialog_content = "Tapi bukankah orang-orang di kedua sisi sungai akan menderita?",
  ui_story_5071_50711201_123_dialog_content = "Ayo bergerak menuju lembah. Tidak ada yang tinggal di sana.",
  ui_story_5071_50711201_124_dialog_content = "Tapi jika aku melakukan itu, pesawat ini akan berubah menjadi tumpukan sampah.",
  ui_story_5071_50711201_125_dialog_content = "Ini semua salahku tentang pesawat terbangmu...",
  ui_story_5071_50711201_126_dialog_content = "Apa yang kamu katakan, Shadowlord? Kau membuatnya terdengar seolah-olah kau adalah dalang di balik semua ini.",
  ui_story_5071_50711201_127_dialog_content = "...",
  ui_story_5071_50711201_128_dialog_content = "Jelaskan padaku bagaimana cara menerbangkannya dan kalian bisa pergi.",
  ui_story_5071_50711201_129_dialog_content = "Lady Sheol?",
  ui_story_5071_50711201_130_dialog_content = "Seseorang harus menerbangkan benda ini, kan? Belum lagi ini milikku.",
  ui_story_5071_50711201_131_dialog_content = "Jadi, kalian harus—",
  ui_story_5071_50711201_132_dialog_content = "Pergilah dan biarkan aku yang menerbangkannya.",
  ui_story_5071_50711201_133_dialog_content = "Shadowlord?",
  ui_story_5071_50711201_134_dialog_content = "Apa yang kamu lakukan—",
  ui_story_5071_50711201_135_dialog_content = "Berhenti mencoba melakukan pekerjaan orang lain, Lady Sheol.",
  ui_story_5071_50711201_136_dialog_content = "Belum lagi aku sudah punya pengalaman dengan ini.",
  ui_story_5071_50711201_137_dialog_content = "Pergilah. Mereka yang mendambakan terbang tidak seharusnya memiliki mimpi mereka hancur di langit.",
  ui_story_5071_50711201_138_dialog_content = "Shadowlord...",
  ui_story_5071_50711201_139_dialog_content = "Bawa kedua anak itu dan kembali ke tempat yang aman.",
  ui_story_5071_50711201_140_dialog_content = "... Apa kamu masih ingat bantuan yang kamu berutang padaku?",
  ui_story_5071_50711201_141_dialog_content = "Saya tidak melupakan janji-janji saya.",
  ui_story_5071_50711201_142_dialog_content = "Baik. Aku akan menjaga mereka.",
  ui_story_5071_50711201_143_dialog_content = "Sebagai gantinya, saya harap Anda menepati janji Anda dan memenuhi permintaan saya.",
  ui_story_5071_50711201_144_dialog_content = "Keinginanku adalah tetap hidup, sesederhana itu.",
  ui_story_5071_50711201_145_dialog_content = "... Aku berjanji.",
  ui_story_5071_50711201_146_dialog_content = "Jangan buang waktu lagi. Ayo pergi!",
  ui_story_5071_50711201_147_dialog_content = "May Bayangan menjagamu.",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>Valon</color>, teman lama... Mari kita berikan lebih banyak dalam mimpi ini...",
  ui_story_5071_50711202_1_dialog_content = "Akhirnya, kamu kembali juga, Tuan Borriman.",
  ui_story_5071_50711202_2_dialog_content = "Saya rasa tidak perlu ada perkenalan.",
  ui_story_5071_50711202_3_dialog_content = "L-Lady Bethel? Ah, kenapa tiba-tiba datang?",
  ui_story_5071_50711202_4_dialog_content = "Kamu bahkan tidak memberi tahu kami—",
  ui_story_5071_50711202_5_dialog_content = "Saya menangkap sekelompok tentara bayaran bersenjata di luar kota. Mereka mencoba menyerang Umbraton.",
  ui_story_5071_50711202_6_dialog_content = "Berdasarkan kendaraan mereka, personel pendukung, dan kesaksian ini...",
  ui_story_5071_50711202_7_dialog_content = "Kami mencurigai Guild Red Panther Anda, Guild Gray Parrot, dan Geng Rust Falcon...",
  ui_story_5071_50711202_8_dialog_content = "... adalah di antara minimal tiga kaki tangan dalam insiden ini.",
  ui_story_5071_50711202_9_dialog_content = "Ini adalah foto bukti Anda melakukan perdagangan senjata secara ilegal.",
  ui_story_5071_50711202_10_dialog_content = "Saya ingin Anda bergabung dengan kami di bawah Regulasi Keamanan Umbraton.",
  ui_story_5071_50711202_11_dialog_content = "T-Tunggu sebentar. Pasti ada semacam kesalahpahaman.",
  ui_story_5071_50711202_12_dialog_content = "Kamu tidak bisa membawaku pergi seperti ini!",
  ui_story_5071_50711202_13_dialog_content = "Hanya satu jam lagi. Tidak! Mungkin bahkan setengah jam lagi atau sekitar itu...",
  ui_story_5071_50711202_14_dialog_content = "Maksudmu?",
  ui_story_5071_50711202_15_dialog_content = "Seolah-olah kamu memiliki rencana...",
  ui_story_5071_50711202_16_dialog_content = "<size=45>Ah!</size>",
  ui_story_5071_50711202_17_dialog_content = "Apa yang terjadi di luar sana?",
  ui_story_5071_50711202_18_dialog_content = "Kenapa di mana-mana kacau?",
  ui_story_5071_50711202_19_dialog_content = "Bawa dia ke tahanan.",
  ui_story_5071_50711202_20_dialog_content = "Siap, Kapten!",
  ui_story_5071_50711202_21_dialog_content = "Bethel ke guild. Apa yang terjadi?",
  ui_story_5071_50711202_22_dialog_content = "Lady Bethel, kamu sudah kembali!",
  ui_story_5071_50711202_23_dialog_content = "Shadowlord adalah...",
  ui_story_5071_50711202_24_dialog_content = "Tenanglah. Apa yang terjadi pada ayahku? Ceritakan padaku!",
  ui_story_5071_50711202_25_dialog_content = "Pesawat yang ditumpangi Lady Sheol dan dia akan segera jatuh!",
  ui_story_5071_50711202_26_dialog_content = "Apa?",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5071_50711202_28_dialog_content = "Itu... suara pesawat jatuh?",
  ui_story_5071_50711202_29_dialog_content = "Lady Bethel, kita harus bagaimana?",
  ui_story_5071_50711202_30_dialog_content = "Benda yang jatuh dari pesawat itu tampaknya telah mendarat di kota.",
  ui_story_5071_50711202_31_dialog_content = "Ada seseorang yang bersembunyi di antara penduduk kota dan menghasut kerusuhan. Sementara itu, banyak tentara bayaran di luar kota sedang...",
  ui_story_5071_50711202_32_dialog_content = "Seleucid ingin kita membantu Shadowlord, tetapi tanpa persetujuanmu—",
  ui_story_5071_50711202_33_dialog_content = "Ayah...",
  ui_story_5071_50711202_34_dialog_content = "Aku tahu.",
  ui_story_5071_50711202_35_dialog_content = "Dia mengirimku pergi karena dia merasakan bahaya yang segera datang.",
  ui_story_5071_50711202_36_dialog_content = "Lady Bethel?",
  ui_story_5071_50711202_37_dialog_content = "Tenang saja, aku rasa tidak akan terjadi apa-apa pada Shadowlord.",
  ui_story_5071_50711202_38_dialog_content = "Juga, berikan perintahku kepada semua orang di guild.",
  ui_story_5071_50711202_39_dialog_content = "Siap, Kapten!",
  ui_story_5071_50711202_40_dialog_content = "Seseorang menargetkan Umbraton. Kita tidak boleh panik dan memberi mereka celah.",
  ui_story_5071_50711202_41_dialog_content = "Aku akan menyerahkan daftar dan bukti ini ke Guardians. Kirim Kleken ke markas mereka—",
  ui_story_5071_50711202_42_dialog_content = "Beritahu dia untuk membantu para Guardian menangkap para pelaku, dan waspadalah karena mereka akan memanfaatkan kesempatan untuk melarikan diri atau melawan.",
  ui_story_5071_50711202_43_dialog_content = "Siap, Kapten!",
  ui_story_5071_50711202_44_dialog_content = "Beritahu Seleucid untuk merakit unit tempur Guardians dan kirim setengahnya untuk mempertahankan pinggiran kota.",
  ui_story_5071_50711202_45_dialog_content = "Panggil Patty dan Patsy. Kirim mereka untuk membantu saya dengan kekacauan di kota.",
  ui_story_5071_50711202_46_dialog_content = "Juga, kirimkan bala bantuan utama untuk membantu para penduduk. Kemudian kirim dua unit untuk mencari Shadowlord!",
  ui_story_5071_50711202_47_dialog_content = "Sebelum dia kembali, kita harus menjaga ketertiban dan mempertahankan tempat ini atas namanya, mengerti?",
  ui_story_5071_50711202_48_dialog_content = "Ya, Lady Bethel!",
  ui_story_5071_50711202_49_dialog_content = "Aku percaya padamu, Ayah, untuk menjadi dirimu seperti biasanya...",
  ui_story_5071_50711202_50_dialog_content = "Dan buat <color=#FFB400>kembali emas</color> lainnya!",
  ui_story_5071_50711301_1_dialog_content = "Pesawat yang begitu indah... hilang begitu saja...",
  ui_story_5071_50711301_2_dialog_content = "Shadowlord berhasil! Dia mendarat darurat di bagian kosong dari padang gurun—",
  ui_story_5071_50711301_3_dialog_content = "Mendekatlah sebelum kamu mendarat, sayang.",
  ui_story_5071_50711301_4_dialog_content = "Kita baru saja di udara, tapi sekarang...",
  ui_story_5071_50711301_5_dialog_content = "Mimpi orang-orang di Umbraton tidak pernah bertahan lama. Tidak ada yang bisa kamu lakukan tentang itu.",
  ui_story_5071_50711301_6_dialog_content = "Api ini begitu ganas... Tidak ada yang tersisa kecuali sisa-sisa yang hangus...",
  ui_story_5071_50711301_7_dialog_content = "Tidak ada yang dilepaskan, bahkan karya seni yang berharga sekalipun... Ap-Apa yang akan kita lakukan sekarang, Nona Sheol?",
  ui_story_5071_50711301_8_dialog_content = "Aku tidak terlalu peduli dengan koleksi pribadiku dibandingkan dengan barang lelang dari klien, beberapa di antaranya bahkan tidak bisa direproduksi... Aku harus membayar untuk mereka dari kantongku sendiri.",
  ui_story_5071_50711301_9_dialog_content = "Nona Sheol...",
  ui_story_5071_50711301_10_dialog_content = "Aku baik-baik saja, sayang. Dalam bisnis, ada kalanya menang dan ada kalanya kalah.",
  ui_story_5071_50711301_11_dialog_content = "Dan aku belum benar-benar dalam masalah. Mari kita cari Shadowlord.",
  ui_story_5071_50711301_12_dialog_content = "I-Ini sangat panas... Apakah Shadowlord benar-benar bisa bertahan dari sesuatu seperti ini?",
  ui_story_5071_50711301_13_dialog_content = "Bersembunyi di tempat yang tak terlihat adalah hal terbaik yang dilakukan oleh Bayangan. Dia pasti masih hidup.",
  ui_story_5071_50711301_14_dialog_content = "Hati-hati, Nona Sheol! Api di sana terlalu kuat!",
  ui_story_5071_50711301_15_dialog_content = "(Masih tidak ada... Aku tidak bisa merasakan keberadaan Shadowlord di mana pun.)",
  ui_story_5071_50711301_16_dialog_content = "Shadowlord? Shadowlord?",
  ui_story_5071_50711301_17_dialog_content = "Apa pendengaranmu menurun karena usia tua? Berhenti bermain-main.",
  ui_story_5071_50711301_18_dialog_content = "(Apa yang akan terjadi pada Umbraton? Dan Bethel... Apa yang seharusnya saya katakan padanya...)",
  ui_story_5071_50711301_19_dialog_content = "Ini tidak akan berhasil, Lady Sheol! Tolong keluar sebelum semuanya terbakar...",
  ui_story_5071_50711301_20_dialog_content = "Dia masih memiliki hutang yang harus diselesaikan denganku. Kreditnya terlalu baik untuk kabur!",
  ui_story_5071_50711301_21_dialog_content = "Tapi Nona Sheol...",
  ui_story_5071_50711301_22_dialog_content = "Saya tidak mengerti... Apakah Shadowlord itu orang baik, atau orang jahat?",
  ui_story_5071_50711301_23_dialog_content = "Vergil...",
  ui_story_5071_50711301_24_dialog_content = "Bagi orang dewasa, hal-hal tidak pernah hanya hitam atau putih.",
  ui_story_5071_50711301_25_dialog_content = "Tapi dia mempertaruhkan dirinya untuk menyelamatkan kita—itu adalah fakta yang tak terbantahkan.",
  ui_story_5071_50711301_26_dialog_content = "Tapi kobaran api... Kita harus mendapatkan seseorang untuk memadamkan api itu.",
  ui_story_5071_50711301_27_dialog_content = "Haruskah kita memberitahu Bethel?",
  ui_story_5071_50711301_28_dialog_content = "*Huff* Bethel harus diberitahu tentang ini.",
  ui_story_5071_50711301_29_dialog_content = "Terutama ketika saya mencium bau konspirasi di sekelilingnya.",
  ui_story_5071_50711301_30_dialog_content = "Nyonya Yvonne kemungkinan meninggal karena racun, dan Lumo Guards menyerang kami di kapal...",
  ui_story_5071_50711301_31_dialog_content = "Otak di balik semuanya bukanlah menargetkan saya, tetapi Umbraton—atau lebih spesifik, Shadowlord.",
  ui_story_5071_50711301_32_dialog_content = "Shadowlord menyebutkan \"Bayangan dari masa lalu.\" Mungkin dia sudah tahu siapa yang ada di balik itu?",
  ui_story_5071_50711301_33_dialog_content = "Bayangan masa lalu? Lalu saya percaya Nyonya Hanstie memiliki sesuatu untuk dikatakan tentang itu.",
  ui_story_5071_50711301_34_dialog_content = "Sebentar, ada yang datang!",
  ui_story_5071_50711301_35_dialog_content = "Hoot—Hoot—",
  ui_story_5071_50711301_36_dialog_content = "Apakah itu... burung hantu?",
  ui_story_5071_50711301_37_dialog_content = "Bagus, kamu menemukannya. Kembali kepadaku sekarang.",
  ui_story_5071_50711301_38_dialog_content = "Hoot—Hoot—",
  ui_story_5071_50711301_39_dialog_content = "Apa kau... Nyonya Hanstie?",
  ui_story_5071_50711301_40_dialog_content = "(Itu burung hantu... Ada sesuatu yang sangat familiar tentang itu...)",
  ui_story_5071_50711301_41_dialog_content = "Tidak bisa percaya ini adalah tempatnya... Dulu ada Lubang yang mengesankan di sini berabad-abad yang lalu.",
  ui_story_5071_50711301_42_dialog_content = "Ini juga tempat di mana pengkhianat itu membunuh saudaranya.",
  ui_story_5071_50711301_43_dialog_content = "!",
  ui_story_5071_50711301_44_dialog_content = "Bisakah ini adalah takdir? Aku kembali berada di sisimu, Valon.",
  ui_story_5071_50711301_45_dialog_content = "Dan si pengkhianat itu juga berhasil mendarat darurat di tempat ini!",
  ui_story_5071_50711301_46_dialog_content = "Tampaknya bahkan Umbraton tidak akan menyelamatkannya dari pembalasan terakhir yang pantas dia terima!",
  ui_story_5071_50711301_47_dialog_content = "Aku tak perlu lagi mengotori tanganku...",
  ui_story_5071_50711301_48_dialog_content = "Hehe.. Hehehehe.",
  ui_story_5071_50711301_49_dialog_content = "Aku tahu. Kamu adalah \"bayangan masa lalu\" Shadowlord, bukan, Nyonya Hanstie?",
  ui_story_5071_50711301_50_dialog_content = "Apa yang sebenarnya terjadi saat itu? Tempat ini...",
  ui_story_5071_50711301_51_dialog_content = "Apakah penjelasan penulis tersebut tidak cukup jelas untuk Anda?",
  ui_story_5071_50711301_52_dialog_content = "\"Dengan darah dingin, pengkhianat yang dikenal sebagai Kade membunuh Valon, saudara tercintanya. Dengan melakukan itu, dia merampas segala yang dimiliki Valon, dan mengkhianati Umbraton.\"",
  ui_story_5071_50711301_53_dialog_content = "Sebagai bagian dari masa lalu yang dia coba hapus, aku terpaksa hidup di luar kota selama bertahun-tahun ini.",
  ui_story_5071_50711301_54_dialog_content = "Saya menderita penghinaan yang tak terkatakan saat saya mencapai puncak dunia bisnis, semua demi agar suatu hari nanti saya bisa kembali ke kampung halaman saya—",
  ui_story_5071_50711301_55_dialog_content = "Dan merobek topeng pengkhianat itu dengan kedua tangan ku sendiri!",
  ui_story_5071_50711301_56_dialog_content = "Dia tidak layak mendapatkan nama belakang Valon! Dia tidak pantas menyebut dirinya \"Istvan\"!",
  ui_story_5071_50711301_57_dialog_content = "Maaf mengganggu—",
  ui_story_5071_50711301_58_dialog_content = "Situasi sebelumnya sangat gila sampai-sampai aku tidak memiliki kesempatan untuk berbicara...",
  ui_story_5071_50711301_59_dialog_content = "Selama ini aku bertanya-tanya tentang sesuatu. Apakah Ny. Yvonne benar-benar menulis naskah-naskah yang kita lihat dengan tangannya sendiri?",
  ui_story_5071_50711301_60_dialog_content = "Apa yang kamu katakan, Vergil?",
  ui_story_5071_50711301_61_dialog_content = "Nyonya Yvonne sangat bersemangat tentang menulis, dan tulisan tangannya mencerminkan itu. Tulisan tangannya biasanya sangat bebas, dan setiap kata ditulis dengan sangat sedikit perhatian terhadap estetika.",
  ui_story_5071_50711301_62_dialog_content = "Namun, naskah-naskah terakhir itu ditulis dengan sangat teliti, dan tintanya jauh lebih gelap. Tidak hanya itu, bentuk dan maksud di balik kata-kata tersebut benar-benar berbeda.",
  ui_story_5071_50711301_63_dialog_content = "Ada... tingkat keahlian tertentu pada mereka.",
  ui_story_5071_50711301_64_dialog_content = "Ada juga aroma samar yang tertinggal di halaman-halaman manuskrip tersebut.",
  ui_story_5071_50711301_65_dialog_content = "... Petunjuk-petunjuk itu memberitahuku bahwa itu adalah pekerjaan dari \"A,\" pemalsu ulung.",
  ui_story_5071_50711301_66_dialog_content = "Sebuah aroma...",
  ui_story_5071_50711301_67_dialog_content = "Baunya seperti <color=#FFB400>bunga lili</color>!",
  ui_story_5071_50711301_68_dialog_content = "\"Saya suka cara Anda menggambarkannya: misterius, kuat, tanpa hambatan.\"",
  ui_story_5071_50711301_69_dialog_content = "\"Kagumku pada perannya sebagai penjaga yang diam adalah alasan aku sangat menyukai bunga lili.\"",
  ui_story_5071_50711301_70_dialog_content = "\"Kenangan abadi, cinta yang tak terhentikan, dan berkat yang mendalam. Itulah yang disimbolkan oleh bunga lili.\"",
  ui_story_5071_50711301_71_dialog_content = "Hanstie...",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>Ms. Hanstie tersenyum tipis, tidak menyangkal maupun mengakui apapun.</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>Kebenaran terendam dalam tinta. Pada titik ini, apakah penting siapa yang menulisnya, Yvonne atau Hanstie?</color>",
  ui_story_5071_50711301_74_dialog_content = "Kita semua mengenakan topeng yang berbeda-beda. Apakah aku \"A\" atau tidak, tidak ada pengaruhnya pada hasil akhir.",
  ui_story_5071_50711301_75_dialog_content = "*isak tangis* Tapi kenapa kamu melakukan ini? Aku... Aku selalu mengagumimu...",
  ui_story_5071_50711301_76_dialog_content = "Yah, Ny. Yvonne memang menyebutkan bahwa dia mendapatkan inspirasi dari \"teman seniman.\"",
  ui_story_5071_50711301_77_dialog_content = "Ternyata teman itu adalah kamu.",
  ui_story_5071_50711301_78_dialog_content = "Kamu memang tipe yang langsung turun tangan, melakukan semuanya demi dendam lama.",
  ui_story_5071_50711301_79_dialog_content = "Sebagai kerugian tambahan dalam skema Anda, saya ingin tahu apakah Anda akan mengganti saya untuk pesawat udara dan kerugian besar saya.",
  ui_story_5071_50711301_80_dialog_content = "Jika mimpi yang dicurimu mati di sini, aku tidak memiliki keberatan tentang itu.",
  ui_story_5071_50711301_81_dialog_content = "Oh, sayangku Nyonya Hanstie, itu sebenarnya adalah mimpiku.",
  ui_story_5071_50711301_82_dialog_content = "Ini tidak seperti cerita karangan yang kamu buat—",
  ui_story_5071_50711301_83_dialog_content = "Kamu telah seenaknya berbicara tentang bagaimana ibuku meninggal, bukan?",
  ui_story_5071_50711301_84_dialog_content = "Mungkin itu benar—",
  ui_story_5071_50711301_85_dialog_content = "Atau mungkin itu hanya kabar angin belaka.",
  ui_story_5071_50711301_86_dialog_content = "Bagaimanapun juga, rumor seperti itu tidak akan tersebar di tempat pertama jika tidak ada bukti.",
  ui_story_5071_50711301_87_dialog_content = "Saya sama sekali tidak tertarik dengan kebenaran tentang Lady Melissa. Saya puas selama saya bisa terus menggunakan rumor tentang dia.",
  ui_story_5071_50711301_88_dialog_content = "Ya, kalian semua seharusnya bisa melihat wajah asli Kade sekarang.",
  ui_story_5071_50711301_89_dialog_content = "Tidak—",
  ui_story_5071_50711301_90_dialog_content = "Ini... Ini tidak masuk akal!",
  ui_story_5071_50711301_91_dialog_content = "Dan apa yang bisa kamu ketahui, anak kecil?",
  ui_story_5071_50711301_92_dialog_content = "Kamu selalu berbicara tentang menunjukkan kebenaran tentang masa lalu kepada orang lain. Kenapa masa lalu Lady Mercury harus berbeda?",
  ui_story_5071_50711301_93_dialog_content = "Kamu tahu betapa pentingnya bagi Nona Sheol untuk belajar tentang ibunya...",
  ui_story_5071_50711301_94_dialog_content = "Tapi kamu hanya menggunakan pengetahuan itu sebagai alat tawar-menawar untuk menyakiti orang lain—",
  ui_story_5071_50711301_95_dialog_content = "Bisa-bisanya kamu begitu egois!",
  ui_story_5071_50711301_96_dialog_content = "PlayerName…",
  ui_story_5071_50711301_97_dialog_content = "Cukup!",
  ui_story_5071_50711301_98_dialog_content = "Anda mencari nafkah dengan membuat barang palsu, tetapi Anda tidak bisa menahan diri untuk tidak meninggalkan tanda tangan Anda sendiri pada mereka.",
  ui_story_5071_50711301_99_dialog_content = "Untuk mendapatkan balas dendammu, kamu menggunakan cara yang paling kejam dan tercela—",
  ui_story_5071_50711301_100_dialog_content = "Kamu mungkin ingin mengungkap masa lalu Shadowlord, tetapi tidak ada sedikit pun kebenaran di balik tindakanmu.",
  ui_story_5071_50711301_101_dialog_content = "Seseorang yang egois dan arogan seperti kamu hanya akan menargetkan Shadowlord untuk melayani kepentingan mereka sendiri...",
  ui_story_5071_50711301_102_dialog_content = "Aku sudah bilang cukup, anak nakal yang tak berguna!",
  ui_story_5071_50711301_103_dialog_content = "Ayo sekarang, itu di bawah standarmu, Lady Hanstie.",
  ui_story_5071_50711301_104_dialog_content = "Lihat, kamu bahkan menakuti Vergil.",
  ui_story_5071_50711301_105_dialog_content = "Nyonya Yvonne diracuni hingga tewas.",
  ui_story_5071_50711301_106_dialog_content = "Aku pernah melihat racun serupa sebelumnya...",
  ui_story_5071_50711301_107_dialog_content = "Aku sudah muak mendengar kata-katamu.",
  ui_story_5071_50711301_108_dialog_content = "Sepertinya tidak ada yang bisa membujuk kalian, orang-orang keras kepala ini, untuk meninggalkan jalan yang salah ini.",
  ui_story_5071_50711301_109_dialog_content = "Saya tidak punya pilihan selain mengubur beberapa anak buah Kade di tempat peristirahatan Valon.",
  ui_story_5071_50711301_110_dialog_content = "Keluarlah, teman-teman!",
  ui_story_5071_50711301_111_dialog_content = "Mulai serius sekarang, begitu rupanya.",
  ui_story_5071_50711301_112_dialog_content = "Kami telah dikelilingi...",
  ui_story_5071_50711301_113_dialog_content = "Aku pikir sudah waktunya kamu melakukan apa yang kamu bisa lakukan dengan terbaik, sayang.",
  ui_story_5071_50711301_114_dialog_content = "Sebelumnya, saya hanya melihatmu menavigasi orang lain. Biarkan saya mengalaminya secara langsung hari ini!",
  ui_story_5071_50711301_115_dialog_content = "Dapatkan Vergil dan berdirilah di belakangku!",
  ui_story_5071_50711301_116_dialog_content = "Aku tidak bisa kehilangan klien dan karyawan terbaikku.",
  ui_story_5071_50711302_1_dialog_content = "Mereka mendapatkan lebih banyak bala bantuan. Itu tidak baik.",
  ui_story_5071_50711302_2_dialog_content = "Meski kamu ada di sini, sayang, kita tidak akan bertahan.",
  ui_story_5071_50711302_3_dialog_content = "Bethel dan yang lain pasti sudah menyadari keributan sebesar ini. Saya yakin mereka sudah dalam perjalanan...",
  ui_story_5071_50711302_4_dialog_content = "Aku khawatir kita tidak bisa bertahan sampai saat itu.",
  ui_story_5071_50711302_5_dialog_content = "Saya seorang wanita bisnis, bukan pejuang, tapi kita tidak punya pilihan lain...",
  ui_story_5071_50711302_6_dialog_content = "PlayerName, Vergil, kalian berdua pergi cari Shadowlord. Aku akan menangani mereka.",
  ui_story_5071_50711302_7_dialog_content = "Tapi—",
  ui_story_5071_50711302_8_dialog_content = "Percayalah padanya! Saya belum pernah melihat siapa pun yang lebih menepati janjinya daripada dia selama bertahun-tahun saya berbisnis.",
  ui_story_5071_50711302_9_dialog_content = "Tolong percaya padanya dan dirimu sendiri, PlayerName.",
  ui_story_5071_50711302_10_dialog_content = "Hanya kamu yang bisa menemukannya dalam kekacauan ini. Jangan menyerah!",
  ui_story_5071_50711302_11_dialog_content = "... Aku mengerti.",
  ui_story_5071_50711302_12_dialog_content = "Ayo, Vergil.",
  ui_story_5071_50711302_13_dialog_content = "Meninggalkan begitu cepat?",
  ui_story_5071_50711302_14_dialog_content = "Apa yang membuat Anda terburu-buru, Nyonya Hanstie? Kita masih memiliki urusan yang belum selesai.",
  ui_story_5071_50711302_15_dialog_content = "Rendah sekali berbohong tentang ibu seseorang, kamu tahu.",
  ui_story_5071_50711302_16_dialog_content = "Seperti yang diharapkan dari putri Mrs. Red Mercury, sifatmu tidak berbeda dengan dirinya.",
  ui_story_5071_50711302_17_dialog_content = "Meskipun aku sangat mengaguminya, aku tidak pernah peduli padamu dalam hidupku.",
  ui_story_5071_50711302_18_dialog_content = "Jadi, apa yang telah saya lakukan salah, dan haruskah saya meminta maaf?",
  ui_story_5071_50711302_19_dialog_content = "Kamu benar-benar orang bodoh yang kurang ajar.",
  ui_story_5071_50711302_20_dialog_content = "Mungkin sekarang kamu tahu sedikit tentang bisnis, tapi penglihatanmu masih sama buruknya.",
  ui_story_5071_50711302_21_dialog_content = "Sejak terakhir kali, kau tidak melakukan apa-apa selain menghalangi jalanku.",
  ui_story_5071_50711302_22_dialog_content = "Waktu itu? Sekarang saya harus bertanya kapan itu terjadi.",
  ui_story_5071_50711302_23_dialog_content = "... Itu hanyalah kesalahan kecil, tetapi dosa terbesarmu adalah berpikir bahwa kamu bisa mencuri mimpi orang lain tanpa rasa malu.",
  ui_story_5071_50711302_24_dialog_content = "Akulah satu-satunya orang yang bisa meneruskan mimpi Valon!",
  ui_story_5071_50711302_25_dialog_content = "Kamu tidak layak!",
  ui_story_5071_50711302_26_dialog_content = "PlayerName benar. Kamu sudah menjadi pemimpin guild, namun masih lebih egois daripada anak kecil.",
  ui_story_5071_50711302_27_dialog_content = "Kamu dan Kade benar-benar tidak berbeda satu sama lain—aku tidak akan menahan diri terhadapmu tidak peduli seberapa mirip kamu dengan ibumu.",
  ui_story_5071_50711302_28_dialog_content = "Aku akan menghancurkanmu, bersama dengan Kade dan Cloudrover Guild berhargamu—",
  ui_story_5071_50711302_29_dialog_content = "Aku akan membawa kalian semua menabrak ke <color=#FFB400>tanah</color>!",
  ui_story_5071_50711302_30_dialog_content = "Baiklah... Karena kamu sudah mencela saya, apa lagi yang bisa merusak citra saya?",
  ui_story_5071_50711302_31_dialog_content = "(Shadowlord... Apakah kamu benar-benar masih hidup di luar sana? Jika iya, di mana kamu?)",
  ui_story_5071_50711302_32_dialog_content = "(Atau apakah Lady Sheol hanya mencoba memberi kita waktu untuk melarikan diri?)",
  ui_story_5071_50711302_33_dialog_content = "(Tolong biarkan aku mendengar suaramu... atau else—)",
  ui_story_5071_50711302_34_dialog_content = "*batuk* As-Asapnya—semakin tebal—",
  ui_story_5071_50711302_35_dialog_content = "Maaf, Vergil... Tapi aku harus terus mencari Shadowlord. Sebaiknya kamu kembali ke Umbraton dan meminta bantuan.",
  ui_story_5071_50711302_36_dialog_content = "Saya tidak bisa melakukan itu. Lady Sheol meminta kita berdua untuk mencarinya.",
  ui_story_5071_50711302_37_dialog_content = "Dia bilang Shadowlord selalu menepati janjinya, jadi saya juga akan percaya padanya!",
  ui_story_5071_50711302_38_dialog_content = "Virgil... Hah?",
  ui_story_5071_50711302_39_dialog_content = "(Saya merasakan campuran emosi kuat dan kacau, dan itu berasal dari dalam-dalam nyala api!)",
  ui_story_5071_50711302_40_dialog_content = "Vergil, kita perlu melewati api-api ini—",
  ui_story_5071_50711302_41_dialog_content = "Aduh—T-Tunggu aku!",
  ui_story_5071_50711302_42_dialog_content = "(Shadowlord... Jika kamu benar-benar ada di sana, tolong katakan sesuatu—)",
  ui_story_5071_50711302_43_dialog_content = "Shadowlord... Shadowlord!",
  ui_story_5071_50711302_44_dialog_content = "Shadowlord—",
  ui_story_5071_50711302_45_dialog_content = "PlayerName?",
  ui_story_5071_50711302_46_dialog_content = "Ini benar-benar kamu! Syukurlah kau... Hah?",
  ui_story_5071_50711302_47_dialog_content = "Awas, di belakangmu!",
  ui_story_5071_50711302_48_dialog_content = "Tidak—",
  ui_story_5071_50711302_49_dialog_content = "Jangan khawatir, mereka sudah keluar.",
  ui_story_5071_50711302_50_dialog_content = "Orang-orang itu benar-benar keras kepala. Apakah mereka sembunyi di sini sejak awal?",
  ui_story_5071_50711302_51_dialog_content = "Sulit dipercaya mereka bahkan menemukan kamu sebelum kami.",
  ui_story_5071_50711302_52_dialog_content = "Keinginan Ms. Hanstie untuk memusnahkan segalanya sangat menakutkan. Dia benar-benar melawan kita.",
  ui_story_5071_50711302_53_dialog_content = "Biarkan dia melakukan halnya...",
  ui_story_5071_50711302_54_dialog_content = "Shadowlord?",
  ui_story_5071_50711302_55_dialog_content = "Aku merasa... sedikit lelah—",
  ui_story_5071_50711302_56_dialog_content = "Kamu terlihat seperti sedang kesakitan banyak. Apakah kamu terluka?",
  ui_story_5071_50711302_57_dialog_content = "*Batuk*",
  ui_story_5071_50711302_58_dialog_content = "Ikut bersama kami! Asap di sini semakin tebal!",
  ui_story_5071_50711302_59_dialog_content = "Ini bukan asap.",
  ui_story_5071_50711302_60_dialog_content = "Bukan asap? Lalu apa ini uap hitam?",
  ui_story_5071_50711302_61_dialog_content = "(Tunggu, kabut hitam ini... Apakah ini sama dengan <color=#FFB400>racun Arte</color> dari sebelumnya?)",
  ui_story_5071_50711302_62_dialog_content = "Heheh, jadi kamu akhirnya tahu ya?",
  ui_story_5071_50711302_63_dialog_content = "Aku membiarkanmu hidup agar suatu saat nanti aku bisa mendengar pengakuanmu—",
  ui_story_5071_50711302_64_dialog_content = "Jadi, lewati saja basa-basi.",
  ui_story_5071_50711302_65_dialog_content = "Ini hanya... cara Ms. Hanstie mengetuk pintu.",
  ui_story_5071_50711302_66_dialog_content = "Asap telah mengambang sejak kita mulai saling bertarung.",
  ui_story_5071_50711302_67_dialog_content = "Makin keras kamu berjuang, makin banyak yang kamu hirup.",
  ui_story_5071_50711302_68_dialog_content = "Meskipun sebagian besar sudah terbakar oleh api, tidak ada yang tahu berapa banyak yang sudah Anda hirup—",
  ui_story_5071_50711302_69_dialog_content = "Serahkan penawarnya!",
  ui_story_5071_50711302_70_dialog_content = "Saya pikir Black Wolves sudah punah? Bagaimana kalian masih bisa memproduksi racun ini?",
  ui_story_5071_50711302_71_dialog_content = "\"Racun\"? Hahaha—Kurasa kau salah paham, teman.",
  ui_story_5071_50711302_72_dialog_content = "Lagipula, Black Wolves hanyalah sekumpulan anak anjing yang tidak berharga.",
  ui_story_5071_50711302_73_dialog_content = "Apa hubunganmu dengan Black Wolves? Dan Arte dan Hanstie...",
  ui_story_5071_50711302_74_dialog_content = "Tidak masalah, berikan saja kami penawarnya—",
  ui_story_5071_50711302_75_dialog_content = "Jangan khawatir, PlayerName... Mereka juga menghirup kabut itu.",
  ui_story_5071_50711302_76_dialog_content = "Jika itu beracun, mereka akan mati lebih cepat mengingat betapa lemahnya mereka.",
  ui_story_5071_50711302_77_dialog_content = "Heh, sesuai dengan ekspektasi dari Shadowlord yang terkenal. Bahkan dalam kondisi ini, kamu masih tetap tenang.",
  ui_story_5071_50711302_78_dialog_content = "Kurasa kamu akan mencapai bagian monolog di mana kamu mengungkap plot cerita.",
  ui_story_5071_50711302_79_dialog_content = "Jangan biarkan kesempatanmu untuk didengar lewat begitu saja, badut yang canggung.",
  ui_story_5071_50711302_80_dialog_content = "Humph—Kami hanya mengikuti perintah Ms. Hanstie, tapi ini persis apa yang kita semua inginkan.",
  ui_story_5071_50711302_81_dialog_content = "Kamu bisa merasakannya sekarang, bukan? Sebuah rasa gelisah yang datang dari dalam diri—rasa kekerasan.",
  ui_story_5071_50711302_82_dialog_content = "Itu adalah efek dari kabut hitam yang telah kami modifikasi. Itu tidak membunuhmu lagi—hanya saja membuatmu penuh dengan kemarahan dan membuatmu menuruti dorongan paling liar.",
  ui_story_5071_50711302_83_dialog_content = "Dalam kondisi itu, tak seorang pun yang bisa menekan keinginan terdalam mereka.",
  ui_story_5071_50711302_84_dialog_content = "Jangan bilang kalian—",
  ui_story_5071_50711302_85_dialog_content = "Benar! Tujuan kita adalah menggunakannya untuk membebaskan binatang yang bersembunyi di bawah topeng Istvan!",
  ui_story_5071_50711302_86_dialog_content = "<size=50>Demon dari Parit—Kade!</size>",
  ui_story_5071_50711302_87_dialog_content = "Kami akan mengeluarkan monster yang terkubur dalam di hatimu!",
  ui_story_5071_50711302_88_dialog_content = "Semua orang yang datang menolongmu akan tahu persis siapa dirimu!",
  ui_story_5071_50711302_89_dialog_content = "Sekarang tunjukkan pada mereka! Tunjukkan pada orang-orang yang kamu klaim cintai tentang kegilaan mengerikan di dalam jiwamu!",
  ui_story_5071_50711302_90_dialog_content = "Kamu orang-orang... Kamu lah orang gila satu-satunya di sini!",
  ui_story_5071_50711302_91_dialog_content = "Serahkan penawarnya—tidak apa-apa, aku akan mengambilnya sendiri dari kamu...",
  ui_story_5071_50711302_92_dialog_content = "Dengan kekuatanku, aku tidak akan memiliki masalah untuk menemukan penawar di tubuhmu—",
  ui_story_5071_50711302_93_dialog_content = "Hah?",
  ui_story_5071_50711302_94_dialog_content = "(Kehadirannya... Benar-benar menghilang sepenuhnya!)",
  ui_story_5071_50711302_95_dialog_content = "Hei! Bangun! Kamu—",
  ui_story_5071_50711302_96_dialog_content = "...",
  ui_story_5071_50711302_97_dialog_content = "Anda bisa berhenti sekarang, PlayerName.",
  ui_story_5071_50711302_98_dialog_content = "Dia mengakhiri hidupnya.",
  ui_story_5071_50711302_99_dialog_content = "Mereka tidak membawa obat penawar karena mereka sudah siap untuk mati.",
  ui_story_5071_50711302_100_dialog_content = "Masih ada yang lain! Kita perlu menghentikan mereka dari...",
  ui_story_5071_50711302_101_dialog_content = "(Apa yang terjadi? Meskipun kita dikelilingi oleh kebakaran yang mengamuk... nyala api kehidupan mulai padam, satu per satu...)",
  ui_story_5071_50711302_102_dialog_content = "Berhenti! Jangan lakukan ini lagi, atau kalian semua—",
  ui_story_5071_50711302_103_dialog_content = "Waaah—",
  ui_story_5071_50711302_104_dialog_content = "PlayerName, aku sangat senang bahwa—",
  ui_story_5071_50711302_105_dialog_content = "Seorang anak muda seperti kamu akan meratapi musuh.",
  ui_story_5071_50711302_106_dialog_content = "Tapi saya juga minta maaf karena kebanyakan orang di sini mungkin...",
  ui_story_5071_50711302_107_dialog_content = "Bagaimana... Bagaimana mereka bisa melakukan ini pada diri mereka sendiri tanpa ragu-ragu? Dan dengan cara yang begitu mengerikan—",
  ui_story_5071_50711302_108_dialog_content = "Aku percaya kamu sudah tahu jawabannya.",
  ui_story_5071_50711302_109_dialog_content = "Ini...",
  ui_story_5071_50711302_110_dialog_content = "Lambang keluarga Gambi... dari masa lalu...",
  ui_story_5071_50711302_111_dialog_content = "Sebuah keluarga yang telah saya hancurkan—",
  ui_story_5071_50711302_112_dialog_content = "Mereka semua membawa sesuatu yang serupa.",
  ui_story_5071_50711302_113_dialog_content = "Ini Colo, itu Luka, dan yang itu milik Bonas...",
  ui_story_5071_50711302_114_dialog_content = "Aku melihat para pemimpin yang tenggelam di Lubang itu semua meninggalkan bayangan mereka di belakang—",
  ui_story_5071_50711302_115_dialog_content = "Ini adalah tempat di mana bayangan masa lalu akhirnya sampai.",
  ui_story_5071_50711302_116_dialog_content = "Urgh... Ada sensasi terbakar di dadaku...",
  ui_story_5071_50711302_117_dialog_content = "Sebuah dorongan yang mendorongku untuk membakar... untuk menghancurkan segalanya...",
  ui_story_5071_50711302_118_dialog_content = "Wajahmu...",
  ui_story_5071_50711302_119_dialog_content = "Saya bayangkan saya tidak terlihat menyenangkan. Jadi, apakah saya terlihat barbar?",
  ui_story_5071_50711302_120_dialog_content = "(Apakah ekspresi yang mengerikan... Bahkan urat-uratnya benar-benar terlihat. Dia sama sekali tidak mirip dengan Shadowlord dari sebelumnya...)",
  ui_story_5071_50711302_121_dialog_content = "Kita harus pergi, Shadowlord—",
  ui_story_5071_50711302_122_dialog_content = "Jika kita tidak bisa menemukan penawar di sini, saya yakin kita bisa menemukan sesuatu di Umbraton...",
  ui_story_5071_50711302_123_dialog_content = "Bagaimanapun, kita harus menjauh dari nyala api ini!",
  ui_story_5071_50711302_124_dialog_content = "Kamu benar, tapi... Urgh—",
  ui_story_5071_50711302_125_dialog_content = "Hanya bersandar padaku! Aku akan membawa kita keluar dari sini!",
  ui_story_5071_50711302_126_dialog_content = "Api di dalam diriku membakar lebih panas daripada kobaran api di sini.",
  ui_story_5071_50711302_127_dialog_content = "Aku... tidak pikir aku bisa bertahan lebih lama lagi.",
  ui_story_5071_50711302_128_dialog_content = "Ini sudah ditakdirkan. Masa laluku sedang mengejarku—",
  ui_story_5071_50711302_129_dialog_content = "Tinggalkan aku dan keluar dari sini. Aku tidak bisa membiarkanmu terluka...",
  ui_story_5071_50711302_130_dialog_content = "Berhenti mengatakan hal seperti itu!",
  ui_story_5071_50711302_131_dialog_content = "Benar! Kami masih membutuhkanmu untuk menyelamatkan Lady Sheol!",
  ui_story_5071_50711302_132_dialog_content = "Aku juga ingin menepati janjiku, tapi... Urgh—",
  ui_story_5071_50711302_133_dialog_content = "Mereka benar. Saya merasa ingin menghancurkan sesuatu...",
  ui_story_5071_50711302_134_dialog_content = "Cepat! Aku tidak bercanda tentang ini. Aku...",
  ui_story_5071_50711302_135_dialog_content = "Tidak mungkin, aku tidak akan meninggalkanmu! Aku yakin pasti ada cara lain—",
  ui_story_5071_50711302_136_dialog_content = "Aku bilang, keluar dari sini! Sekarang!",
  ui_story_5071_50711302_137_dialog_content = "Tinggalkan aku sendiri!",
  ui_story_5071_50711302_138_dialog_content = "Ini dia... Aku lebih mengenal diriku daripada kamu.",
  ui_story_5071_50711302_139_dialog_content = "Tidak...",
  ui_story_5071_50711302_140_dialog_content = "Pasti ada cara lain.",
  ui_story_5071_50711302_141_dialog_content = "(Harus ada! Meskipun—)",
  ui_story_5071_50711302_142_dialog_content = "Maaf. Aku tahu kamu mungkin akan menyalahkan aku untuk ini nanti, tapi aku tidak punya pilihan lain sekarang.",
  ui_story_5071_50711302_143_dialog_content = "PlayerName…",
  ui_story_5071_50711302_144_dialog_content = "Awasi kami, Vergil! Kami mengandalkanmu!",
  ui_story_5071_50711302_145_option_content = "Force Boost!",
  ui_story_5071_50711401_1_dialog_content = "Jadi ini adalah dunia batin Shadowlord? Ada begitu banyak emosi yang bertentangan di sini...",
  ui_story_5071_50711401_2_dialog_content = "Aku ingat di sini, ini adalah—",
  ui_story_5071_50711401_3_dialog_content = "Apakah itu suara Shadowlord?",
  ui_story_5071_50711401_4_dialog_content = "Ketika Krisis Darkover datang, saya mewakili ayah dan asosiasi serikat sementara untuk bernegosiasi mendapatkan bantuan dari Lumopolis. Lalu...",
  ui_story_5071_50711401_5_dialog_content = "Di mana kamu, Shadowlord?",
  ui_story_5071_50711401_6_dialog_content = "Saya tidak pernah membayangkan saya akan melihat hari itu lagi.",
  ui_story_5071_50711401_7_dialog_content = "Dia tidak bisa mendengarku... Jika aku tidak bisa menjangkaunya seperti ini, maka aku tidak punya pilihan selain mencari celah dalam emosinya.",
  ui_story_5071_50711401_8_dialog_content = "Tapi kemana dia pergi...",
  ui_story_5071_50711401_9_dialog_content = "Tempat ini... Apakah ini semacam arena?",
  ui_story_5071_50711401_10_dialog_content = "... Mengapa begitu banyak orang berkumpul di sini?",
  ui_story_5071_50711401_11_dialog_content = "Aku juga sangat terkejut... Bisakah kamu ingat kapan terakhir kali begitu banyak bos berkumpul bersama?",
  ui_story_5071_50711401_12_dialog_content = "Apakah... Apakah semua orang ini anggota geng?",
  ui_story_5071_50711401_13_dialog_content = "Karena semua orang bersedia datang dan berbicara secara individu, saya ingin mendengar apa yang semua orang katakan.",
  ui_story_5071_50711401_14_dialog_content = "Saya dengar bahwa Istvan tua dan beberapa guild telah bersekongkol untuk mengkhianati Umbraton, dan <color=#FFB400>anak angkatnya akan lewat dengan tongkat itu sebagai bukti</color>.",
  ui_story_5071_50711401_15_dialog_content = "Saya ingin mendapatkan tongkat itu dan memerintahkan asosiasi guild untuk mendistribusikan persediaan dan mempersenjatai semua orang untuk melawan Eclipsite.",
  ui_story_5071_50711401_16_dialog_content = "Jadi mereka lah yang memanggil semua bangsawan dari Lumopolis itu? Orang-orang itu sepenuhnya bersenjata dan bertugas di luar dalam situasi darurat seperti ini. Saya pikir mereka ingin menjaga kami di sini.",
  ui_story_5071_50711401_17_dialog_content = "Orang-orang dari Lumopolis selalu mencari kesempatan untuk menduduki Umbraton. Mari kita berikan saja apa yang mereka inginkan dan tinggalkan tempat ini.",
  ui_story_5071_50711401_18_dialog_content = "Tapi ini adalah rumah kita!",
  ui_story_5071_50711401_19_dialog_content = "Jangan bilang begitu. Saya tidak menganggap selokan yang bau ini sebagai rumah saya.",
  ui_story_5071_50711401_20_dialog_content = "Apakah kamu ingin bertarung denganku di Pit?",
  ui_story_5071_50711401_21_dialog_content = "Aku tidak setuju dengan orang-orang dari Lumopolis yang seenaknya masuk ke wilayah kita seperti ini! Bukankah mereka sudah meninggalkan Umbraton dan pulang karena takut dengan tentara Eclipsite? Kenapa mereka kembali?",
  ui_story_5071_50711401_22_dialog_content = "Kami sudah pernah mengusir mereka sekali, dan sekarang mereka ingin menempatkan pasukan mereka di sini? Apakah itu adil?",
  ui_story_5071_50711401_23_dialog_content = "Ayo berhenti berdebat! Menurutku, kita harus bekerja sama untuk menghasilkan uang dari ini! Orang-orang miskin di kota itu tidak ada hubungannya dengan kita, jadi mari kita peras sebanyak mungkin uang dari mereka dan gunakan uang itu untuk membujuk orang-orang dari Lumopolis!",
  ui_story_5071_50711401_24_dialog_content = "Kamu benar. Karena kita semua di sini, kita harus merampok guild-guild itu—",
  ui_story_5071_50711401_25_dialog_content = "Penyokongku ada di antara mereka!",
  ui_story_5071_50711401_26_dialog_content = "Ini adalah Pit. Saya usulkan kita gunakan aturan tertua untuk menentukan siapa yang mendapatkan tongkat.",
  ui_story_5071_50711401_27_dialog_content = "Bisakah kita semua bekerja sama? Kita masih belum tahu berapa banyak orang yang akan mengawal staf.",
  ui_story_5071_50711401_28_dialog_content = "Siapa pun yang bertahan hingga akhir dapat memimpin pasukan kita untuk mengambilnya. Sesederhana itu.",
  ui_story_5071_50711401_29_dialog_content = "Dalam pandanganmu, apakah staf itu lebih penting daripada Umbraton?",
  ui_story_5071_50711401_30_dialog_content = "Tentu saja! Tongkat Gembala mewakili klan Istvan tua dan bahkan menjadi simbol dari asosiasi guild...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>Cukup sudah!</size>",
  ui_story_5071_50711401_32_dialog_content = "Yang paling penting sekarang adalah keberadaan si bocah Kade dan stafnya. Kenapa dia lama sekali?",
  ui_story_5071_50711401_33_dialog_content = "Apakah orang-orang ini yang bertanggung jawab atas Umbraton saat itu? Sungguh tempat yang mengerikan...",
  ui_story_5071_50711401_34_dialog_content = "Saya perlu menggunakan kekuatan saya untuk menemukan Shadowlord, dan itu harus cepat...",
  ui_story_5071_50711401_35_dialog_content = "Saya dengar bahwa anak laki-laki Istvan yang tua, Valon, sedang berjalan cukup baik dan sudah mengelola beberapa guild.",
  ui_story_5071_50711401_36_dialog_content = "Dia bahkan telah memberi kita banyak manfaat. Saya penasaran apa yang dia pikirkan tentang serangan Eclipsite ini.",
  ui_story_5071_50711401_37_dialog_content = "Di sana! Versi muda dari Shadowlord sedang bersembunyi di sudut itu—",
  ui_story_5071_50711401_38_dialog_content = "Hah? Siapa itu di depan dia?",
  ui_story_5071_50711401_39_dialog_content = "Kau dengar itu, Kade?",
  ui_story_5071_50711401_40_dialog_content = "Ini adalah bos-bos Umbraton yang ingin kamu selamatkan.",
  ui_story_5071_50711401_41_dialog_content = "Aku tidak punya waktu untuk membicarakan itu, Valon. Kita harus pergi, waktu tidak menunggu siapapun!",
  ui_story_5071_50711401_X41_dialog_content = "Valon? Mengapa hanya ada ingatan samar tentang Valon di memori Shadowlord?",
  ui_story_5071_50711401_42_dialog_content = "City Lord muda itu memberitahuku bahwa dia akan membantu kita melewati krisis!",
  ui_story_5071_50711401_43_dialog_content = "Bala bantuan berada di luar gerbang tetapi belum melakukan gerakan apa pun, jadi mereka memberi kita lebih banyak penghargaan dari biasanya.",
  ui_story_5071_50711401_44_dialog_content = "Aku hanya perlu pergi menandatangani PACT, dan mereka akan berjuang bersama Umbraton melawan tentara Eclipsite!",
  ui_story_5071_50711401_45_dialog_content = "Jika kamu menunjukkan dirimu sekarang, mereka hanya akan menyerangmu. Tinggal dan bicara denganku sebentar, dan aku akan membantumu merencanakan sesuatu.",
  ui_story_5071_50711401_46_dialog_content = "Jangan khawatir, kita aman di sini. Tidak ada yang akan mendengar pembicaraan kita.",
  ui_story_5071_50711401_47_dialog_content = "Apa syarat dari perjanjian ini, Kade? Apa yang kamu siap berikan kepada Lumopolis sebagai imbalan atas bantuan mereka?",
  ui_story_5071_50711401_48_dialog_content = "Orang-orang Umbraton? Perdagangan bebas? Atau malah lebih banyak pajak? Mereka sudah meninggalkan Umbraton dan hanya akan semakin buruk jika mereka kembali!",
  ui_story_5071_50711401_49_dialog_content = "Mengapa kau mengkhianati Umbraton hanya untuk merendahkan diri di Lumopolis? Apakah kau benar-benar menyerah pada impian kita?",
  ui_story_5071_50711401_50_dialog_content = "Ini telah disetujui oleh ayah kami serta asosiasi guild. Tongkat ini di tangan saya dan surat yang ditandatangani adalah buktinya.",
  ui_story_5071_50711401_51_dialog_content = "Ini mewakili persetujuan mereka secara bulat.",
  ui_story_5071_50711401_52_dialog_content = "Orang-orang di dasar masyarakat Umbraton, mereka yang telah ditindas oleh Lumopolis dan guild-guild besar—apakah kamu pernah bertanya bagaimana perasaan mereka tentang hal ini?",
  ui_story_5071_50711401_53_dialog_content = "Intelijen kami mengatakan bahwa gerombolan Eclipsite akan ada di sini dalam sehari, tetapi pasukan independen Umbraton masing-masing memiliki agenda mereka sendiri.",
  ui_story_5071_50711401_54_dialog_content = "Meskipun segalanya, ayah dan asosiasi adalah yang pertama kali menghubungi Lumopolis untuk perlindungan. Sementara itu, keluarga Gambi dan sekutu mereka mulai menaikkan harga tiket untuk transportasi keluar dari kota...",
  ui_story_5071_50711401_55_dialog_content = "Orang-orang miskin di kota ini tidak memiliki cara untuk membela diri atau melarikan diri. Yang bisa mereka lakukan hanyalah duduk dan menunggu datangnya kematian.",
  ui_story_5071_50711401_56_dialog_content = "Kita akan membela ini bersama-sama!",
  ui_story_5071_50711401_57_dialog_content = "Itu tidak lebih dari pemikiran yang penuh harapan dari Anda. Kebanyakan orang ingin meninggalkan Umbraton, tetapi saya mendapat kabar bahwa sejumlah geng telah mulai merampok mereka saat mereka mencoba melarikan diri.",
  ui_story_5071_50711401_58_dialog_content = "Siapa pun yang memiliki sedikit kekuatan terus mengabaikan yang lemah dan yang menderita. Aku tidak tahu mengapa Umbraton harus seperti ini, tapi inilah kenyataan kampung halaman kita...",
  ui_story_5071_50711401_59_dialog_content = "Untungnya, para bandit ini adalah orang-orang Umbraton sejati. Semua yang dibutuhkan hanyalah sedikit provokasi untuk membuat darah mereka mendidih.",
  ui_story_5071_50711401_60_dialog_content = "Itulah sebabnya saya telah mendorong mereka dari bayangan, hanya agar mereka bisa menemukan tempat ini. Dengan beberapa kata pilihan dan janji hadiah, mereka seharusnya bisa cukup kooperatif.",
  ui_story_5071_50711401_61_dialog_content = "Apa sebenarnya yang kamu inginkan?",
  ui_story_5071_50711401_62_dialog_content = "Aku sudah bilang sebelumnya, Kade. Aku telah bekerja keras untuk meningkatkan kekuatanku.",
  ui_story_5071_50711401_63_dialog_content = "Saya akan menggunakan invasi Eclipsite untuk membebaskan Umbraton dari malapetakannya, sekali dan untuk selamanya.",
  ui_story_5071_50711401_64_dialog_content = "Yang perlu kita lakukan hanyalah mengorbankan orang-orang ini, dan kita akan dapat membawa yang tidak bersalah keluar dari kota dengan aman.",
  ui_story_5071_50711401_65_dialog_content = "Kamu seharusnya berada di sisiku, membersihkan nanah busuk mereka dari kota ini alih-alih meminta bantuan dari kotoran Lumopolis. Inilah yang sebenarnya dibutuhkan Umbraton saat ini.",
  ui_story_5071_50711401_66_dialog_content = "Mengapa, Valon? Kamu telah berubah...",
  ui_story_5071_50711401_67_dialog_content = "Mengapa kamu tidak bisa menyatukan mereka melawan Eclipsites, alih-alih memecah belah mereka dengan pertikaian internal?",
  ui_story_5071_50711401_68_dialog_content = "Apa bedanya kamu ini dengan para bangsawan haus darah yang ada di sini?",
  ui_story_5071_50711401_69_dialog_content = "Pria-pria ini adalah sampah dari Umbraton, pemimpin dari penjahat-penjahat terkotor yang telah merusak kota kita. Membiarkan mereka hidup hanya akan membawa malapetaka bagi orang lain.",
  ui_story_5071_50711401_70_dialog_content = "Ini adalah satu-satunya kesempatan kita, Kade! Bantu aku untuk mengusir mereka agar kita bisa membawa orang-orang yang tidak bersalah ke tempat yang aman...",
  ui_story_5071_50711401_71_dialog_content = "Kematian mereka adalah hal yang diperlukan untuk bertahannya orang-orang paling rentan di Umbraton!",
  ui_story_5071_50711401_72_dialog_content = "... Jadi apa jika mereka melarikan diri?",
  ui_story_5071_50711401_73_dialog_content = "Lumopolis akan memerintah Umbraton, dan orang-orang di sini di masa depan akan menghadapi masalah yang sama seperti yang kita alami.",
  ui_story_5071_50711401_74_dialog_content = "Dan akan ada putra setan lainnya seperti aku, terlahir di bayang-bayang dan dijauhi oleh semua orang.",
  ui_story_5071_50711401_75_dialog_content = "Kemudian siklus itu akan dimulai lagi.",
  ui_story_5071_50711401_76_dialog_content = "Tidak mudah mencapai kesepakatan dengan Lumopolis, dan saya harus memanfaatkan kesempatan ini untuk dialog yang setara...",
  ui_story_5071_50711401_77_dialog_content = "Sepertinya sekarang kamu sudah tidak bisa berubah pikiran...",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>Dengarkan semua orang, Kade ada di sini!</color></size>",
  ui_story_5071_50711401_79_dialog_content = "*keheningan tiba-tiba*",
  ui_story_5071_50711401_80_dialog_content = "Valon! Bagaimana bisa kau!",
  ui_story_5071_50711401_81_dialog_content = "Apakah kamu mendengar suara dari semua langkah kaki itu? Sekarang kamu tidak punya pilihan selain melawan mereka semua dan membantu saya membersihkan kota ini dari kotoran mereka!",
  ui_story_5071_50711401_82_dialog_content = "Tapi jangan khawatir. Pasukan saya dan saya akan bertarung di sisimu, seperti sekutu.",
  ui_story_5071_50711401_83_dialog_content = "Janganlah kita bertindak impulsif. Kita masih bisa bekerja sama. Kita akan membuat anak itu menyerahkan tongkatnya, lalu kita akan mentransfer beberapa persediaan untuk pertahanan!",
  ui_story_5071_50711401_84_dialog_content = "Urgh! S-Siapa—",
  ui_story_5071_50711401_85_dialog_content = "Seseorang telah diserang! Drat, kalian memiliki motif tersembunyi dan tidak ingin bekerja sama, aku tahu itu!",
  ui_story_5071_50711401_86_dialog_content = "Ayo kita bunuh dulu anak iblis itu dan berjuang untuk staf nanti!",
  ui_story_5071_50711401_87_dialog_content = "Minggir, saya tidak punya waktu untukmu.",
  ui_story_5071_50711401_88_dialog_content = "Lepaskan tanda ku!",
  ui_story_5071_50711401_89_dialog_content = "Saya bilang, minggir—",
  ui_story_5071_50711401_90_dialog_content = "Kamu akan mati jika tidak melawan, Kade. Jika itu terjadi, semua mimpi kita akan mati bersamamu.",
  ui_story_5071_50711401_91_dialog_content = "Sial! Minggir!",
  ui_story_5071_50711401_92_dialog_content = "Jangan coba-coba kalian yang berpandangan sempit ini untuk menghentikanku!",
  ui_story_5071_50711401_93_dialog_content = "Aku menikamnya. Cepat! Tolong aku—",
  ui_story_5071_50711401_94_dialog_content = "Argh!",
  ui_story_5071_50711401_95_dialog_content = "Ini yang kalian inginkan, hama-hama? Nah, kalian dapatkan!",
  ui_story_5071_50711401_96_dialog_content = "Tidak, berhenti! Pertarungan ini sia-sia—",
  ui_story_5071_50711401_97_dialog_content = "Berubahlah menjadi abu, semua kalian!",
  ui_story_5071_50711401_98_dialog_content = "Tidak ada yang bisa mendengar saya...",
  ui_story_5071_50711401_99_dialog_content = "Ini pembantaian... Aku tidak tahu bahwa Shadowlord memiliki sisi brutal seperti ini... Apakah dia benar-benar kehilangan kendali?",
  ui_story_5071_50711401_100_dialog_content = "Apakah begitulah dia akhirnya membunuh sahabatnya?",
  ui_story_5071_50711401_101_dialog_content = "Tunggu sebentar, apa yang sedang aku pikirkan? Celah dalam emosi Shadowlord seharusnya ada di sini!",
  ui_story_5071_50711401_102_dialog_content = "Tolong dengarkan aku! Kamu harus sadar—",
  ui_story_5071_50711402_1_dialog_content = "Semua bos...",
  ui_story_5071_50711402_2_dialog_content = "Lihat! Saya pikir tentara Lumopolis sedang bergerak. Sepertinya mereka sedang menuju ke arah ini... benar?",
  ui_story_5071_50711402_3_dialog_content = "Sekarang hanya tinggal kamu dan aku saja...",
  ui_story_5071_50711402_4_dialog_content = "Selamat karena telah bertahan di Pit untuk kedua kalinya, Kade.",
  ui_story_5071_50711402_5_dialog_content = "*meraung*",
  ui_story_5071_50711402_6_dialog_content = "Minggir, Valon! Saya harus pergi menguatkan pakta dengan bukti...",
  ui_story_5071_50711402_7_dialog_content = "Bahkan setelah semua ini, kamu masih percaya pada kebohongan Lumopolis?",
  ui_story_5071_50711402_8_dialog_content = "Apa kamu ingat <color=#FFB400>mimpi</color> yang pernah aku ceritakan padamu, Kade?",
  ui_story_5071_50711402_9_dialog_content = "Dasar sudah diletakkan. Ikutlah denganku, dan dengan kekuatan Tongkat Gembala, kita bisa menyatukan asosiasi guild dan orang-orang lemah di Umbraton di bawah kita.",
  ui_story_5071_50711402_10_dialog_content = "Kita akan membuat rumah baru untuk diri kita sendiri, tempat bernaung yang aman untuk jiwa-jiwa tersesat seperti kita.",
  ui_story_5071_50711402_11_dialog_content = "Sebuah tempat di mana kita bisa hidup dalam kebahagiaan dan kesetaraan, di mana kita bisa bepergian ke mana saja dan berbisnis dengan siapa saja di <color=#FFB400>tanah</color> ini—",
  ui_story_5071_50711402_12_dialog_content = "(Sebuah guild yang berkeliling... Apakah ini bagaimana <color=#FFB400>Continental Guild</color> dimulai? Dan gagasan perdagangan bebas terdengar seperti <color=#FFB400>Cloudrover Guild</color>!)",
  ui_story_5071_50711402_13_dialog_content = "(Mimpi Mr. Valon... Tidak berbeda dengan milik Nona Sheol! Itulah sebabnya Ms. Hanstie terus mengatakan bahwa dia mencuri mimpi orang lain!)",
  ui_story_5071_50711402_14_dialog_content = "Tapi bagaimana dengan ayah? Bagaimana dengan pekerja guild yang tidak mau pergi?",
  ui_story_5071_50711402_15_dialog_content = "Bagaimana dengan anak-anak yang ditipu untuk bergabung dengan geng? Jika mereka juga tidak ingin pergi—",
  ui_story_5071_50711402_16_dialog_content = "... Ayah dan orang-orang itu tidak mau pergi. Mungkin lebih karena tidak ingin menyerah pada prospek mereka, bukan semacam cinta.",
  ui_story_5071_50711402_17_dialog_content = "Begitu banyak orang yang telah dirampas kehidupan baiknya di sini, dan mereka tidak menginginkan apa-apa selain pergi. Apakah Anda benar-benar akan memaksa mereka untuk tinggal di sini dan mati untuk kota busuk ini?",
  ui_story_5071_50711402_18_dialog_content = "Anda menangis untuk anak-anak di jalanan, tetapi mereka yang bekerja untuk gilda mungkin adalah orang tua atau saudara mereka!",
  ui_story_5071_50711402_19_dialog_content = "Hubungan antara kita dan kampung halaman kita lebih erat daripada yang kamu pikirkan, dan tidak ada yang bisa memutuskan ikatan tersebut.",
  ui_story_5071_50711402_20_dialog_content = "Orang mungkin mencintai atau membenci rumah mereka, tetapi seharusnya tidak pernah meninggalkannya—",
  ui_story_5071_50711402_21_dialog_content = "Aku tinggal bersama ayah dan mempertahankan rumah kita dengan caranya sendiri.",
  ui_story_5071_50711402_22_dialog_content = "Horda Eclipsite akan segera tiba, dan militer Lumopolis juga sedang mempersiapkan diri untuk pertempuran. Tak lama lagi, tempat ini akan terjerumus ke dalam kekacauan total.",
  ui_story_5071_50711402_23_dialog_content = "Rakyat Lumopolis tidak akan peduli jika kamu tetap di sini sampai mati!",
  ui_story_5071_50711402_24_dialog_content = "Setidaknya kita mati demi negeri kita.",
  ui_story_5071_50711402_25_dialog_content = "Ayah dan aku tidak pernah sependapat...",
  ui_story_5071_50711402_26_dialog_content = "Aku tidak pernah mendapatkan persetujuannya, tidak seperti kamu. Pada akhirnya, tampaknya kamu memang anak yang lebih baik dari Istvan.",
  ui_story_5071_50711402_27_dialog_content = "Tapi kamu berbeda darinya. Sejak kamu mulai mendorong saya untuk mengejar impian saya, saya tahu kamu adalah satu-satunya orang yang benar-benar bisa mengerti saya.",
  ui_story_5071_50711402_28_dialog_content = "Jadi tolong, demi mimpi kita, ikutlah denganku—",
  ui_story_5071_50711402_29_dialog_content = "Impian kita adalah mengubah tempat ini! Jika kita tidak bisa bertahan, impian itu menjadi kebohongan.",
  ui_story_5071_50711402_30_dialog_content = "Sulit untuk akhirnya meyakinkan mereka untuk bersatu. Aku tidak bisa menyerah sekarang...",
  ui_story_5071_50711402_31_dialog_content = "Ini semua bohong, Kade! Orang-orang ini hanya tertarik untuk menguntungkan diri mereka sendiri! Mereka akan segera mulai berkelahi satu sama lain!",
  ui_story_5071_50711402_32_dialog_content = "Saya mengerti geng-geng telah mengecewakan orang banyak. Tapi mereka tidak selalu berada di luar bantuan.",
  ui_story_5071_50711402_33_dialog_content = "Banyak dari mereka tidak memiliki pilihan. Tapi jika bahkan saya bisa mendapatkan aspirasi yang benar, orang lain juga bisa!",
  ui_story_5071_50711402_34_dialog_content = "Selama kita bertahan, kita akan meninggalkan biji itu.",
  ui_story_5071_50711402_35_dialog_content = "Meskipun bukan kita, suatu hari nanti, seseorang akan mewujudkan impian kita.",
  ui_story_5071_50711402_36_dialog_content = "Kade... Selama ini kau terus berjuang di masa kini. Kau bertindak sembrono dan hanya fokus pada serangan, sama seperti saat kita bermain catur.",
  ui_story_5071_50711402_37_dialog_content = "Menghukum kejahatan seperti ini hanya akan menghancurkan segalanya di depan kita. Sejak kapan kamu... bisa melihat lebih dari itu?",
  ui_story_5071_50711402_38_dialog_content = "Umbraton akan mengandalkan dirinya sendiri di masa depan, tetapi itu tidak berarti kita tidak bisa membuat sekutu. Kita tidak bisa berjuang sendiri tetapi meminta bantuan dari Lumopolis.",
  ui_story_5071_50711402_39_dialog_content = "Kaulah yang membuatku mengerti arti persahabatan, Valon. Kenapa kau berubah?",
  ui_story_5071_50711402_40_dialog_content = "Lumopolis adalah sumber kegelapan Umbraton... Sementara mereka dengan sombongnya berjemur dalam cahaya, mereka meninggalkan kita yang lain terperangkap dalam bayangan.",
  ui_story_5071_50711402_41_dialog_content = "Aku iri padamu karena bisa melepaskan kebencianmu dan melanjutkan hidup begitu mudahnya.",
  ui_story_5071_50711402_42_dialog_content = "Tapi, aku takkan pernah memaafkan orang-orang seperti mereka. Berkompromi dengan sampah seperti mereka sama saja dengan mengabaikan ketidakadilan mereka, dan aku menolak untuk melakukan itu.",
  ui_story_5071_50711402_43_dialog_content = "Melindungi orang-orang yang kusayangi... sudah membutuhkan semua kekuatanku.",
  ui_story_5071_50711402_44_dialog_content = "Valon...",
  ui_story_5071_50711402_45_dialog_content = "Tak pernah sekalipun kau mengalahkanku dalam catur, Kade. Apa yang membuatmu berpikir kau bisa mengalahkan seluruh Lumopolis?",
  ui_story_5071_50711402_46_dialog_content = "Ketika berbicara tentang penipuan, tidak ada yang lebih baik daripada mereka—",
  ui_story_5071_50711402_47_dialog_content = "Tolong, Kade, aku memohon padamu. Berikan aku Shepherd's Staff, dan ikutlah denganku...",
  ui_story_5071_50711402_48_dialog_content = "Aku... menolak.",
  ui_story_5071_50711402_49_dialog_content = "Apakah ini harus berakhir seperti ini antara kita? Benarkah hanya bisa ada satu pemenang di Pit?",
  ui_story_5071_50711402_50_dialog_content = "Saya tidak pernah berpikir bahwa pedang kita akan bersilangan suatu hari... Tapi saya...",
  ui_story_5071_50711402_51_dialog_content = "Apa yang terjadi di sini? Di mana perwakilan kita, Pak Kade?",
  ui_story_5071_50711402_52_dialog_content = "!",
  ui_story_5071_50711402_53_dialog_content = "Kamu tidak boleh masuk ke dalam!",
  ui_story_5071_50711402_54_dialog_content = "Aku tidak punya waktu untuk berurusan dengan kalian. Di mana Mr. Kade?",
  ui_story_5071_50711402_55_dialog_content = "Busuk Lumopolis! Beraninya kalian membawa tentara kalian ke rumah kami!",
  ui_story_5071_50711402_56_dialog_content = "Usir mereka dari sini!",
  ui_story_5071_50711402_57_dialog_content = "Jangan berlagak sombong, kalian orang rendahan yang tinggal di parit-parit Umbraton.",
  ui_story_5071_50711402_58_dialog_content = "Kalahkan mereka dan cari tahu di mana Kade berada. Jangan biarkan dia dibunuh oleh sampah-sampah ini.",
  ui_story_5071_50711402_59_dialog_content = "Kutuklah penghuni Lumopolis ini! Urgh!",
  ui_story_5071_50711402_60_dialog_content = "Apakah Anda di sana, Pak Kade? Karena sudah cukup lama sejak waktu pertemuan yang kita sepakati, kita...",
  ui_story_5071_50711402_61_dialog_content = "Apakah ini benar-benar rencanamu, Kade?",
  ui_story_5071_50711402_62_dialog_content = "Apakah kamu benar-benar rela merendahkan diri sejauh ini? Sungguh memalukan!",
  ui_story_5071_50711402_63_dialog_content = "Mundur. Kamu tidak bisa masuk ke Umbraton seperti itu.",
  ui_story_5071_50711402_64_dialog_content = "Pak Kade, saya rasa Anda tidak cukup memahami apa itu komitmen. Sebuah perjanjian lebih penting daripada apapun.",
  ui_story_5071_50711402_65_dialog_content = "Mundur!",
  ui_story_5071_50711402_66_dialog_content = "Kamu mengkhianati seluruh Umbraton dengan membiarkan anjing-anjing ini masuk ke rumah kita!",
  ui_story_5071_50711402_67_dialog_content = "Penduduk Umbraton! Jaga bahasamu!",
  ui_story_5071_50711402_68_dialog_content = "Aku tidak akan membiarkanmu mencemarkan rumahku!",
  ui_story_5071_50711402_69_dialog_content = "Jangan menyerang. Letakkan senjatamu, Valon!",
  ui_story_5071_50711402_70_dialog_content = "Mundur! Mundur! Sial, Luminatics orang itu—",
  ui_story_5071_50711402_71_dialog_content = "Komandan telah terluka! Balas! Serang mereka balik!",
  ui_story_5071_50711402_72_dialog_content = "Kalian, orang-orang sombong, tidak akan bisa kabur begitu saja! Aku—",
  ui_story_5071_50711402_73_dialog_content = "(Oh, tidak, para prajurit Lumopolis menembak tanpa pandang bulu... Harus menghentikan mereka!)",
  ui_story_5071_50711402_74_dialog_content = "(Sial, saya benar-benar tidak bisa menghentikan semua ini...)",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>Bang—</color>",
  ui_story_5071_50711402_76_dialog_content = "K-Kau sampah... Kade—",
  ui_story_5071_50711402_77_dialog_content = "<size=40>Valon!</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>Ahhhh!</size>",
  ui_story_5071_50711402_79_dialog_content = "Keluar! Kalian semua, keluar!",
  ui_story_5071_50711402_80_dialog_content = "Ayo mundur sekarang! Orang ini sudah gila dan tidak peduli lagi tentang perjanjian. Mundur!",
  ui_story_5071_50711402_81_dialog_content = "Mundur! Kembali, sekarang!",
  ui_story_5071_50711402_82_dialog_content = "Valon...",
  ui_story_5071_50711402_83_dialog_content = "Kade... Sepertinya hal-hal selalu berubah dari buruk menjadi lebih buruk di Umbraton. Bagaimana kita seharusnya menyelamatkan tempat ini sekarang?",
  ui_story_5071_50711402_84_dialog_content = "Bayangan Lumopolis... akan memadamkan api... Dan Umbraton tidak akan pernah murni...",
  ui_story_5071_50711402_85_dialog_content = "Sekarang siapa yang akan menjadi... penyelamat bagi yang tertindas...",
  ui_story_5071_50711402_86_dialog_content = "Ini mungkin! Ini mungkin, Valon. Beri aku lebih banyak waktu. Kita hanya perlu melewati krisis ini...",
  ui_story_5071_50711402_87_dialog_content = "Impianmu masih bisa menjadi kenyataan, dan tempat ini akan berkembang!",
  ui_story_5071_50711402_88_dialog_content = "Heheh... Kamu benar-benar... terlalu naif...",
  ui_story_5071_50711402_89_dialog_content = "Jangan beri tahu ayah apa yang telah saya lakukan... bukan karena saya malu... tapi karena saya tidak ingin dia menderita...",
  ui_story_5071_50711402_90_dialog_content = "... Aku berjanji.",
  ui_story_5071_50711402_91_dialog_content = "Mendekatlah, kakak... Aku masih ada yang ingin kuceritakan...",
  ui_story_5071_50711402_92_dialog_content = "*batuk* ... Kami adalah orang-orang Umbraton, sepenuhnya. Kekerasan tidak akan pernah hilang dari hati kami...",
  ui_story_5071_50711402_93_dialog_content = "Karena aku tidak bisa menghentikanmu melakukan semua ini, setidaknya tepati janjimu padaku...",
  ui_story_5071_50711402_94_dialog_content = "Mulai sekarang, kamu harus melakukan apa pun yang diperlukan untuk menjaga Umbraton tetap hidup...",
  ui_story_5071_50711402_95_dialog_content = "Aku... berjanji.",
  ui_story_5071_50711402_96_dialog_content = "Saudara laki-laki saya.",
  ui_story_5071_50711402_97_dialog_content = "...",
  ui_story_5071_50711402_98_dialog_content = "Tidak... Tidak... Kamu sama sekali tidak melakukannya, bukan, Shadowlord?",
  ui_story_5071_50711402_99_dialog_content = "... Orang-orang itu tertarik oleh keributan dan hanya memasuki Umbraton untuk memastikan PACT dilaksanakan.",
  ui_story_5071_50711402_100_dialog_content = "Mereka terlalu acuh tak acuh untuk menunjukkan rasa hormat kepada kami, tetapi kami sedikit terlalu sensitif. Kami tidak belajar untuk bekerja sama sampai kami membayar harganya.",
  ui_story_5071_50711402_101_dialog_content = "Tapi, apakah itu menghapus dosa-dosaku?",
  ui_story_5071_50711402_102_dialog_content = "Seorang bijak pernah berkata, \"Kekuatan kata-kata dapat mengikat jiwa.\"",
  ui_story_5071_50711402_103_dialog_content = "Jadi, aku benar-benar tidak bisa melepaskan diri dari kata-kata Valon.",
  ui_story_5071_50711501_1_dialog_content = "Untuk menjaga aliansi kita dengan Lumopolis, aku tidak pernah menjelaskan tentang kematian Valon kepada siapa pun. Bagaimanapun, semua ini adalah salahku.",
  ui_story_5071_50711501_2_dialog_content = "Tapi itu jelas bukan kebenarannya...",
  ui_story_5071_50711501_3_dialog_content = "Ketika aku menjadi Anak Kecil dari Istvan, aku bersumpah untuk tidak pernah membunuh keluargaku sendiri atau merugikan kepentingan keluarga kita...",
  ui_story_5071_50711501_4_dialog_content = "Tapi pada akhirnya, aku melanggar sumpah itu. Tidak peduli bagaimana orang melihatnya, aku tidak memiliki hak untuk menghadapi Ayah kita.",
  ui_story_5071_50711501_5_dialog_content = "Namun tepat sebelum dia meninggal, Ayah kita memilih untuk meninggalkan segalanya di tangan saya. Dan begitu, \"Istvan\" menjadi nama baru saya.",
  ui_story_5071_50711501_6_dialog_content = "Shadowlord...",
  ui_story_5071_50711501_7_dialog_content = "Saya memutuskan untuk menjadi Bayangan...",
  ui_story_5071_50711501_8_dialog_content = "Aku akan hidup dalam kegelapan sebagai bayangan dan melakukan apa saja untuk memastikan Umbraton bertahan.",
  ui_story_5071_50711501_9_dialog_content = "Aku telah menyembunyikan masa lalu dari diriku sendiri selama ini sampai-sampai aku hampir tidak bisa mengingatnya... Tapi dosa-dosa masa laluku masih menghantuiku sebagai mimpi buruk.",
  ui_story_5071_50711501_10_dialog_content = "Harga yang adil sebagai ganti keselamatanku.",
  ui_story_5071_50711501_11_dialog_content = "Tidak... Ini sama sekali tidak adil.",
  ui_story_5071_50711501_12_dialog_content = "Demi masa depan Umbraton, aku bersedia mengorbankan segalanya. Inilah cara aku selalu melakukan hal-hal.",
  ui_story_5071_50711501_13_dialog_content = "Seperti orang sombong yang aku ini, aku akan mengorbankan segalanya dan bertanggung jawab atas semuanya. Valon... Dia adalah \"harga\" pertama yang harus aku bayar.",
  ui_story_5071_50711501_14_dialog_content = "Kamu tidak melakukan kesalahan apapun... Kamu tahu itu, kan? Tapi kamu masih memilih untuk menghukum diri sendiri seperti ini.",
  ui_story_5071_50711501_15_dialog_content = "... Saya membuat keputusan ini demi Umbraton, dan konsekuensinya adalah tanggung jawab saya. Terlepas dari benar atau salah, saya hanya ingin melindungi kota ini.",
  ui_story_5071_50711501_16_dialog_content = "Saya selalu percaya bahwa suatu hari nanti akan ada seseorang yang berdiri di puncak tempat kegelapan ini, orang yang pada akhirnya akan menggantikan saya.",
  ui_story_5071_50711501_17_dialog_content = "Saya senang mengatakan bahwa saya dapat melihat harapan itu segera menjadi kenyataan.",
  ui_story_5071_50711501_18_dialog_content = "Jika kamu benar-benar merasa seperti itu, lalu kenapa kamu masih terperangkap dalam kenangan-kenangan ini...?",
  ui_story_5071_50711501_19_dialog_content = "Memang, kenapa ya... Ketika aku terbangun di tengah malam, kadang-kadang aku juga bertanya-tanya hal yang sama pada diriku sendiri.",
  ui_story_5071_50711501_20_option_content = "Ini karena rasa bersalahmu.",
  ui_story_5071_50711501_21_dialog_content = "Anda mengatakan bahwa saya masih menyalahkan diri sendiri?",
  ui_story_5071_50711501_22_option_content = "Ini karena penyesalanmu.",
  ui_story_5071_50711501_23_dialog_content = "Menyesal... Kamu pikir itu yang aku rasakan?",
  ui_story_5071_50711501_24_dialog_content = "Saya pikir, di suatu tempat dalam hatimu yang paling dalam, kamu selalu merasa bersalah tentang hal-hal ini.",
  ui_story_5071_50711501_X24_dialog_content = "Itulah mengapa kamu tidak bisa mengingat seperti apa wajah Valon.",
  ui_story_5071_50711501_X25_dialog_content = "...",
  ui_story_5071_50711501_25_dialog_content = "Apakah kamu benar-benar tidak pernah mempertimbangkan untuk memberi tahu orang-orang tentang kebenaran?",
  ui_story_5071_50711501_26_dialog_content = "Kebenaran bisa lebih menyakitkan daripada pedang pada beberapa waktu. Demi kedamaian, saya harus melanjutkan sandiwara ini tidak peduli seberapa dangkal itu mungkin.",
  ui_story_5071_50711501_27_dialog_content = "Saya tidak menyesal akan apapun—",
  ui_story_5071_50711501_28_dialog_content = "Seharusnya kau sudah menyadarinya sekarang... Tapi selama ini kau hidup dalam rasa bersalah dan penyesalan.",
  ui_story_5071_50711501_29_dialog_content = "Penyesalan karena tidak memberi tahu Tn. Valon dan Istvan yang tua tentang kebenaran.",
  ui_story_5071_50711501_30_dialog_content = "Tajam seperti biasanya, tapi bayangan lama itu sudah lama hilang. Saya tidak akan pernah memiliki kesempatan untuk berbaikan dengan mereka lagi.",
  ui_story_5071_50711501_31_dialog_content = "Itulah sebabnya kamu mulai menghukum diri sendiri... Dan menjebak dirimu sendiri dalam mimpi buruk ini...",
  ui_story_5071_50711501_32_dialog_content = "Aku telah memainkan peranku begitu lama hingga aku hampir tidak bisa membedakan lagi. Apakah aku telah menjadi satu dengan bayang-bayang, atau bayang-bayanglah yang sebenarnya memainkan peranku?",
  ui_story_5071_50711501_33_dialog_content = "Segala yang telah kulakukan... Apakah itu benar-benar cukup?",
  ui_story_5071_50711501_34_dialog_content = "Kamu sudah berkorban begitu banyak untuk Umbraton...",
  ui_story_5071_50711501_35_dialog_content = "Kalau saja aku tidak ragu, kalau saja aku menghentikan Valon saat aku punya kesempatan, mungkin kejadiannya akan berbeda—",
  ui_story_5071_50711501_36_dialog_content = "Aku tidak pernah ingin membayar harga dengan nyawanya.",
  ui_story_5071_50711501_37_dialog_content = "Heh... Jika aku masih bisa merasa seperti ini, maka tampaknya Kade yang lama masih ada dalam diriku. Setelah semua ini, aku masih sangat membutuhkan pengampunanmu, teman baikku...",
  ui_story_5071_50711501_38_dialog_content = "Heh—",
  ui_story_5071_50711501_39_dialog_content = "Hahahahahaha—",
  ui_story_5071_50711501_40_dialog_content = "Shadowlord?",
  ui_story_5071_50711501_41_dialog_content = "Mungkin saya memang sudah tua. Apakah saya benar-benar sudah kehilangan semangat masa mudaku?",
  ui_story_5071_50711501_42_dialog_content = "Bagaimana bisa aku membiarkan diriku tenggelam dalam pikiran seperti itu?",
  ui_story_5071_50711501_43_dialog_content = "Akhirnya kamu kembali sadar, Shadowlord!",
  ui_story_5071_50711501_44_dialog_content = "Belum cukup, masih belum cukup!",
  ui_story_5071_50711501_45_dialog_content = "Ada lebih banyak kemarahan yang membara untuk dilepaskan!",
  ui_story_5071_50711501_46_dialog_content = "(Emosi Shadowlord mulai stabil, tetapi aku merasakan sesuatu yang lain di hatinya. Sesuatu yang samar...)",
  ui_story_5071_50711501_47_dialog_content = "Jika bukan karena bantuanmu barusan, aku akan melupakan pelajaran dari masa lalu. Bayangan mereka ada untuk mengingatkanku agar tidak mengulangi kesalahan yang sama lagi.",
  ui_story_5071_50711501_48_dialog_content = "Tidak ada lagi basa-basi!",
  ui_story_5071_50711501_49_dialog_content = "Jika mereka menginginkan kekejaman, maka kekejamanlah yang akan mereka terima! Aku tidak akan menahan diri lagi!",
  ui_story_5071_50711501_50_dialog_content = "Kamu hampir sampai di sana, Shadowlord! Bangunlah!",
  ui_story_5071_50711501_51_dialog_content = "(Apakah berhasil? Tubuhku... Kesadaranku mulai kabur... Seperti aku sedang ditarik keluar dari sini...)",
  ui_story_5071_50711501_52_dialog_content = "Shadowlord... Aku akan menunggumu di luar...",
  ui_story_5071_50711501_53_dialog_content = "Terima kasih, Caelestite yang baik.",
  ui_story_5071_50711501_54_dialog_content = "Aku juga harus...",
  ui_story_5071_50711501_55_dialog_content = "Kade.",
  ui_story_5071_50711501_56_dialog_content = "?!",
  ui_story_5071_50711501_57_dialog_content = "Sejujurnya... sudah lama sekali.",
  ui_story_5071_50711501_58_dialog_content = "Valon...?",
  ui_story_5071_50711501_59_dialog_content = "Kade... Ada pertanyaan yang ingin kubertanyakan lagi kepadamu.",
  ui_story_5071_50711501_60_dialog_content = "Bisakah kamu menatap mataku dan menjawab dengan jujur?",
  ui_story_5071_50711501_61_dialog_content = "...",
  ui_story_5071_50711501_62_dialog_content = "Berapa harga yang kamu bersedia bayar untuk menyelamatkan Umbraton?",
  ui_story_5071_50711501_63_dialog_content = "... Apakah kamu benar-benar harus bertanya?",
  ui_story_5071_50711501_64_dialog_content = "Semuanya! Saya akan membayar semuanya!",
  ui_story_5071_50711501_65_dialog_content = "Ini sangat seperti kamu... mengatakan itu, Kade...",
  ui_story_5071_50711501_66_dialog_content = "Sekarang pergi, teman-teman! Tunjukkan kepada semua musuh Umbraton tekad kalian!",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5071_50711501_68_dialog_content = "Heh, aku tidak menyangka bisa bertahan selama ini.",
  ui_story_5071_50711501_69_dialog_content = "Pesawat ini hampir meledak. Apakah kamu benar-benar percaya Kade akan kembali?",
  ui_story_5071_50711501_70_dialog_content = "Ya. Dan PlayerName juga berjanji padaku untuk kembali bersama Shadowlord.",
  ui_story_5071_50711501_71_dialog_content = "Kade hanyalah keberadaan yang hampa... Meski dia bertahan, dia tak mungkin bisa menyelamatkanmu sekarang.",
  ui_story_5071_50711501_72_dialog_content = "Wajah aslinya hanya akan memenuhi kalian semua dengan keputusasaan.",
  ui_story_5071_50711501_73_dialog_content = "Lady Hanstie, kita sudah sampai...",
  ui_story_5071_50711501_74_dialog_content = "Lebih banyak bala bantuan bahkan sekarang?",
  ui_story_5071_50711501_75_dialog_content = "Dan bahkan mendapatkan Eclipsites untuk bertarung untuknya? Ini semakin memburuk.",
  ui_story_5071_50711501_76_dialog_content = "Konsentrasikan seranganmu! Jangan beri dia kesempatan untuk mengambil nafas!",
  ui_story_5071_50711501_77_dialog_content = "Shadowlord...",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5071_50711501_79_dialog_content = "Apa yang terjadi?",
  ui_story_5071_50711501_80_dialog_content = "Tiba-tiba ada ledakan besar...",
  ui_story_5071_50711501_81_dialog_content = "T-Tunggu! Apa itu?",
  ui_story_5071_50711501_82_dialog_content = "Ada seseorang di dalam api... C-Mungkinkah...",
  ui_story_5071_50711501_83_dialog_content = "Shadowlord!!!",
  ui_story_5071_50711501_84_dialog_content = "Ribuan bekas luka... dan api biru yang ganas. Itulah dia...",
  ui_story_5071_50711501_85_dialog_content = "<size=45>Itu adalah iblis dari The Pit!!!</size>",
  ui_story_5071_50711501_86_dialog_content = "Dia tidak bisa dikalahkan... Dia adalah legenda yang tak terkalahkan... Bagaimana kita bisa...",
  ui_story_5071_50711501_87_dialog_content = "Jangan lari, pengecut! Tujuan kita adalah untuk membalas dendam pada pria itu!",
  ui_story_5071_50711501_88_dialog_content = "Seberapapun tua dia sekarang, tidak mungkin dia bisa mengalahkan sebanyak ini lawan...",
  ui_story_5071_50711501_89_dialog_content = "Bahkan setelah semua ini, kau masih ingin kabur?",
  ui_story_5071_50711501_90_dialog_content = "K-Kami tidak akan membiarkanmu!",
  ui_story_5071_50711501_91_dialog_content = "Kamu terlambat, Shadowlord. Apakah usia tua mulai mempengaruhimu?",
  ui_story_5071_50711501_92_dialog_content = "Maafkan saya, Sheol. Kamu benar— selama ini saya terjebak di balik topeng yang sedih.",
  ui_story_5071_50711501_93_dialog_content = "Tapi sekarang, saya rasa sudah waktunya untuk membiarkan bayanganku yang lama kembali.",
  ui_story_5071_50711501_94_dialog_content = "Ava... Kegaguan inilah yang membuatku kehilangan Valon.",
  ui_story_5071_50711501_95_dialog_content = "Tapi aku tidak akan ragu lagi— Bahkan jika kamu adalah musuhku.",
  ui_story_5071_50711501_96_dialog_content = "Diam! Kau tak berhak menyebut nama Valon!",
  ui_story_5071_50711501_97_dialog_content = "Ketika insiden ini dimulai, aku tahu kamu terlibat sejak awal—",
  ui_story_5071_50711501_98_dialog_content = "Kamu bebas mencari pembalasan terhadapku, tapi seharusnya kamu membiarkan orang-orang yang tidak bersalah.",
  ui_story_5071_50711501_99_dialog_content = "Diam! Tutup mulutmu! Kamu tidak tahu betapa banyaknya penderitaan yang telah aku alami!",
  ui_story_5071_50711501_100_dialog_content = "Aku telah melakukan begitu banyak hal yang tak terkatakan, semua untuk momen ini!",
  ui_story_5071_50711501_101_dialog_content = "Saya melukis begitu banyak pemalsuan menjijikkan demi uang... Dan untuk membongkarmu, saya melakukan begitu banyak eksperimen menjijikkan...",
  ui_story_5071_50711501_102_dialog_content = "Semua kekuatan dan orang-orang yang telah saya kumpulkan selama bertahun-tahun, hanya agar kita bisa membalas dendam!",
  ui_story_5071_50711501_103_dialog_content = "Rencanamu gagal. Pikiran Shadowlord sekarang sangat stabil; dia tidak akan pernah kehilangan kendali lagi!",
  ui_story_5071_50711501_104_dialog_content = "Apakah begitu? Baiklah... Jika kamu bersikeras mempertahankan penyamaranmu yang tidak berguna itu...",
  ui_story_5071_50711501_105_dialog_content = "Maka aku akan menenangkan roh Valon dengan membunuhmu sendiri!",
  ui_story_5071_50711501_106_dialog_content = "Kalian semua, serang!",
  ui_story_5071_50711501_107_dialog_content = "Apakah ini semua bantuan yang bisa kau dapatkan dari orang-orang menyedihkan yang menjual diri ini?",
  ui_story_5071_50711501_108_dialog_content = "Urgh—",
  ui_story_5071_50711501_109_dialog_content = "Jangan meremehkan kami, Ava!",
  ui_story_5071_50711501_110_dialog_content = "K-Kita bukan tandingannya. Lari!",
  ui_story_5071_50711501_111_dialog_content = "Kegelapan yang pernah Valon dan saya taklukkan di masa lalu jauh lebih besar dari apa pun yang pernah kamu lihat!",
  ui_story_5071_50711501_112_dialog_content = "K-Kau monster...",
  ui_story_5071_50711501_113_dialog_content = "Sh-Sh-Shadowlord menjadi liar—",
  ui_story_5071_50711501_114_dialog_content = "Sekarang semua anugerah telah diabaikan, bersiaplah untuk memohon belas kasihan!",
  ui_story_5071_50711501_115_dialog_content = "B-Bagaimana ini bisa terjadi?! Tubuhnya dipenuhi luka, jadi kenapa dia...",
  ui_story_5071_50711501_116_dialog_content = "Terus serang! Dia pasti sudah kehilangan kekuatan sekarang!",
  ui_story_5071_50711501_117_dialog_content = "Kehilangan kekuatan? Aku baru saja pemanasan!",
  ui_story_5071_50711501_118_dialog_content = "S-Semua telah terbakar menjadi abu... Pria ini tak lekang oleh waktu...",
  ui_story_5071_50711501_119_dialog_content = "Graaaaaaaaagh!!!",
  ui_story_5071_50711501_120_dialog_content = "Inilah yang dia sembunyikan, penampilan yang berkobar dalam kekacauan...",
  ui_story_5071_50711501_121_dialog_content = "Apakah kamu bahagia sekarang?",
  ui_story_5071_50711501_122_dialog_content = "Selamat, ini adalah binatang yang kamu inginkan, 'kan?",
  ui_story_5071_50711501_123_dialog_content = "C-Cepat! Bawa benda itu keluar sekarang!!!",
  ui_story_5071_50711501_124_dialog_content = "Saya akan membayar berapapun harganya, jadi keluarkan saja...",
  ui_story_5071_50711501_125_dialog_content = "<size=50>Ava—!!!</size>",
  ui_story_5071_50711502_1_dialog_content = "Apakah kalian semua melihat itu? Bahkan Eclipsite itu tidak bisa menghentikannya. Istvan adalah monster yang sebenarnya!",
  ui_story_5071_50711502_2_dialog_content = "Mau kabur, ya?",
  ui_story_5071_50711502_3_dialog_content = "Jangan mendekat—",
  ui_story_5071_50711502_4_dialog_content = "!",
  ui_story_5071_50711502_5_dialog_content = "Valon...",
  ui_story_5071_50711502_6_dialog_content = "Apakah Anda ingin saya menyelamatkannya?",
  ui_story_5071_50711502_7_dialog_content = "Tolong—",
  ui_story_5071_50711502_8_dialog_content = "Kamu menyedihkan, Ava!",
  ui_story_5071_50711502_9_dialog_content = "Tidak...",
  ui_story_5071_50711502_10_dialog_content = "Menyerahlah. Aku tidak akan menyakitimu, tetapi kamu akan mendapatkan keadilan yang pantas kamu terima.",
  ui_story_5071_50711502_11_dialog_content = "Aku akan melanjutkan mimpi Valon, mimpi kita.",
  ui_story_5071_50711502_12_dialog_content = "Mimpi itu... jelas sudah hancur...",
  ui_story_5071_50711502_13_dialog_content = "Sayang sekali, Ava, aku tidak pernah menyangka kamu akan jatuh sejauh ini.",
  ui_story_5071_50711502_14_dialog_content = "Terutama saat kau menjadi milik Valon...",
  ui_story_5071_50711502_15_dialog_content = "Jangan katakan itu padaku. Aku tidak butuh simpatimu!",
  ui_story_5071_50711502_16_dialog_content = "Kamu tidak bisa mencapai sejauh ini tanpa banyak bantuan.",
  ui_story_5071_50711502_17_dialog_content = "Orang-orang yang membenciku telah memanfaatkanmu... Sungguh tak bisa dimaafkan!",
  ui_story_5071_50711502_18_dialog_content = "...",
  ui_story_5071_50711502_19_dialog_content = "Jika kamu tidak mau membocorkan, saya akan mencari tahu siapa mereka dengan caraku sendiri.",
  ui_story_5071_50711502_20_dialog_content = "Tapi saya berjanji pada Anda, Anda akan mendapatkan pengadilan yang adil.",
  ui_story_5071_50711502_21_dialog_content = "Berhenti meneteskan air mata buaya. Itu menjijikkan!",
  ui_story_5071_50711502_22_dialog_content = "Kau membunuh Valon dan mengambil segalanya darinya, namun kau tidak dihukum.",
  ui_story_5071_50711502_23_dialog_content = "Mengapa kami harus menjadi anak domba pengorbananmu?",
  ui_story_5071_50711502_24_dialog_content = "Aku mengutukmu! May hatimu terperangkap selamanya di dalam jurang!",
  ui_story_5071_50711502_25_dialog_content = "...Sangat lama yang lalu, Valon dan saya sama-sama berharap ada hukum dan aturan di Umbraton.",
  ui_story_5071_50711502_26_dialog_content = "Dia mendambakan tatanan baru dan mempercayakan impian itu padaku.",
  ui_story_5071_50711502_27_dialog_content = "Jika memungkinkan, saya lebih suka tidak menahanmu.",
  ui_story_5071_50711502_28_dialog_content = "Valon...",
  ui_story_5071_50711502_29_dialog_content = "Anda mendirikan Continental Guild untuk Valon, bukan?",
  ui_story_5071_50711502_30_dialog_content = "Meski penuh kebencian, karena cinta kamu masih tetap mempertahankan yang murni itu...",
  ui_story_5071_50711502_31_dialog_content = "Cukup, berhenti...",
  ui_story_5071_50711502_32_dialog_content = "Aku telah bersembunyi dalam bayangan cukup lama untuk mengetahui jenis orang mana yang tidak bisa ditolong.",
  ui_story_5071_50711502_33_dialog_content = "Ava, masih ada kepolosan di hatimu.",
  ui_story_5071_50711502_34_dialog_content = "Itu adalah bayangan dari masa lalumu.",
  ui_story_5071_50711502_35_dialog_content = "Oleh karena itu, aku berjanji padamu di sini dan sekarang—",
  ui_story_5071_50711502_36_dialog_content = "Suatu hari, ketika kamu telah menebus dosa-dosamu dan aku selesai mereformasi Umbraton...",
  ui_story_5071_50711502_37_dialog_content = "Anda dipersilakan untuk mengambil nyawa saya.",
  ui_story_5071_50711502_38_dialog_content = "Kamu...",
  ui_story_5071_50711502_39_dialog_content = "Tenang, saya melihat para Guardian datang dengan regu penyelamatan.",
  ui_story_5071_50711502_40_dialog_content = "Katakan apa pun yang tersisa padamu kepada mereka.",
  ui_story_5071_50711502_41_dialog_content = "... Biarkan aku pergi!",
  ui_story_5071_50711502_42_dialog_content = "Kenapa harus aku?",
  ui_story_5071_50711502_43_dialog_content = "Tukang daging yang sebenarnya ada tepat di depan Anda!",
  ui_story_5071_50711502_44_dialog_content = "Lihat dia, lihat bekas luka jelek itu! Kau tidak mengerti, 'kan?",
  ui_story_5071_50711502_45_dialog_content = "Dia adalah pendosa dan musuh terbesar Umbraton!",
  ui_story_5071_50711502_46_dialog_content = "Apakah kamu lupa bagaimana ibumu meninggal?",
  ui_story_5071_50711502_47_dialog_content = "...",
  ui_story_5071_50711502_48_dialog_content = "Aku benar-benar tidak cocok untuk ini. Cepatlah, Guardians!",
  ui_story_5071_50711502_49_dialog_content = "Kalian semua melihatnya, bukan?",
  ui_story_5071_50711502_50_dialog_content = "Gemetarlah dalam ketakutan, semuanya dan semua yang ingin tetap di sisinya!",
  ui_story_5071_50711502_51_dialog_content = "Kebenaran akan terungkap suatu hari nanti!",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>Aku mengutukmu, Kade!</color>",
  ui_story_5071_50711601_1_dialog_content = "Penyebab kematian Yvonne akhirnya diungkap ke publik dan ternyata adalah racun. Dia masih berada di puncak ketika Hanstie membunuhnya.",
  ui_story_5071_50711601_2_dialog_content = "Saya menyesal tidak memiliki lebih banyak percakapan dengan dia.",
  ui_story_5071_50711601_3_dialog_content = "Dia adalah orang yang baik...",
  ui_story_5071_50711601_4_dialog_content = "Vergil juga sangat terpukul dan tidak tidur atau makan selama beberapa hari. Saya harus memberikan lebih banyak pekerjaan untuk mengalihkan pikirannya.",
  ui_story_5071_50711601_5_dialog_content = "Saya rasa Anda tidak seharusnya membebani dia seperti itu, Lady Sheol...",
  ui_story_5071_50711601_6_dialog_content = "Untuk mengenang Ms. Yvonne, kami merilis buku-bukunya. Ini adalah batch pertama.",
  ui_story_5071_50711601_7_dialog_content = "Tolong kirimkan beberapa salinan ke Shadowlord.",
  ui_story_5071_50711601_8_dialog_content = "Aku yakin itu akan membuat Shadowlord sangat senang... Hah? Apa itu semua buku di belakangmu?",
  ui_story_5071_50711601_9_dialog_content = "Oh, itu! Itu adalah cetakan baru dari Nyonya Red Mercury, seri favorit saya.",
  ui_story_5071_50711601_X9_dialog_content = "Bunga lili di sampul ini begitu sederhana dan indah... Sangat cocok untuk Nyonya Red Mercury... dan juga ibumu...",
  ui_story_5071_50711601_X10_dialog_content = "Kenangan abadi, cinta yang tak terhingga, dan berkah yang mendalam. Itulah yang disimbolkan oleh bunga lili.",
  ui_story_5071_50711601_X11_dialog_content = "... Tidak ada pertanyaan?",
  ui_story_5071_50711601_X12_dialog_content = "Kamu sudah menceritakan tentang ibuku, kan?",
  ui_story_5071_50711601_X13_dialog_content = "Ya.",
  ui_story_5071_50711601_X14_dialog_content = "Lalu apa yang harus ditanyakan?",
  ui_story_5071_50711601_X15_dialog_content = "... Kebenaran adalah pedang bermata dua. Kadang, aku memilih kebohongan putih.",
  ui_story_5071_50711601_X16_dialog_content = "Ibumu memang meninggal karena sakit, dari depresi yang dia alami saat mencoba mencarimu.",
  ui_story_5071_50711601_X17_dialog_content = "Saya mengunjunginya di ranjang kematiannya dan mendengar permintaan terakhirnya.",
  ui_story_5071_50711601_X18_dialog_content = "Ini adalah cinta besar seorang ibu kepada putrinya. Aku tidak ingin kamu merasa bersalah, jadi...",
  ui_story_5071_50711601_X19_dialog_content = "Bisakah saya menganggap itu sebagai bantuan lain yang kamu berutang padaku?",
  ui_story_5071_50711601_X20_dialog_content = "... Cuma bercanda. Terima kasih, Paman.",
  ui_story_5071_50711601_X21_dialog_content = "Jangan lakukan itu lagi.",
  ui_story_5071_50711601_X22_dialog_content = "Kebijakan jujur seharusnya diterapkan dalam berbisnis di Umbraton.",
  ui_story_5071_50711601_X23_dialog_content = "Haha, saya akan ingat saran itu, Lady Sheol.",
  ui_story_5071_50711601_X24_dialog_content = "Ibu pasti akan senang mengetahui bahwa bunga lili juga sangat cocok untukku!",
  ui_story_5071_50711601_10_dialog_content = "Sayang sekali, saya terlalu sibuk untuk membacanya dengan tenang.",
  ui_story_5071_50711601_11_dialog_content = "Sayang sekali apa yang terjadi pada pesawatnya...",
  ui_story_5071_50711601_12_dialog_content = "Tidak apa-apa, bukan pertama kalinya hal itu terjadi padaku. Ada yang menang, ada yang kalah. Begitulah jalannya bisnis.",
  ui_story_5071_50711601_13_dialog_content = "Saya bebas berbisnis di mana saja tanpa pesawat sekalipun.",
  ui_story_5071_50711601_14_dialog_content = "Saya lega mendengar itu dan melihat betapa optimisnya Anda tentang segala hal, Lady Sheol! Jaga diri!",
  ui_story_5071_50711601_15_dialog_content = "Aku senang PlayerName sayangku sedang menghiburku, tapi melakukannya dengan membawa Colossus-mu sedikit menggangguku.",
  ui_story_5071_50711601_16_dialog_content = "Maaf—",
  ui_story_5071_50711601_17_dialog_content = "Baiklah…",
  ui_story_5071_50711601_18_dialog_content = "Kamu pergi dan terbang dengan bangga membawa mimpi-mimpi kita...",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5071_50711601_20_dialog_content = "Memasuki.",
  ui_story_5071_50711601_21_dialog_content = "Ini aku, Shadowlord. Aku datang untuk mengantarkan beberapa buku— Hah?",
  ui_story_5071_50711601_22_dialog_content = "Apa itu? Apakah penampilanku membuatmu takut?",
  ui_story_5071_50711601_23_dialog_content = "Ada apa?",
  ui_story_5071_50711601_24_dialog_content = "Asap di bayangan belum juga mereda— Sesuatu memberitahuku bahwa pertarungan ini belum berakhir.",
  ui_story_5071_50711601_25_dialog_content = "... Aku akan meninggalkan buku-buku ini di sini saja.",
  ui_story_5071_50711601_26_dialog_content = "Sheol benar-benar menikmati mengirimkanmu untuk urusan seperti ini... Terima kasih.",
  ui_story_5071_50711601_27_dialog_content = "Apakah kamu masih mengalami mimpi buruk akhir-akhir ini?",
  ui_story_5071_50711601_28_dialog_content = "Haha, itu semua tergantung bagaimana kamu mendefinisikan \"mimpi buruk.\" Dulu aku adalah tawanan rasa bersalahku, dan mimpiku penuh dengan kenangan masa lalu yang terdistorsi.",
  ui_story_5071_50711601_29_dialog_content = "Tapi sekarang aku hanya bermimpi tentang kebenaran yang polos. Apakah kamu akan menyebut mimpiku sekarang sebagai \"mimpi buruk\"?",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_5071_50711601_31_dialog_content = "Tolong tetap di sini. Tidak perlu pergi.",
  ui_story_5071_50711601_32_dialog_content = "Masuk—",
  ui_story_5071_50711601_33_dialog_content = "Lord Istvan! Lord Istvan!",
  ui_story_5071_50711601_34_dialog_content = "Tuan yang terhormat Istvan... Tolong terima penghormatan saya. Anda seharusnya mengingat saya. Kita pernah menjadi mitra.",
  ui_story_5071_50711601_35_dialog_content = "Jika kamu ingat persahabatan kita, tolong dengarkan pengakuan tulus dari hatiku...",
  ui_story_5071_50711601_36_dialog_content = "Bicaralah.",
  ui_story_5071_50711601_37_dialog_content = "Aku sempat ragu di Airship Cloudrover dan bertindak tidak pantas bersama beberapa teman yang buruk...",
  ui_story_5071_50711601_38_dialog_content = "Ketika Guild menutup mereka, guild kami juga akan... Tolong percaya saya! Saya benar-benar bertobat!",
  ui_story_5071_50711601_39_dialog_content = "Jadi... Mohon tunjukkan belas kasihan dan izinkan saya kembali ke Guild.",
  ui_story_5071_50711601_40_dialog_content = "Kamu bilang kita adalah mitra.",
  ui_story_5071_50711601_41_dialog_content = "Tapi ketika reformasi dimulai, kamu bersembunyi dari bayangan karena takut terlibat dengan saya.",
  ui_story_5071_50711601_42_dialog_content = "Tidak, itu bukan yang terjadi.",
  ui_story_5071_50711601_43_dialog_content = "Diam-diam, kamu dan rekan-rekanmu meraup banyak keuntungan melalui bisnis bawah tanahmu...",
  ui_story_5071_50711601_44_dialog_content = "Dalam momen paling gemilangmu, kamu tidak pernah mempertimbangkan saran saya.",
  ui_story_5071_50711601_45_dialog_content = "Hanya setelah Guild menyetujui bisnismu, kau datang padaku mencari pengampunan.",
  ui_story_5071_50711601_46_dialog_content = "A-Aku karena...",
  ui_story_5071_50711601_47_dialog_content = "Jangan beri saya alasan— Tidak pernah sekalipun Anda menghormati saya atau menganggap saya sebagai mitra bisnis.",
  ui_story_5071_50711601_48_dialog_content = "Dalam pandanganmu, Shadowlord hanyalah halangan yang harus diatasi.",
  ui_story_5071_50711601_49_dialog_content = "Bukan... bukan itu. Tolong dengarkan aku!",
  ui_story_5071_50711601_50_dialog_content = "Aku akan memulai lembaran baru! Aku tidak akan bersekongkol dengan orang-orang itu lagi. Aku akan meninggalkan bisnis bawah tanahku!",
  ui_story_5071_50711601_51_dialog_content = "Mohon minta Guild untuk bersikap lunak terhadap kami! Berikan kami jalan keluar. Saya memohon kepada Anda, Shadowlord!",
  ui_story_5071_50711601_52_dialog_content = "Pergi.",
  ui_story_5071_50711601_53_dialog_content = "Lalu... bagaimana dengan guildku... Shadowlord?",
  ui_story_5071_50711601_54_dialog_content = "...",
  ui_story_5071_50711601_55_dialog_content = "Ya! Ya! Aku akan tersesat sekarang! Aku pergi sekarang...",
  ui_story_5071_50711601_56_dialog_content = "Maaf kau harus menyaksikan itu.",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>(Dia bahkan lebih mengancam daripada sebelumnya!!!)</color>",
  ui_story_5071_50711601_58_dialog_content = "Jujur saja, bahkan aku sendiri merasa sedikit takut melihatmu seperti ini...",
  ui_story_5071_50711601_59_dialog_content = "Hahaha! Tolong buang pikiran itu, temanku— Saya hanya ingin bermain catur bersamamu.",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5071_50711601_61_dialog_content = "Ayah...",
  ui_story_5071_50711601_62_dialog_content = "... Masuklah.",
  ui_story_5071_50711601_63_dialog_content = "Hasil jajak pendapat telah keluar. Tidak ada yang menentang rancangan undang-undang reformasi.",
  ui_story_5071_50711601_64_dialog_content = "Apakah aku benar-benar memberikan penampilan yang begitu tirani?",
  ui_story_5071_50711601_65_dialog_content = "Bukan maksud saya untuk melakukannya, tetapi saya tidak akan menyangkal kegunaannya dalam negosiasi.",
  ui_story_5071_50711601_66_dialog_content = "Haha, saya rasa memang membuat masalah yang rumit menjadi lebih sederhana.",
  ui_story_5071_50711601_67_dialog_content = "Juga, Ayah, kami memiliki temuan awal tentang siapa yang berada di balik Hanstie.",
  ui_story_5071_50711601_68_dialog_content = "Sepertinya mereka akan melakukan lebih banyak kenakalan. Berikut adalah berkas-berkasnya.",
  ui_story_5071_50711601_69_dialog_content = "Biarkan mereka datang.",
  ui_story_5071_50711601_70_dialog_content = "Aku siap untuk setiap pertempuran yang mereka bawa kepada kita. Aku tidak akan bersembunyi lagi.",
  ui_story_5071_50711601_71_dialog_content = "Umbraton tidak lagi selemah dulu. Kota kami siap menyambut tamu seperti mereka kapan saja.",
  ui_story_5071_50711601_72_dialog_content = "Kleken.",
  ui_story_5071_50711601_73_dialog_content = "Ya, tuan ku?",
  ui_story_5071_50711601_74_dialog_content = "Beritahu mereka untuk mulai persiapan. Kita memiliki banyak pekerjaan di depan kita.",
  ui_story_5071_50711601_75_dialog_content = "Mengerti. Saya akan mulai menyiapkan untuk jamuan makan—",
  ui_story_5071_50711601_76_dialog_content = "Harap tenang, Ayah.",
  ui_story_5071_50711601_77_dialog_content = "Kamu terluka dan diracuni. Kamu harus beristirahat sebanyak mungkin.",
  ui_story_5071_50711601_78_dialog_content = "(Huh? Bahkan sikap Bethel tampak sedikit lebih santai sekarang. Mereka hampir tampak seperti ayah dan anak perempuan yang normal...)",
  ui_story_5071_50711601_79_dialog_content = "Aku masih belum sebegitu tuanya, Bethel. Biarkan aku melanjutkan pekerjaanku.",
  ui_story_5071_50711601_80_dialog_content = "Maaf, tapi aku harus pergi—",
  ui_story_5071_50711601_81_dialog_content = "Aku yakin kalian semua punya banyak pekerjaan yang harus dilakukan, jadi aku akan pergi sekarang.",
  ui_story_5071_50711601_82_dialog_content = "Mohon maafkan aku, aku hanya ingin bermain pertandingan denganmu hari ini.",
  ui_story_5071_50711601_83_dialog_content = "Sampai jumpa lagi, teman saya.",
  ui_story_5071_50711601_84_dialog_content = "Dah—",
  ui_story_5071_50711601_85_dialog_content = "Apa yang telah kau lakukan pada ayahku?",
  ui_story_5071_50711601_86_dialog_content = "Kami semua terkagum dengan perubahan yang ada padanya.",
  ui_story_5071_50711601_87_dialog_content = "S-saya tidak melakukan apa-apa! Shadowlord hanya sampai pada beberapa kesadaran sendiri, saya janji!",
  ui_story_5071_50711601_88_dialog_content = "Benarkah?",
  ui_story_5071_50711601_89_dialog_content = "Oke. Dia tampak lebih jujur dan ramah sekarang. Saya sangat menyukai itu.",
  ui_story_5071_50711601_90_dialog_content = "Lady Bethel, ada lebih banyak komunikasi masuk dan pertemuan baru yang perlu Anda selenggarakan.",
  ui_story_5071_50711601_91_dialog_content = "Aku datang. Terima kasih, PlayerName, dan sampai jumpa di lain waktu.",
  ui_story_5071_50711601_92_dialog_content = "Tidak masalah. Sampai jumpa!",
  ui_story_5071_50711601_93_dialog_content = "Cepat, berikan usaha ekstra! Bos sedang menunggu kita!",
  ui_story_5071_50711601_94_dialog_content = "Ayo, ayo, ayo—!",
  ui_story_5071_50711601_95_dialog_content = "(Mereka tampak cukup bersemangat...)",
  ui_story_5071_50711601_96_dialog_content = "Masih belum tahu siapa yang kita kejar, tapi maju!",
  ui_story_5071_50711601_97_dialog_content = "(Matahari begitu terang hari ini. Pernahkah secerah ini di Umbraton?)",
  ui_story_5071_50711601_98_dialog_content = "Hati-hati! Mohon perhatikan lalu lintas meskipun Anda sedang mengangkut material bangunan sekolah!",
  ui_story_5071_50711601_99_dialog_content = "(Umbraton terlihat indah di bawah sinar matahari—)",
  ui_story_5071_50711601_100_dialog_content = "Cepatlah dan bawa barang-barang yang diinginkan tamu ke kendaraan pengiriman...",
  ui_story_5071_50711601_101_dialog_content = "Jangan beri kesan kepada orang-orang bahwa Umbraton Guild itu lambat!",
  ui_story_5071_50711601_102_dialog_content = "Sepertinya semua orang ingin menikmati cuaca baik hari ini.",
  ui_story_5071_50711601_103_dialog_content = "Mungkin aku harus pergi nonton film dengan Vice? Semoga masih ada beberapa tiket tersisa...",
  ui_story_5071_50711601_104_dialog_content = "Buku ini...",
  ui_story_5071_50711601_105_dialog_content = "Ya... Ini sangat cocok untuk membaca di bawah sinar matahari.",
  ui_story_5071_50711601_106_dialog_content = "Heh, dan kebetulan hari ini matahari bersinar sangat terang. Kota kita juga...",
  ui_story_5071_50711601_107_dialog_content = "Sama seperti yang selalu kita impikan—",
  ui_story_5071_50711601_108_dialog_content = "Bukankah begitu, teman lama ku?",
  ui_story_5071_50711601_109_dialog_content = "Sepertinya semuanya sudah ditangani dengan baik. Akhirnya, segala sesuatu sudah beres sekarang.",
  ui_story_5071_50711601_110_dialog_content = "Setelah bertahun-tahun, ternyata aku telah belajar banyak—",
  ui_story_5071_50711601_111_dialog_content = "Sepertinya aku seorang guru yang baik.",
  ui_story_5071_50711601_112_dialog_content = "Sangat indah... Aku tidak pernah menyadari bahwa kampung halaman kita bisa secerah ini...",
  ui_story_5071_50711601_113_dialog_content = "Setelah hari ini, impian kita untuk Umbraton hanya akan semakin kuat, dan...",
  ui_story_5071_50711601_114_dialog_content = "Mereka pasti akan bisa mengepakkan sayap dan terbang suatu hari nanti...",
  ui_story_5071_50711601_115_dialog_content = "Saya menantikan hari itu."
}
return config
